const a=1,n="tnxh",i="Tự nhiên và Xã hội lớp 1",t="internal",h=[{id:"gia-dinh",title:"Gia đình",lessons:[{id:"tnxh1-gia-dinh-em",title:"Gia đình em",weeks:[1,2],learn:[{title:"Các thành viên",text:"Gia đình có thể có ông bà, bố mẹ, anh chị em và em.",example:"👴 👵 👨 👩 👦 👧"},{title:"Yêu thương nhau",text:"Mọi người trong gia đình yêu thương, quan tâm, giúp đỡ nhau.",example:"🤗 ❤️"},{title:"Em làm gì?",text:"Em lễ phép với ông bà, bố mẹ và giúp đỡ việc nhà vừa sức.",example:"🙇 🧹 🍽️"}],practice:[{questions:[{id:"tnxh1-gia-dinh-em-01",type:"mc",q:"Mẹ của bố em, em gọi là gì?",emoji:"👵",options:["Bà ngoại","Bà nội","Cô"],answer:1,explain:"Mẹ của bố là bà nội."},{id:"tnxh1-gia-dinh-em-02",type:"mc",q:"Mẹ của mẹ em, em gọi là gì?",emoji:"👵",options:["Bà ngoại","Dì của em","Bà nội"],answer:0,explain:"Mẹ của mẹ là bà ngoại."},{id:"tnxh1-gia-dinh-em-03",type:"mc",q:"Bố của bố em, em gọi là gì?",emoji:"👴",options:["Chú","Ông ngoại","Ông nội"],answer:2,explain:"Bố của bố là ông nội."},{id:"tnxh1-gia-dinh-em-04",type:"tf",q:"Gia đình là nơi mọi người yêu thương nhau.",emoji:"🏠❤️",answer:!0,explain:"Đúng. Gia đình là nơi mọi người yêu thương, chăm sóc nhau."},{id:"tnxh1-gia-dinh-em-05",type:"tf",q:"Chỉ có bố mẹ mới cần giúp đỡ nhau, trẻ em thì không.",emoji:"🤝",answer:!1,explain:"Sai. Ai trong nhà cũng giúp đỡ nhau, kể cả em."},{id:"tnxh1-gia-dinh-em-06",type:"match",q:"Nối mỗi người với cách gọi đúng.",pairs:[["👴","Ông"],["👵","Bà"],["👨","Bố"],["👩","Mẹ"]],explain:"Ông, bà, bố, mẹ là những người thân trong gia đình."},{id:"tnxh1-gia-dinh-em-07",type:"multi",q:"Ai là người thân trong gia đình em?",emoji:"👨‍👩‍👧‍👦",options:["Bố mẹ","Anh chị em","Người bán hàng","Ông bà"],answers:[0,1,3],explain:"Ông bà, bố mẹ, anh chị em là người thân. Người bán hàng không phải người trong gia đình."},{id:"tnxh1-gia-dinh-em-08",type:"mc",q:"Khi đi học về, em nên làm gì?",emoji:"🎒",options:["Ném cặp xuống đất","Chào ông bà, bố mẹ","Im lặng vào phòng"],answer:1,explain:"Đi học về, em chào ông bà, bố mẹ để thể hiện lễ phép."}]},{questions:[{id:"tnxh1-gia-dinh-em-09",type:"mc",q:"Vì sao em cần lễ phép với ông bà, bố mẹ?",emoji:"🙇",options:["Vì em muốn được ông bà, bố mẹ cho thật nhiều quà","Vì em sợ bị ông bà, bố mẹ phạt","Vì ông bà, bố mẹ yêu thương, chăm sóc em"],answer:2,explain:"Ông bà, bố mẹ yêu thương, chăm sóc em nên em kính trọng, lễ phép."},{id:"tnxh1-gia-dinh-em-10",type:"tf",q:"Bố của mẹ em là ông nội.",emoji:"👴",answer:!1,explain:"Sai. Bố của mẹ là ông ngoại, bố của bố mới là ông nội."},{id:"tnxh1-gia-dinh-em-11",type:"tf",q:"Em gái của bố, em gọi là dì.",emoji:"👩",answer:!1,explain:"Sai. Em gái của bố, em gọi là cô. Dì là em gái của mẹ."},{id:"tnxh1-gia-dinh-em-12",type:"multi",q:"Việc nào thể hiện em yêu thương người thân?",emoji:"❤️",options:["Cãi lại bố mẹ","Giúp mẹ nhặt rau","Tranh đồ chơi với em bé","Hỏi han khi ông bà mệt"],answers:[1,3],explain:"Hỏi han, giúp đỡ là yêu thương. Tranh giành, cãi lại thì không."},{id:"tnxh1-gia-dinh-em-13",type:"match",q:"Nối mỗi tình huống với việc em nên làm.",pairs:[["👵 Bà bị mệt","Lấy nước cho bà"],["👩 Mẹ nấu cơm","Nhặt rau giúp mẹ"],["👶 Em bé buồn","Chơi cùng em bé"]],explain:"Em quan tâm, giúp đỡ người thân bằng những việc vừa sức."},{id:"tnxh1-gia-dinh-em-14",type:"mc",q:"Gia đình Lan có ông bà, bố mẹ, Lan và em trai. Gia đình Lan có mấy thế hệ?",emoji:"👴👨👧",options:["Ba thế hệ","Hai thế hệ","Một thế hệ"],answer:0,explain:"Ông bà, bố mẹ và các con là ba thế hệ."},{id:"tnxh1-gia-dinh-em-15",type:"tf",q:"Gia đình nào cũng phải có đúng bốn người.",emoji:"🏠",answer:!1,explain:"Sai. Mỗi gia đình có số người khác nhau."},{id:"tnxh1-gia-dinh-em-16",type:"mc",q:"Gia đình Nam có bố, mẹ và Nam. Gia đình Nam có mấy thế hệ?",emoji:"👨👩👦",options:["Bốn thế hệ","Hai thế hệ","Ba thế hệ"],answer:1,explain:"Bố mẹ và con là hai thế hệ."}]},{questions:[{id:"tnxh1-gia-dinh-em-17",type:"mc",q:"Bà nội bị mệt. Em nên làm gì?",emoji:"🤒",options:["Bật ti vi thật to cho bà cùng xem","Chạy nhảy ồn ào ở phòng của bà","Hỏi thăm và lấy nước cho bà"],answer:2,explain:"Khi bà mệt, em hỏi thăm, giữ yên lặng và giúp bà."},{id:"tnxh1-gia-dinh-em-18",type:"mc",q:"Em bé đòi chơi đồ chơi của em. Em nên làm gì?",emoji:"🧸",options:["Cùng chơi chung với em bé","Mắng em bé và không cho chơi","Giật lại đồ chơi rồi cất đi"],answer:0,explain:"Anh chị nhường nhịn và chơi chung với em nhỏ."},{id:"tnxh1-gia-dinh-em-19",type:"tf",q:"Mẹ đi làm về mệt, Minh rót nước mời mẹ. Minh làm đúng.",emoji:"🥤",answer:!0,explain:"Đúng. Minh biết quan tâm đến mẹ."},{id:"tnxh1-gia-dinh-em-20",type:"tf",q:"Bố đang nói chuyện, Chi chen ngang đòi mua kẹo. Chi làm đúng.",emoji:"🍬",answer:!1,explain:"Sai. Chi nên chờ bố nói xong rồi mới hỏi."},{id:"tnxh1-gia-dinh-em-21",type:"multi",q:"Cuối tuần, gia đình em có thể làm gì cùng nhau?",emoji:"🌳",options:["Đi công viên","Cãi nhau","Trồng cây","Nấu bữa cơm"],answers:[0,2,3],explain:"Đi chơi, nấu ăn, trồng cây cùng nhau giúp cả nhà vui vẻ."},{id:"tnxh1-gia-dinh-em-22",type:"order",q:"Sắp xếp các việc khi em đi học về.",emoji:"🎒",items:["Chào ông bà, bố mẹ","Cất cặp sách","Rửa tay","Ăn quà chiều"],explain:"Về nhà, em chào người thân, cất cặp, rửa tay rồi mới ăn."},{id:"tnxh1-gia-dinh-em-23",type:"mc",q:"Ông ngoại đến chơi. Em làm gì đầu tiên?",emoji:"👴",options:["Khoanh tay chào ông","Chạy đi chỗ khác","Chơi tiếp trò chơi"],answer:0,explain:"Có người thân đến, em khoanh tay chào lễ phép."},{id:"tnxh1-gia-dinh-em-24",type:"fill",q:"Mẹ của bố là bà …",emoji:"👵",answer:["nội"],loose:!0,explain:"Mẹ của bố là bà nội."}]}],challenge:{questions:[{id:"tnxh1-gia-dinh-em-25",type:"mc",q:"Ông bà nội là bố mẹ của ai?",emoji:"👴👵",options:["Của mẹ em","Của bố em","Của cô giáo"],answer:1,explain:"Ông bà nội là bố mẹ của bố em."},{id:"tnxh1-gia-dinh-em-26",type:"mc",q:"Em trai của bố, em gọi là gì?",emoji:"👨",options:["Chú","Dì","Cậu"],answer:0,explain:"Em trai của bố, em gọi là chú."},{id:"tnxh1-gia-dinh-em-27",type:"tf",q:"Em trai của mẹ, em gọi là chú.",emoji:"👨",answer:!1,explain:"Sai. Em trai của mẹ là cậu, em trai của bố mới là chú."},{id:"tnxh1-gia-dinh-em-28",type:"match",q:"Nối người thân với cách gọi.",pairs:[["Mẹ của mẹ","Bà ngoại"],["Bố của bố","Ông nội"],["Em trai của bố","Chú"],["Em gái của mẹ","Dì"]],explain:"Bên nội là họ hàng của bố, bên ngoại là họ hàng của mẹ."},{id:"tnxh1-gia-dinh-em-10",type:"tf",q:"Bố của mẹ em là ông nội.",emoji:"👴",answer:!1,explain:"Sai. Bố của mẹ là ông ngoại, bố của bố mới là ông nội."},{id:"tnxh1-gia-dinh-em-17",type:"mc",q:"Bà nội bị mệt. Em nên làm gì?",emoji:"🤒",options:["Bật ti vi thật to cho bà cùng xem","Chạy nhảy ồn ào ở phòng của bà","Hỏi thăm và lấy nước cho bà"],answer:2,explain:"Khi bà mệt, em hỏi thăm, giữ yên lặng và giúp bà."}]},summary:["Gia đình em có những người thân yêu.","Em lễ phép, yêu thương và giúp đỡ người thân."]},{id:"tnxh1-ngoi-nha",title:"Ngôi nhà của em",weeks:[2,3],learn:[{title:"Ngôi nhà",text:"Ngôi nhà là nơi cả gia đình cùng sống, ăn, ngủ và nghỉ ngơi.",example:"🏠 🏡 🏢"},{title:"Các phòng",text:"Nhà thường có phòng khách, phòng ngủ, bếp và nhà vệ sinh.",example:"🛋️ 🛏️ 🍳 🚽"},{title:"Đồ dùng",text:"Mỗi phòng có đồ dùng riêng, như giường ở phòng ngủ, nồi ở bếp.",example:"🛏️ 🍲 🪑"}],practice:[{questions:[{id:"tnxh1-ngoi-nha-01",type:"mc",q:"Cái giường thường đặt ở phòng nào?",emoji:"🛏️",options:["Bếp","Nhà vệ sinh","Phòng ngủ"],answer:2,explain:"Giường dùng để ngủ nên đặt ở phòng ngủ."},{id:"tnxh1-ngoi-nha-02",type:"mc",q:"Cái nồi thường để ở đâu?",emoji:"🍲",options:["Trên giường","Trong tủ quần áo","Trong bếp"],answer:2,explain:"Nồi dùng để nấu ăn nên để ở bếp."},{id:"tnxh1-ngoi-nha-03",type:"mc",q:"Đồ dùng nào dùng để nấu ăn?",emoji:"🍳",options:["Cái chảo","Cái chăn","Cái gối"],answer:0,explain:"Chảo dùng để nấu ăn. Gối, chăn dùng khi ngủ."},{id:"tnxh1-ngoi-nha-04",type:"tf",q:"Ngôi nhà là nơi gia đình cùng sống.",emoji:"🏠",answer:!0,explain:"Đúng. Cả nhà cùng ăn, ngủ, nghỉ ngơi ở ngôi nhà."},{id:"tnxh1-ngoi-nha-05",type:"tf",q:"Bồn cầu thường đặt ở phòng khách.",emoji:"🚽",answer:!1,explain:"Sai. Bồn cầu đặt ở nhà vệ sinh."},{id:"tnxh1-ngoi-nha-06",type:"match",q:"Nối đồ dùng với phòng.",pairs:[["🛏️ Giường","Phòng ngủ"],["🍳 Chảo","Bếp"],["🚽 Bồn cầu","Nhà vệ sinh"],["🛋️ Ghế sô-pha","Phòng khách"]],explain:"Mỗi đồ dùng đặt ở phòng phù hợp."},{id:"tnxh1-ngoi-nha-07",type:"multi",q:"Đồ dùng nào thường có trong bếp?",emoji:"🍽️",options:["Gối","Bát đĩa","Đũa","Nồi"],answers:[1,2,3],explain:"Nồi, bát đĩa, đũa dùng cho việc nấu và ăn. Gối dùng khi ngủ."},{id:"tnxh1-ngoi-nha-08",type:"mc",q:"Nhà nhiều tầng, có nhiều gia đình cùng ở gọi là gì?",emoji:"🏢",options:["Nhà sàn bằng gỗ","Lều trại","Nhà chung cư"],answer:2,explain:"Nhà chung cư cao nhiều tầng, có nhiều gia đình cùng ở."}]},{questions:[{id:"tnxh1-ngoi-nha-09",type:"mc",q:"Phòng nào cả nhà thường ngồi tiếp khách?",emoji:"🛋️",options:["Nhà vệ sinh","Phòng khách","Bếp"],answer:1,explain:"Phòng khách là nơi tiếp khách và cả nhà trò chuyện."},{id:"tnxh1-ngoi-nha-10",type:"mc",q:"Vì sao ta cần có nhà ở?",emoji:"🌧️🏠",options:["Để làm chỗ cho xe cộ đi qua","Để che mưa nắng và nghỉ ngơi","Để làm nơi bán đồ ăn"],answer:1,explain:"Nhà che mưa, che nắng và là nơi cả nhà nghỉ ngơi."},{id:"tnxh1-ngoi-nha-11",type:"tf",q:"Nhà ở thành phố và ở nông thôn có thể khác nhau.",emoji:"🏡🏢",answer:!0,explain:"Đúng. Có nhà chung cư, nhà phố, nhà có vườn, nhà sàn…"},{id:"tnxh1-ngoi-nha-12",type:"tf",q:"Cái chăn dùng để rửa bát.",emoji:"🛌",answer:!1,explain:"Sai. Chăn dùng để đắp khi ngủ."},{id:"tnxh1-ngoi-nha-13",type:"multi",q:"Đồ dùng nào thường có ở phòng ngủ?",emoji:"🛏️",options:["Gối","Giường","Chăn","Bếp ga"],answers:[0,1,2],explain:"Giường, gối, chăn dùng để ngủ. Bếp ga đặt ở bếp."},{id:"tnxh1-ngoi-nha-14",type:"match",q:"Nối đồ dùng với việc dùng nó.",pairs:[["🧹 Chổi","Quét nhà"],["🛏️ Giường","Nằm ngủ"],["🍚 Nồi cơm","Nấu cơm"]],explain:"Mỗi đồ dùng có một công dụng riêng."},{id:"tnxh1-ngoi-nha-15",type:"mc",q:"Đồ dùng nào KHÔNG thuộc bếp?",emoji:"🍳",options:["Cái thớt","Cái nồi","Cái gối"],answer:2,explain:"Gối dùng khi ngủ, không thuộc bếp."},{id:"tnxh1-ngoi-nha-16",type:"tf",q:"Nhà sàn là nhà có cột cao, sàn cách xa mặt đất.",emoji:"🛖",answer:!0,explain:"Đúng. Nhà sàn dựng trên những cột cao."}]},{questions:[{id:"tnxh1-ngoi-nha-17",type:"mc",q:"An muốn đánh răng, rửa mặt. An đi vào phòng nào?",emoji:"🪥",options:["Bếp","Phòng tắm","Phòng khách"],answer:1,explain:"Đánh răng, rửa mặt ở phòng tắm hoặc nơi rửa mặt."},{id:"tnxh1-ngoi-nha-18",type:"mc",q:"Có khách đến chơi. Em mời khách ngồi ở đâu?",emoji:"🛋️",options:["Ở nhà vệ sinh","Ở trong bếp","Ở phòng khách"],answer:2,explain:"Phòng khách là nơi mời khách ngồi."},{id:"tnxh1-ngoi-nha-19",type:"tf",q:"Bình để giày dép lên giường ngủ. Bình làm đúng.",emoji:"👟",answer:!1,explain:"Sai. Giày dép để ở kệ giày, không để lên giường."},{id:"tnxh1-ngoi-nha-20",type:"multi",q:"Những việc nào em có thể làm để giữ nhà gọn gàng?",emoji:"🧺",options:["Cất đồ chơi sau khi chơi","Gấp chăn sau khi ngủ dậy","Vứt quần áo khắp nơi"],answers:[0,1],explain:"Cất đồ chơi, gấp chăn giúp nhà gọn gàng."},{id:"tnxh1-ngoi-nha-21",type:"order",q:"Sắp xếp các việc buổi sáng khi em ngủ dậy.",emoji:"🌅",items:["Gấp chăn","Đánh răng, rửa mặt","Ăn sáng","Đi học"],explain:"Ngủ dậy em gấp chăn, vệ sinh cá nhân, ăn sáng rồi đi học."},{id:"tnxh1-ngoi-nha-22",type:"mc",q:"Ngăn tủ để quần áo. Em cất cái áo đã gấp vào đâu?",emoji:"👕",options:["Nồi cơm điện","Tủ quần áo","Tủ lạnh"],answer:1,explain:"Quần áo cất vào tủ quần áo."},{id:"tnxh1-ngoi-nha-23",type:"tf",q:"Thức ăn thừa nên được cất vào tủ lạnh.",emoji:"🧊",answer:!0,explain:"Đúng. Tủ lạnh giữ thức ăn lâu hỏng hơn."},{id:"tnxh1-ngoi-nha-24",type:"fill",q:"Cái giường đặt ở phòng …",emoji:"🛏️",answer:["ngủ"],loose:!0,explain:"Giường đặt ở phòng ngủ."}]}],challenge:{questions:[{id:"tnxh1-ngoi-nha-25",type:"match",q:"Nối mỗi việc với nơi làm việc đó trong nhà.",pairs:[["Nấu ăn","Bếp"],["Ngủ trưa","Phòng ngủ"],["Tắm","Phòng tắm"],["Tiếp khách","Phòng khách"]],explain:"Mỗi phòng dùng cho một số việc riêng."},{id:"tnxh1-ngoi-nha-26",type:"multi",q:"Những ngôi nhà nào có thể là nhà ở?",emoji:"🏘️",options:["Nhà có vườn","Bãi đỗ xe","Nhà chung cư","Nhà sàn"],answers:[0,2,3],explain:"Chung cư, nhà sàn, nhà có vườn đều là nhà ở. Bãi đỗ xe không phải nhà ở."},{id:"tnxh1-ngoi-nha-27",type:"mc",q:"Đồ dùng nào cần dùng điện?",emoji:"🔌",options:["Quạt điện","Cái gối","Cái chổi"],answer:0,explain:"Quạt điện chạy bằng điện. Chổi, gối thì không."},{id:"tnxh1-ngoi-nha-28",type:"tf",q:"Cất đồ đúng chỗ giúp em dễ tìm khi cần.",emoji:"🗄️",answer:!0,explain:"Đúng. Đồ để đúng chỗ thì dễ tìm, nhà cũng gọn gàng."},{id:"tnxh1-ngoi-nha-13",type:"multi",q:"Đồ dùng nào thường có ở phòng ngủ?",emoji:"🛏️",options:["Gối","Giường","Chăn","Bếp ga"],answers:[0,1,2],explain:"Giường, gối, chăn dùng để ngủ. Bếp ga đặt ở bếp."},{id:"tnxh1-ngoi-nha-20",type:"multi",q:"Những việc nào em có thể làm để giữ nhà gọn gàng?",emoji:"🧺",options:["Cất đồ chơi sau khi chơi","Gấp chăn sau khi ngủ dậy","Vứt quần áo khắp nơi"],answers:[0,1],explain:"Cất đồ chơi, gấp chăn giúp nhà gọn gàng."}]},summary:["Ngôi nhà là nơi gia đình cùng sống.","Nhà có nhiều phòng, mỗi phòng có đồ dùng riêng.","Em cất đồ đúng chỗ cho nhà gọn gàng."]},{id:"tnxh1-an-toan-o-nha",title:"An toàn khi ở nhà",weeks:[3,4],learn:[{title:"Đồ dùng sắc nhọn",text:"Dao, kéo nhọn có thể làm đứt tay. Em không nghịch dao, kéo.",example:"🔪 ✂️ ⚠️"},{title:"Điện và lửa",text:"Ổ điện, dây điện, bếp đang đun có thể gây nguy hiểm. Em không chạm vào.",example:"🔌 🔥 ⚠️"},{title:"Thuốc",text:"Em chỉ uống thuốc khi bố mẹ hoặc người lớn đưa cho.",example:"💊 👩"},{title:"Khi có chuyện",text:"Nếu bị đau hay thấy nguy hiểm, em gọi ngay người lớn.",example:"📣 🧑"}],practice:[{questions:[{id:"tnxh1-an-toan-o-nha-01",type:"mc",q:"Đồ dùng nào có thể làm đứt tay?",emoji:"🔪",options:["Quyển sách","Cái gối","Con dao"],answer:2,explain:"Dao sắc có thể làm đứt tay."},{id:"tnxh1-an-toan-o-nha-02",type:"mc",q:"Đồ dùng nào có thể gây bỏng?",emoji:"♨️",options:["Cái thìa nhựa nhỏ xinh","Nồi canh đang sôi","Gấu bông mềm mại"],answer:1,explain:"Nồi canh đang sôi rất nóng, có thể gây bỏng."},{id:"tnxh1-an-toan-o-nha-03",type:"tf",q:"Em không được cho ngón tay vào ổ điện.",emoji:"🔌",answer:!0,explain:"Đúng. Ổ điện có thể gây điện giật rất nguy hiểm."},{id:"tnxh1-an-toan-o-nha-04",type:"tf",q:"Em được tự lấy thuốc trong tủ để uống như kẹo.",emoji:"💊",answer:!1,explain:"Sai. Uống thuốc bừa bãi rất nguy hiểm. Chỉ uống khi người lớn đưa."},{id:"tnxh1-an-toan-o-nha-05",type:"multi",q:"Những đồ dùng nào có thể gây nguy hiểm?",emoji:"⚠️",options:["Gấu bông","Ổ điện","Con dao","Bàn là đang nóng"],answers:[1,2,3],explain:"Ổ điện, dao, bàn là nóng có thể gây nguy hiểm. Gấu bông thì không."},{id:"tnxh1-an-toan-o-nha-06",type:"match",q:"Nối đồ dùng với điều có thể xảy ra.",pairs:[["🔪 Dao","Đứt tay"],["🔌 Ổ điện","Điện giật"],["🔥 Bếp lửa","Bỏng"]],explain:"Biết nguy hiểm để tránh xa."},{id:"tnxh1-an-toan-o-nha-07",type:"mc",q:"Khi thấy dây điện bị hở, em làm gì?",emoji:"⚡",options:["Lấy tay cầm thử dây điện","Kéo dây điện ra để chơi","Tránh xa và báo người lớn"],answer:2,explain:"Dây điện hở có thể gây điện giật. Em tránh xa và báo người lớn."},{id:"tnxh1-an-toan-o-nha-08",type:"tf",q:"Leo trèo lên bậu cửa sổ cao là an toàn.",emoji:"🪟",answer:!1,explain:"Sai. Leo trèo cửa sổ cao có thể bị ngã rất nguy hiểm."}]},{questions:[{id:"tnxh1-an-toan-o-nha-09",type:"mc",q:"Vì sao em không nghịch bật lửa, diêm?",emoji:"🔥",options:["Vì có thể gây cháy và bỏng","Vì chúng rất nặng, khó cầm","Vì chúng rất đắt, dễ bị mất"],answer:0,explain:"Lửa có thể gây cháy nhà và làm bỏng người."},{id:"tnxh1-an-toan-o-nha-10",type:"tf",q:"Sàn nhà ướt không làm em trượt ngã.",emoji:"💧",answer:!1,explain:"Sai. Sàn ướt rất trơn, dễ làm em trượt ngã."},{id:"tnxh1-an-toan-o-nha-11",type:"mc",q:"Đồ vật nào trẻ nhỏ có thể nuốt phải, gây hóc?",emoji:"🪙",options:["Quả bóng to tròn","Cái gối ôm mềm","Hạt nhỏ, đồng xu"],answer:2,explain:"Đồ vật nhỏ có thể bị nuốt, gây hóc. Em không ngậm đồ vật nhỏ."},{id:"tnxh1-an-toan-o-nha-12",type:"multi",q:"Việc nào an toàn khi ở nhà?",emoji:"🏠",options:["Chơi xa khu vực bếp","Nhờ người lớn gọt hoa quả","Thò tay vào quạt đang quay"],answers:[0,1],explain:"Nhờ người lớn, chơi xa bếp là an toàn. Thò tay vào quạt có thể bị thương."},{id:"tnxh1-an-toan-o-nha-13",type:"tf",q:"Chai nước lau nhà có thể uống được.",emoji:"🧴",answer:!1,explain:"Sai. Nước lau nhà là chất độc, không được uống."},{id:"tnxh1-an-toan-o-nha-14",type:"mc",q:"Em nên chơi ở đâu cho an toàn?",emoji:"🧸",options:["Trên ban công cao, sát lan can","Cạnh bếp đang đun nấu thức ăn","Ở sân, phòng khách có người lớn"],answer:2,explain:"Chơi ở nơi rộng rãi, có người lớn trông là an toàn."},{id:"tnxh1-an-toan-o-nha-15",type:"match",q:"Nối tình huống với việc em nên làm.",pairs:[["Thấy khói bốc lên","Gọi người lớn ngay"],["Bị đứt tay","Báo bố mẹ để băng lại"],["Thấy viên thuốc rơi","Đưa cho người lớn cất"]],explain:"Gặp chuyện nguy hiểm, em báo ngay cho người lớn."},{id:"tnxh1-an-toan-o-nha-16",type:"tf",q:"Dùng kéo đầu tròn để cắt giấy là an toàn hơn kéo nhọn.",emoji:"✂️",answer:!0,explain:"Đúng. Kéo đầu tròn ít làm em bị thương."}]},{questions:[{id:"tnxh1-an-toan-o-nha-17",type:"mc",q:"Minh thấy mẹ để quên dao trên bàn. Minh nên làm gì?",emoji:"🔪",options:["Đưa dao cho em bé","Cầm dao lên chơi","Báo mẹ cất dao đi"],answer:2,explain:"Dao sắc nguy hiểm, Minh báo mẹ cất dao."},{id:"tnxh1-an-toan-o-nha-18",type:"mc",q:"Em bé đang bò gần ổ điện. Em làm gì?",emoji:"👶",options:["Đứng yên một chỗ để xem em bé","Bế em ra xa và gọi người lớn","Cho em bé chạm vào ổ điện"],answer:1,explain:"Em bé có thể bị điện giật. Em đưa bé ra xa và gọi người lớn."},{id:"tnxh1-an-toan-o-nha-19",type:"tf",q:"Hà tự bật bếp ga để nấu mì khi bố mẹ vắng nhà. Hà làm đúng.",emoji:"🔥",answer:!1,explain:"Sai. Trẻ nhỏ tự bật bếp ga có thể gây cháy, bỏng."},{id:"tnxh1-an-toan-o-nha-20",type:"tf",q:"Khi bị bỏng nhẹ, em báo ngay người lớn để được giúp đỡ.",emoji:"🩹",answer:!0,explain:"Đúng. Người lớn sẽ giúp em xử lí vết bỏng."},{id:"tnxh1-an-toan-o-nha-21",type:"multi",q:"Lan ở nhà một mình. Lan nên làm gì?",emoji:"🚪",options:["Mở cửa cho bất kì ai gõ cửa","Khóa cửa cẩn thận","Không mở cửa cho người lạ"],answers:[1,2],explain:"Ở nhà một mình, em khóa cửa và không mở cửa cho người lạ."},{id:"tnxh1-an-toan-o-nha-22",type:"order",q:"Sắp xếp các việc khi em thấy có khói trong nhà.",emoji:"💨",items:["Hô to báo người lớn","Ra khỏi chỗ có khói","Đứng ở nơi an toàn"],explain:"Thấy khói, em báo người lớn, ra khỏi chỗ có khói và đứng ở nơi an toàn."},{id:"tnxh1-an-toan-o-nha-23",type:"mc",q:"Số điện thoại nào gọi khi có cháy?",emoji:"🚒",options:["114","115","113"],answer:0,explain:"Có cháy, gọi 114. Số 113 là công an, 115 là cấp cứu."},{id:"tnxh1-an-toan-o-nha-24",type:"fill",q:"Em không cho ngón tay vào ổ …",emoji:"🔌",answer:["điện"],loose:!0,explain:"Cho tay vào ổ điện có thể bị điện giật."}]}],challenge:{questions:[{id:"tnxh1-an-toan-o-nha-25",type:"mc",q:"Người lạ gõ cửa nói là bạn của bố. Em ở nhà một mình. Em làm gì?",emoji:"🚪",options:["Mở cửa ra đi theo người đó","Mở cửa mời người đó vào nhà","Không mở cửa, gọi điện cho bố mẹ"],answer:2,explain:"Em không mở cửa cho người lạ và gọi hỏi bố mẹ."},{id:"tnxh1-an-toan-o-nha-26",type:"mc",q:"Số điện thoại nào gọi cấp cứu?",emoji:"🚑",options:["115","114","113"],answer:0,explain:"Cần cấp cứu, gọi 115."},{id:"tnxh1-an-toan-o-nha-27",type:"multi",q:"Thứ nào em KHÔNG được tự ý cho vào miệng?",emoji:"🚫",options:["Nước tẩy rửa","Thuốc lạ","Cốc nước sôi để nguội","Viên pin nhỏ"],answers:[0,1,3],explain:"Thuốc lạ, nước tẩy rửa, pin rất độc hoặc gây hóc. Nước sôi để nguội thì uống được."},{id:"tnxh1-an-toan-o-nha-28",type:"tf",q:"Rút phích cắm điện bằng tay ướt là an toàn.",emoji:"💧🔌",answer:!1,explain:"Sai. Tay ướt dễ bị điện giật."},{id:"tnxh1-an-toan-o-nha-21",type:"multi",q:"Lan ở nhà một mình. Lan nên làm gì?",emoji:"🚪",options:["Mở cửa cho bất kì ai gõ cửa","Khóa cửa cẩn thận","Không mở cửa cho người lạ"],answers:[1,2],explain:"Ở nhà một mình, em khóa cửa và không mở cửa cho người lạ."},{id:"tnxh1-an-toan-o-nha-14",type:"mc",q:"Em nên chơi ở đâu cho an toàn?",emoji:"🧸",options:["Trên ban công cao, sát lan can","Cạnh bếp đang đun nấu thức ăn","Ở sân, phòng khách có người lớn"],answer:2,explain:"Chơi ở nơi rộng rãi, có người lớn trông là an toàn."}]},summary:["Dao, kéo, điện, lửa, thuốc có thể gây nguy hiểm.","Em tránh xa đồ dùng nguy hiểm.","Gặp nguy hiểm, em báo ngay người lớn."]},{id:"tnxh1-nha-sach-dep",title:"Giữ nhà sạch đẹp",weeks:[5,6],learn:[{title:"Nhà sạch đẹp",text:"Nhà sạch sẽ, gọn gàng giúp cả nhà khỏe mạnh, vui vẻ.",example:"🏠 ✨"},{title:"Việc nhà vừa sức",text:"Em có thể quét nhà, lau bàn, gấp quần áo, tưới cây.",example:"🧹 🧽 👕 🪴"},{title:"Rác đúng chỗ",text:"Em bỏ rác vào thùng rác, không vứt rác bừa bãi.",example:"🗑️ ✅"}],practice:[{questions:[{id:"tnxh1-nha-sach-dep-01",type:"mc",q:"Dùng gì để quét nhà?",emoji:"🧹",options:["Cái chổi","Cái thìa","Cái bút"],answer:0,explain:"Chổi dùng để quét nhà."},{id:"tnxh1-nha-sach-dep-02",type:"mc",q:"Rác nên bỏ vào đâu?",emoji:"🗑️",options:["Ngoài cửa sổ","Thùng rác","Gầm giường"],answer:1,explain:"Rác phải bỏ vào thùng rác."},{id:"tnxh1-nha-sach-dep-03",type:"tf",q:"Nhà sạch sẽ giúp cả nhà khỏe mạnh.",emoji:"✨",answer:!0,explain:"Đúng. Nhà sạch ít bụi bẩn, ít ruồi muỗi."},{id:"tnxh1-nha-sach-dep-04",type:"tf",q:"Ăn bánh xong, em vứt vỏ bánh xuống sàn nhà.",emoji:"🍪",answer:!1,explain:"Sai. Vỏ bánh phải bỏ vào thùng rác."},{id:"tnxh1-nha-sach-dep-05",type:"multi",q:"Việc nhà nào vừa sức em?",emoji:"🧺",options:["Sửa điện","Gấp quần áo","Quét nhà","Tưới cây"],answers:[1,2,3],explain:"Quét nhà, gấp quần áo, tưới cây vừa sức em. Sửa điện là việc của người lớn."},{id:"tnxh1-nha-sach-dep-06",type:"match",q:"Nối đồ dùng với việc làm.",pairs:[["🧹 Chổi","Quét nhà"],["🧽 Khăn lau","Lau bàn"],["🚿 Bình tưới","Tưới cây"]],explain:"Mỗi việc nhà cần đồ dùng phù hợp."},{id:"tnxh1-nha-sach-dep-07",type:"mc",q:"Sau khi chơi xong, em làm gì với đồ chơi?",emoji:"🧸",options:["Cất vào hộp","Để khắp nhà","Ném vào góc"],answer:0,explain:"Chơi xong em cất đồ chơi vào hộp."},{id:"tnxh1-nha-sach-dep-08",type:"tf",q:"Giữ nhà sạch chỉ là việc của mẹ.",emoji:"👨‍👩‍👧",answer:!1,explain:"Sai. Giữ nhà sạch là việc của mọi người trong gia đình."}]},{questions:[{id:"tnxh1-nha-sach-dep-09",type:"mc",q:"Vì sao cần đậy kín thức ăn?",emoji:"🍲",options:["Để thức ăn nặng hơn một chút","Để thức ăn đổi sang màu khác","Để ruồi, bụi không bám vào"],answer:2,explain:"Đậy thức ăn để ruồi, bụi không làm bẩn."},{id:"tnxh1-nha-sach-dep-10",type:"tf",q:"Nhà bừa bộn, nhiều rác dễ có ruồi, muỗi, gián.",emoji:"🪳",answer:!0,explain:"Đúng. Rác bẩn thu hút ruồi, muỗi, gián."},{id:"tnxh1-nha-sach-dep-11",type:"multi",q:"Việc nào làm nhà bẩn?",emoji:"🚮",options:["Đi dép bẩn lên giường","Vứt rác bừa bãi","Lau bàn sau khi ăn"],answers:[0,1],explain:"Vứt rác bừa, đi dép bẩn lên giường làm nhà bẩn. Lau bàn thì giúp nhà sạch."},{id:"tnxh1-nha-sach-dep-12",type:"mc",q:"Em giúp mẹ việc gì sau bữa cơm?",emoji:"🍽️",options:["Dọn bát đũa","Ngủ luôn","Xem ti vi ngay"],answer:0,explain:"Sau bữa cơm, em giúp mẹ dọn bát đũa."},{id:"tnxh1-nha-sach-dep-13",type:"match",q:"Nối chỗ bẩn với cách làm sạch.",pairs:[["Bàn có vụn bánh","Lau bàn"],["Sàn có bụi","Quét nhà"],["Quần áo bẩn","Giặt sạch"]],explain:"Mỗi chỗ bẩn có cách làm sạch phù hợp."},{id:"tnxh1-nha-sach-dep-14",type:"tf",q:"Chỉ cần lau dọn nhà một lần mỗi năm.",emoji:"🧹",answer:!1,explain:"Sai. Nhà cần được dọn dẹp thường xuyên."},{id:"tnxh1-nha-sach-dep-15",type:"mc",q:"Cách cất giày dép nào gọn gàng?",emoji:"👟",options:["Để trên bàn ăn","Xếp lên kệ giày","Để giữa cửa ra vào"],answer:1,explain:"Giày dép xếp lên kệ cho gọn và sạch."},{id:"tnxh1-nha-sach-dep-16",type:"tf",q:"Đóng kín cửa sổ cả ngày giúp nhà thoáng mát.",emoji:"🪟",answer:!1,explain:"Sai. Mở cửa sổ mới cho không khí trong lành vào nhà."}]},{questions:[{id:"tnxh1-nha-sach-dep-17",type:"mc",q:"Phòng của Nam có nhiều đồ chơi trên sàn. Nam nên làm gì?",emoji:"🧸",options:["Đá đồ chơi vào gầm giường","Để mẹ dọn hết","Nhặt đồ chơi cất vào hộp"],answer:2,explain:"Nam tự cất đồ chơi cho phòng gọn gàng."},{id:"tnxh1-nha-sach-dep-18",type:"mc",q:"Em làm rơi cơm ra bàn. Em nên làm gì?",emoji:"🍚",options:["Để nguyên cơm trên bàn","Nhặt bỏ và lau bàn","Gạt cơm xuống đất"],answer:1,explain:"Làm rơi thì em tự nhặt và lau sạch."},{id:"tnxh1-nha-sach-dep-19",type:"tf",q:"Vy gấp chăn gọn gàng mỗi sáng. Vy làm đúng.",emoji:"🛏️",answer:!0,explain:"Đúng. Gấp chăn giúp phòng ngủ gọn gàng."},{id:"tnxh1-nha-sach-dep-20",type:"tf",q:"Khoa vẽ lên tường nhà cho đẹp. Khoa làm đúng.",emoji:"🖍️",answer:!1,explain:"Sai. Vẽ lên tường làm bẩn nhà. Khoa nên vẽ vào giấy."},{id:"tnxh1-nha-sach-dep-21",type:"order",q:"Sắp xếp các bước dọn bàn ăn.",emoji:"🍽️",items:["Cất bát đũa","Nhặt thức ăn rơi","Lau sạch bàn"],explain:"Dọn bàn ăn: cất bát đũa, nhặt thức ăn rơi rồi lau bàn."},{id:"tnxh1-nha-sach-dep-22",type:"multi",q:"Những việc nào giúp nhà sạch đẹp?",emoji:"🌼",options:["Tưới cây cảnh","Bôi bẩn lên ghế","Xếp sách vở gọn","Bỏ rác vào thùng"],answers:[0,2,3],explain:"Tưới cây, xếp sách, bỏ rác đúng chỗ giúp nhà đẹp."},{id:"tnxh1-nha-sach-dep-23",type:"mc",q:"Cuối tuần cả nhà dọn dẹp. Việc nào em nên nhận làm?",emoji:"🧽",options:["Sửa ổ điện","Lau bàn ghế","Leo lên cao lau quạt trần"],answer:1,explain:"Lau bàn ghế vừa sức và an toàn cho em."},{id:"tnxh1-nha-sach-dep-24",type:"fill",q:"Rác phải bỏ vào thùng …",emoji:"🗑️",answer:["rác"],loose:!0,explain:"Rác phải bỏ vào thùng rác."}]}],challenge:{questions:[{id:"tnxh1-nha-sach-dep-25",type:"mc",q:"Vì sao nên bỏ rác vào thùng có nắp đậy?",emoji:"🗑️",options:["Để ruồi không bay vào, không có mùi hôi","Để rác trong thùng nhẹ hơn khi mang đi đổ","Để thùng rác trông đẹp hơn, nhiều màu hơn"],answer:0,explain:"Thùng có nắp giữ rác không bốc mùi và không có ruồi."},{id:"tnxh1-nha-sach-dep-26",type:"multi",q:"Đồ nào có thể giữ lại dùng tiếp?",emoji:"♻️",options:["Vỏ chuối","Chai nhựa để trồng cây","Hộp giấy để đựng bút"],answers:[1,2],explain:"Chai nhựa, hộp giấy có thể dùng lại. Vỏ chuối là rác."},{id:"tnxh1-nha-sach-dep-27",type:"tf",q:"Giúp bố mẹ làm việc nhà là thể hiện tình yêu thương.",emoji:"❤️",answer:!0,explain:"Đúng. Làm việc nhà giúp bố mẹ đỡ vất vả."},{id:"tnxh1-nha-sach-dep-28",type:"match",q:"Nối người với việc nhà vừa sức.",pairs:[["Em bé","Cất đồ chơi"],["Học sinh lớp 1","Lau bàn"],["Bố mẹ","Sửa đồ điện"]],explain:"Mỗi người làm việc nhà vừa sức của mình."},{id:"tnxh1-nha-sach-dep-17",type:"mc",q:"Phòng của Nam có nhiều đồ chơi trên sàn. Nam nên làm gì?",emoji:"🧸",options:["Đá đồ chơi vào gầm giường","Để mẹ dọn hết","Nhặt đồ chơi cất vào hộp"],answer:2,explain:"Nam tự cất đồ chơi cho phòng gọn gàng."},{id:"tnxh1-nha-sach-dep-10",type:"tf",q:"Nhà bừa bộn, nhiều rác dễ có ruồi, muỗi, gián.",emoji:"🪳",answer:!0,explain:"Đúng. Rác bẩn thu hút ruồi, muỗi, gián."}]},summary:["Nhà sạch đẹp giúp cả nhà khỏe mạnh.","Em làm việc nhà vừa sức và bỏ rác đúng chỗ."]}]},{id:"truong-hoc",title:"Trường học",lessons:[{id:"tnxh1-truong-hoc",title:"Trường học của em",weeks:[7,8],learn:[{title:"Trường học",text:"Trường học là nơi em đến để học tập, vui chơi cùng thầy cô và bạn bè.",example:"🏫 👩‍🏫 👫"},{title:"Các khu vực",text:"Trường có lớp học, thư viện, sân trường, phòng y tế, nhà vệ sinh.",example:"📚 🏃 🩺 🚻"},{title:"Mọi người ở trường",text:"Ở trường có thầy cô giáo, thầy cô hiệu trưởng, bác bảo vệ, cô nhân viên y tế và các bạn.",example:"👩‍🏫 💂 👩‍⚕️ 🧒"}],practice:[{questions:[{id:"tnxh1-truong-hoc-01",type:"mc",q:"Em đến trường để làm gì?",emoji:"🏫",options:["Ngủ cả ngày ở lớp","Đi chợ mua đồ ăn","Học tập và vui chơi"],answer:2,explain:"Ở trường em học tập và vui chơi cùng bạn bè."},{id:"tnxh1-truong-hoc-02",type:"mc",q:"Nơi nào trong trường có nhiều sách để đọc?",emoji:"📚",options:["Thư viện","Nhà vệ sinh","Sân trường"],answer:0,explain:"Thư viện có nhiều sách cho em đọc và mượn."},{id:"tnxh1-truong-hoc-03",type:"mc",q:"Em bị đau bụng ở trường. Em đến phòng nào?",emoji:"🩺",options:["Phòng học nhạc","Phòng y tế","Thư viện"],answer:1,explain:"Phòng y tế là nơi chăm sóc khi em bị ốm, bị đau."},{id:"tnxh1-truong-hoc-04",type:"tf",q:"Sân trường là nơi em chơi trong giờ ra chơi.",emoji:"🏃",answer:!0,explain:"Đúng. Giờ ra chơi em chơi ở sân trường."},{id:"tnxh1-truong-hoc-05",type:"tf",q:"Thư viện là nơi để chạy nhảy, la hét.",emoji:"🤫",answer:!1,explain:"Sai. Ở thư viện em giữ yên lặng để mọi người đọc sách."},{id:"tnxh1-truong-hoc-06",type:"match",q:"Nối khu vực với việc làm ở đó.",pairs:[["📚 Thư viện","Đọc sách"],["🩺 Phòng y tế","Khám khi bị đau"],["🏃 Sân trường","Vui chơi"],["✏️ Lớp học","Học bài"]],explain:"Mỗi khu vực trong trường dùng cho việc riêng."},{id:"tnxh1-truong-hoc-07",type:"multi",q:"Ai làm việc ở trường học?",emoji:"🏫",options:["Bác bảo vệ","Cô nhân viên y tế","Bác lái tàu","Thầy cô giáo"],answers:[0,1,3],explain:"Thầy cô, bác bảo vệ, cô y tế làm việc ở trường. Bác lái tàu làm việc trên tàu."},{id:"tnxh1-truong-hoc-08",type:"mc",q:"Ai dạy em học ở lớp?",emoji:"👩‍🏫",options:["Thầy cô giáo","Bác bảo vệ","Bác sĩ"],answer:0,explain:"Thầy cô giáo dạy em học."}]},{questions:[{id:"tnxh1-truong-hoc-09",type:"mc",q:"Bác bảo vệ làm gì ở trường?",emoji:"💂",options:["Trông coi, giữ an toàn cho trường","Nấu cơm cho cả nhà em mỗi tối","Dạy em đọc và viết trong lớp học"],answer:0,explain:"Bác bảo vệ trông coi cổng trường và giữ an toàn."},{id:"tnxh1-truong-hoc-10",type:"tf",q:"Ai làm việc ở trường cũng giúp em học tập tốt hơn.",emoji:"🤝",answer:!0,explain:"Đúng. Thầy cô, bác bảo vệ, cô y tế… đều chăm lo cho học sinh."},{id:"tnxh1-truong-hoc-11",type:"tf",q:"Gặp thầy cô ở trường, em không cần chào.",emoji:"🙇",answer:!1,explain:"Sai. Gặp thầy cô, em chào lễ phép."},{id:"tnxh1-truong-hoc-12",type:"multi",q:"Ở thư viện, em cần làm gì?",emoji:"📖",options:["Giữ sách cẩn thận","Giữ yên lặng","Xé sách"],answers:[0,1],explain:"Ở thư viện em giữ yên lặng và giữ gìn sách."},{id:"tnxh1-truong-hoc-13",type:"mc",q:"Vì sao cần giữ yên lặng trong thư viện?",emoji:"🤫",options:["Để mọi người đọc sách tập trung","Để sách không bay đi","Vì thư viện có nhiều đồ chơi"],answer:0,explain:"Yên lặng giúp mọi người đọc sách tập trung."},{id:"tnxh1-truong-hoc-14",type:"match",q:"Nối người với công việc.",pairs:[["👩‍🏫 Cô giáo","Dạy học"],["💂 Bác bảo vệ","Trông cổng trường"],["👩‍⚕️ Cô y tế","Chăm sóc khi em ốm"]],explain:"Mỗi người ở trường làm một việc khác nhau."},{id:"tnxh1-truong-hoc-15",type:"tf",q:"Trường học nào cũng giống hệt nhau.",emoji:"🏫",answer:!1,explain:"Sai. Mỗi trường có cảnh vật, phòng học khác nhau."},{id:"tnxh1-truong-hoc-16",type:"mc",q:"Giờ ra chơi, em có thể chơi gì ở sân trường?",emoji:"🪢",options:["Leo lên mái nhà","Nhảy dây","Trèo tường rào"],answer:1,explain:"Nhảy dây là trò chơi an toàn."}]},{questions:[{id:"tnxh1-truong-hoc-17",type:"mc",q:"Chi muốn mượn sách đọc. Chi đến đâu?",emoji:"📚",options:["Thư viện","Nhà vệ sinh","Phòng y tế"],answer:0,explain:"Thư viện là nơi mượn sách."},{id:"tnxh1-truong-hoc-18",type:"mc",q:"Bạn Tùng bị ngã trầy chân ở sân trường. Em nên làm gì?",emoji:"🩹",options:["Báo thầy cô để đưa bạn đến phòng y tế","Đứng cười bạn rồi chạy đi chỗ khác","Bỏ mặc bạn và đi chơi tiếp với nhóm"],answer:0,explain:"Em báo thầy cô để bạn được chăm sóc."},{id:"tnxh1-truong-hoc-19",type:"tf",q:"Mượn sách thư viện xong, Bình trả lại đúng hẹn. Bình làm đúng.",emoji:"📗",answer:!0,explain:"Đúng. Trả sách đúng hẹn để các bạn khác được đọc."},{id:"tnxh1-truong-hoc-20",type:"tf",q:"Phúc ra khỏi cổng trường khi chưa tan học mà không xin phép. Phúc làm đúng.",emoji:"🚪",answer:!1,explain:"Sai. Ra khỏi trường không xin phép rất nguy hiểm."},{id:"tnxh1-truong-hoc-21",type:"order",q:"Sắp xếp các việc khi em mượn sách ở thư viện.",emoji:"📚",items:["Chọn sách","Đưa cô thủ thư ghi lại","Đọc và giữ sách cẩn thận","Trả sách đúng hẹn"],explain:"Mượn sách: chọn sách, nhờ cô ghi, đọc cẩn thận, trả đúng hẹn."},{id:"tnxh1-truong-hoc-22",type:"multi",q:"Việc nào thể hiện em yêu trường học?",emoji:"🌳",options:["Viết bậy lên tường","Chăm sóc cây ở trường","Giữ sân trường sạch"],answers:[1,2],explain:"Giữ trường sạch, chăm sóc cây là yêu trường. Viết bậy làm trường bẩn."},{id:"tnxh1-truong-hoc-23",type:"mc",q:"Em gặp bác bảo vệ ở cổng trường buổi sáng. Em nói gì?",emoji:"👋",options:["Cháu chào bác ạ!","Không nói gì cả","Bác tránh ra cho cháu!"],answer:0,explain:"Em chào bác bảo vệ lễ phép."},{id:"tnxh1-truong-hoc-24",type:"fill",q:"Nơi có nhiều sách để đọc trong trường là thư …",emoji:"📚",answer:["viện"],loose:!0,explain:"Đó là thư viện."}]}],challenge:{questions:[{id:"tnxh1-truong-hoc-25",type:"match",q:"Nối tình huống với nơi em cần đến.",pairs:[["Muốn đọc truyện","Thư viện"],["Bị sốt","Phòng y tế"],["Giờ ra chơi","Sân trường"],["Giờ học Toán","Lớp học"]],explain:"Mỗi việc em đến đúng khu vực trong trường."},{id:"tnxh1-truong-hoc-26",type:"multi",q:"Những khu vực nào thường có ở trường tiểu học?",emoji:"🏫",options:["Sân trường","Lớp học","Chuồng voi","Thư viện"],answers:[0,1,3],explain:"Lớp học, thư viện, sân trường có ở trường. Chuồng voi có ở vườn thú."},{id:"tnxh1-truong-hoc-27",type:"tf",q:"Chạy nhảy trong hành lang lúc đông người có thể gây va ngã.",emoji:"🚶",answer:!0,explain:"Đúng. Em đi nhẹ nhàng trong hành lang."},{id:"tnxh1-truong-hoc-28",type:"mc",q:"Vì sao cần chào hỏi mọi người làm việc ở trường?",emoji:"🙇",options:["Để được cô cho về nhà sớm hơn","Vì chào hỏi sẽ được điểm cao","Để thể hiện lễ phép và biết ơn"],answer:2,explain:"Chào hỏi thể hiện em lễ phép, biết ơn."},{id:"tnxh1-truong-hoc-12",type:"multi",q:"Ở thư viện, em cần làm gì?",emoji:"📖",options:["Giữ sách cẩn thận","Giữ yên lặng","Xé sách"],answers:[0,1],explain:"Ở thư viện em giữ yên lặng và giữ gìn sách."},{id:"tnxh1-truong-hoc-21",type:"order",q:"Sắp xếp các việc khi em mượn sách ở thư viện.",emoji:"📚",items:["Chọn sách","Đưa cô thủ thư ghi lại","Đọc và giữ sách cẩn thận","Trả sách đúng hẹn"],explain:"Mượn sách: chọn sách, nhờ cô ghi, đọc cẩn thận, trả đúng hẹn."}]},summary:["Trường học có lớp học, thư viện, sân trường, phòng y tế.","Em kính trọng thầy cô và mọi người ở trường."]},{id:"tnxh1-lop-hoc",title:"Lớp học của em",weeks:[8,9],learn:[{title:"Lớp học",text:"Lớp học có cô giáo hoặc thầy giáo và các bạn học sinh.",example:"👩‍🏫 👦 👧"},{title:"Đồ dùng trong lớp",text:"Lớp có bảng, bàn ghế, tranh ảnh. Em có sách vở, bút, thước.",example:"🪑 📘 ✏️ 📏"},{title:"Bạn bè",text:"Em đoàn kết, giúp đỡ bạn, không trêu chọc bạn.",example:"🤝 😊"}],practice:[{questions:[{id:"tnxh1-lop-hoc-01",type:"mc",q:"Cô giáo viết bài lên đâu?",emoji:"🧑‍🏫",options:["Sàn nhà","Cửa sổ","Bảng"],answer:2,explain:"Cô giáo viết lên bảng cho cả lớp cùng xem."},{id:"tnxh1-lop-hoc-02",type:"mc",q:"Đồ dùng nào để viết bài?",emoji:"✏️",options:["Bút chì","Cái chổi","Quả bóng"],answer:0,explain:"Em dùng bút chì để viết."},{id:"tnxh1-lop-hoc-03",type:"mc",q:"Đồ dùng nào để kẻ đường thẳng?",emoji:"📏",options:["Thước kẻ","Hộp màu","Cục tẩy"],answer:0,explain:"Thước kẻ giúp em kẻ đường thẳng."},{id:"tnxh1-lop-hoc-04",type:"tf",q:"Cục tẩy dùng để gọt bút chì.",emoji:"🧽",answer:!1,explain:"Sai. Cục tẩy dùng để xóa vết bút chì."},{id:"tnxh1-lop-hoc-05",type:"tf",q:"Trong lớp chỉ có một mình em.",emoji:"👫",answer:!1,explain:"Sai. Lớp học có thầy cô và nhiều bạn."},{id:"tnxh1-lop-hoc-06",type:"multi",q:"Đồ dùng học tập nào em mang trong cặp?",emoji:"🎒",options:["Cái nồi","Bút","Sách","Vở"],answers:[1,2,3],explain:"Sách, vở, bút là đồ dùng học tập. Nồi để nấu ăn."},{id:"tnxh1-lop-hoc-07",type:"match",q:"Nối đồ dùng với công dụng.",pairs:[["✏️ Bút chì","Viết"],["📏 Thước","Kẻ"],["🖍️ Bút màu","Tô màu"],["✂️ Kéo","Cắt giấy"]],explain:"Mỗi đồ dùng học tập có một công dụng."},{id:"tnxh1-lop-hoc-08",type:"mc",q:"Em ngồi học ở đâu trong lớp?",emoji:"🪑",options:["Trên bục giảng","Ở bàn ghế của em","Trên bậu cửa sổ"],answer:1,explain:"Em ngồi ngay ngắn tại bàn ghế của mình."}]},{questions:[{id:"tnxh1-lop-hoc-09",type:"mc",q:"Muốn phát biểu trong giờ học, em làm gì?",emoji:"🙋",options:["Giơ tay xin phép","Nói to cắt ngang","Đứng lên chạy"],answer:0,explain:"Em giơ tay, chờ thầy cô cho phép rồi nói."},{id:"tnxh1-lop-hoc-10",type:"tf",q:"Giữ sách vở sạch sẽ là thói quen tốt.",emoji:"📘",answer:!0,explain:"Đúng. Sách vở sạch giúp em học tốt và dùng được lâu."},{id:"tnxh1-lop-hoc-11",type:"tf",q:"Trêu chọc bạn trong lớp là vui và tốt.",emoji:"😢",answer:!1,explain:"Sai. Trêu chọc làm bạn buồn. Em đối xử tốt với bạn."},{id:"tnxh1-lop-hoc-12",type:"multi",q:"Việc nào thể hiện em là bạn tốt?",emoji:"🤝",options:["Giấu đồ của bạn","Giúp bạn nhặt đồ rơi","Cho bạn mượn bút"],answers:[1,2],explain:"Cho mượn bút, giúp nhặt đồ là bạn tốt. Giấu đồ của bạn là sai."},{id:"tnxh1-lop-hoc-13",type:"mc",q:"Vì sao em cần ngồi ngay ngắn khi viết?",emoji:"🧍",options:["Để chạy nhanh hơn trong giờ ra chơi","Để không đau lưng, không hại mắt","Để tối về ngủ ngon hơn"],answer:1,explain:"Ngồi đúng tư thế giúp lưng thẳng và mắt khỏe."},{id:"tnxh1-lop-hoc-14",type:"match",q:"Nối hành động với lời nói phù hợp.",pairs:[["Bạn cho mượn bút","Cảm ơn bạn"],["Lỡ va vào bạn","Xin lỗi bạn"],["Gặp cô giáo","Em chào cô ạ"]],explain:"Em biết nói cảm ơn, xin lỗi, chào hỏi."},{id:"tnxh1-lop-hoc-15",type:"tf",q:"Em nên bọc sách vở để giữ sạch.",emoji:"📗",answer:!0,explain:"Đúng. Bọc sách vở giúp sách không bị bẩn, rách."},{id:"tnxh1-lop-hoc-16",type:"mc",q:"Bạn mới chuyển đến lớp em. Em làm gì?",emoji:"👋",options:["Không nói chuyện với bạn","Làm quen và rủ bạn chơi","Cười chê bạn"],answer:1,explain:"Em chào và làm quen để bạn mới thấy vui."}]},{questions:[{id:"tnxh1-lop-hoc-17",type:"mc",q:"Ngọc quên mang bút. Em có hai cái bút. Em làm gì?",emoji:"✏️",options:["Chê Ngọc là bạn đãng trí","Giấu cả hai cái bút đi","Cho Ngọc mượn một cái"],answer:2,explain:"Cho bạn mượn bút là biết giúp đỡ bạn."},{id:"tnxh1-lop-hoc-18",type:"mc",q:"Trong giờ học, Dũng muốn đi vệ sinh. Dũng làm gì?",emoji:"🙋",options:["Ngồi im khóc","Tự chạy ra ngoài","Giơ tay xin phép cô"],answer:2,explain:"Dũng giơ tay xin phép rồi mới ra khỏi lớp."},{id:"tnxh1-lop-hoc-19",type:"tf",q:"An làm rách vở của bạn và xin lỗi bạn. An làm đúng.",emoji:"🙏",answer:!0,explain:"Đúng. Làm sai thì xin lỗi bạn."},{id:"tnxh1-lop-hoc-20",type:"tf",q:"Thảo nói chuyện riêng khi cô đang giảng bài. Thảo làm đúng.",emoji:"🤐",answer:!1,explain:"Sai. Em giữ trật tự và lắng nghe khi cô giảng bài."},{id:"tnxh1-lop-hoc-21",type:"order",q:"Sắp xếp các việc chuẩn bị đi học từ tối hôm trước.",emoji:"🎒",items:["Xem thời khóa biểu","Xếp sách vở vào cặp","Gọt bút chì","Để cặp đúng chỗ"],explain:"Xem thời khóa biểu, xếp sách vở, chuẩn bị bút rồi để cặp gọn gàng."},{id:"tnxh1-lop-hoc-22",type:"multi",q:"Lớp học sạch đẹp khi các bạn…",emoji:"🧹",options:["Xếp bàn ghế ngay ngắn","Vẽ lên bàn","Bỏ rác vào thùng"],answers:[0,2],explain:"Bỏ rác đúng chỗ, xếp bàn ghế ngay ngắn giúp lớp sạch đẹp."},{id:"tnxh1-lop-hoc-23",type:"mc",q:"Bạn bên cạnh không hiểu bài. Em làm gì?",emoji:"📖",options:["Giảng lại cho bạn trong giờ ra chơi","Cười chê bạn vì bạn chưa hiểu bài","Bảo bạn đừng học bài đó nữa"],answer:0,explain:"Giúp bạn hiểu bài là đoàn kết."},{id:"tnxh1-lop-hoc-24",type:"fill",q:"Em dùng cục … để xóa vết bút chì.",emoji:"✏️",answer:["tẩy"],loose:!0,explain:"Cục tẩy xóa được vết bút chì."}]}],challenge:{questions:[{id:"tnxh1-lop-hoc-25",type:"match",q:"Nối việc với đồ dùng cần có.",pairs:[["Vẽ con mèo","Bút màu"],["Kẻ lề vở","Thước kẻ"],["Cắt giấy thủ công","Kéo"],["Xóa chữ viết sai","Cục tẩy"]],explain:"Chọn đúng đồ dùng giúp em làm bài tốt."},{id:"tnxh1-lop-hoc-26",type:"mc",q:"Hai bạn tranh nhau một quyển truyện. Cách nào hay nhất?",emoji:"📕",options:["Mách cô rồi ngồi khóc thật to","Giằng co đến khi quyển sách bị rách","Thay phiên nhau đọc hoặc đọc chung"],answer:2,explain:"Đọc chung hoặc thay phiên là cách hòa thuận."},{id:"tnxh1-lop-hoc-27",type:"tf",q:"Lớp học là của chung, ai cũng cần giữ gìn.",emoji:"🏫",answer:!0,explain:"Đúng. Cả lớp cùng giữ gìn lớp học."},{id:"tnxh1-lop-hoc-28",type:"multi",q:"Đồ dùng nào là của chung cả lớp?",emoji:"🏫",options:["Hộp bút của em","Tranh treo tường","Bàn ghế","Cái bảng"],answers:[1,2,3],explain:"Bảng, bàn ghế, tranh là của chung. Hộp bút là đồ riêng."},{id:"tnxh1-lop-hoc-13",type:"mc",q:"Vì sao em cần ngồi ngay ngắn khi viết?",emoji:"🧍",options:["Để chạy nhanh hơn trong giờ ra chơi","Để không đau lưng, không hại mắt","Để tối về ngủ ngon hơn"],answer:1,explain:"Ngồi đúng tư thế giúp lưng thẳng và mắt khỏe."},{id:"tnxh1-lop-hoc-09",type:"mc",q:"Muốn phát biểu trong giờ học, em làm gì?",emoji:"🙋",options:["Giơ tay xin phép","Nói to cắt ngang","Đứng lên chạy"],answer:0,explain:"Em giơ tay, chờ thầy cô cho phép rồi nói."}]},summary:["Lớp học có thầy cô và các bạn.","Em giữ gìn đồ dùng và đoàn kết với bạn bè."]},{id:"tnxh1-hoat-dong-o-truong",title:"Hoạt động ở trường",weeks:[9,10],learn:[{title:"Giờ học",text:"Trong giờ học, em chú ý nghe giảng và làm bài.",example:"📖 ✍️"},{title:"Giờ ra chơi",text:"Giờ ra chơi, em chơi các trò chơi an toàn với bạn.",example:"🪢 ⚽ 🤸"},{title:"Chào cờ",text:"Đầu tuần, trường em thường chào cờ. Em đứng nghiêm trang.",example:"🇻🇳 🧍"},{title:"Hoạt động khác",text:"Ở trường còn có văn nghệ, thể thao, trồng cây.",example:"🎵 🏃 🌱"}],practice:[{questions:[{id:"tnxh1-hoat-dong-o-truong-01",type:"mc",q:"Khi chào cờ, em đứng thế nào?",emoji:"🇻🇳",options:["Đứng nghiêm trang","Nói chuyện riêng","Chạy nhảy"],answer:0,explain:"Chào cờ em đứng nghiêm, hướng về lá cờ."},{id:"tnxh1-hoat-dong-o-truong-02",type:"mc",q:"Lá cờ Tổ quốc Việt Nam có màu gì?",emoji:"🇻🇳",options:["Nền vàng, sao đỏ","Nền xanh, sao trắng","Nền đỏ, sao vàng"],answer:2,explain:"Cờ Tổ quốc nền đỏ, ở giữa có ngôi sao vàng năm cánh."},{id:"tnxh1-hoat-dong-o-truong-03",type:"tf",q:"Giờ ra chơi là lúc em nghỉ ngơi và vui chơi.",emoji:"⏰",answer:!0,explain:"Đúng. Ra chơi giúp em thư giãn sau giờ học."},{id:"tnxh1-hoat-dong-o-truong-04",type:"tf",q:"Trong giờ học, em nên chơi đồ chơi dưới gầm bàn.",emoji:"🧸",answer:!1,explain:"Sai. Trong giờ học em chú ý nghe giảng."},{id:"tnxh1-hoat-dong-o-truong-05",type:"multi",q:"Trò chơi nào an toàn trong giờ ra chơi?",emoji:"🪢",options:["Trèo cây cao","Ô ăn quan","Nhảy dây","Đá cầu"],answers:[1,2,3],explain:"Nhảy dây, đá cầu, ô ăn quan an toàn. Trèo cây cao dễ ngã."},{id:"tnxh1-hoat-dong-o-truong-06",type:"match",q:"Nối hoạt động với hình.",pairs:[["Hát múa","🎵"],["Đá bóng","⚽"],["Trồng cây","🌱"],["Đọc sách","📖"]],explain:"Ở trường có nhiều hoạt động bổ ích."},{id:"tnxh1-hoat-dong-o-truong-07",type:"mc",q:"Ngôi sao trên lá cờ Tổ quốc có mấy cánh?",emoji:"⭐",options:["Bốn cánh","Năm cánh","Sáu cánh"],answer:1,explain:"Ngôi sao vàng trên cờ Tổ quốc có năm cánh."},{id:"tnxh1-hoat-dong-o-truong-08",type:"tf",q:"Thể dục giữa giờ làm em mệt và yếu đi.",emoji:"🤸",answer:!1,explain:"Sai. Thể dục giữa giờ giúp cơ thể khỏe và đầu óc tỉnh táo."}]},{questions:[{id:"tnxh1-hoat-dong-o-truong-09",type:"mc",q:"Vì sao em cần chú ý trong giờ học?",emoji:"👂",options:["Để về sớm","Để được ngủ","Để hiểu bài"],answer:2,explain:"Chú ý nghe giảng giúp em hiểu bài."},{id:"tnxh1-hoat-dong-o-truong-10",type:"tf",q:"Tham gia hoạt động ở trường giúp em có thêm bạn.",emoji:"👫",answer:!0,explain:"Đúng. Cùng hoạt động, các bạn gần gũi nhau hơn."},{id:"tnxh1-hoat-dong-o-truong-11",type:"multi",q:"Việc nào em nên làm trong giờ học?",emoji:"📚",options:["Giơ tay phát biểu","Nghe cô giảng","Làm bài cẩn thận","Ngủ gật"],answers:[0,1,2],explain:"Nghe giảng, phát biểu, làm bài là học tập tốt."},{id:"tnxh1-hoat-dong-o-truong-12",type:"mc",q:"Hết giờ ra chơi, trống báo vào lớp. Em làm gì?",emoji:"🥁",options:["Trốn ra cổng trường","Xếp hàng vào lớp","Ở lại sân chơi tiếp"],answer:1,explain:"Nghe trống, em dừng chơi và vào lớp."},{id:"tnxh1-hoat-dong-o-truong-13",type:"match",q:"Nối thời điểm với việc em làm.",pairs:[["Giờ học","Nghe giảng, làm bài"],["Giờ ra chơi","Chơi cùng bạn"],["Giờ chào cờ","Đứng nghiêm trang"]],explain:"Mỗi thời điểm ở trường có việc phù hợp."},{id:"tnxh1-hoat-dong-o-truong-14",type:"tf",q:"Khi chào cờ, em vừa hát Quốc ca vừa nói chuyện với bạn.",emoji:"🎶",answer:!1,explain:"Sai. Khi chào cờ, em nghiêm trang, không nói chuyện."},{id:"tnxh1-hoat-dong-o-truong-15",type:"mc",q:"Bài hát được hát khi chào cờ là bài gì?",emoji:"🎶",options:["Bài hát ru","Quốc ca","Bài hát chúc mừng sinh nhật"],answer:1,explain:"Khi chào cờ, cả trường hát Quốc ca."},{id:"tnxh1-hoat-dong-o-truong-16",type:"tf",q:"Ra chơi xong, em nên uống nước và rửa tay trước khi vào lớp.",emoji:"🚰",answer:!0,explain:"Đúng. Rửa tay cho sạch, uống nước cho đỡ khát."}]},{questions:[{id:"tnxh1-hoat-dong-o-truong-17",type:"mc",q:"Lớp em trồng cây ở vườn trường. Em có thể làm gì?",emoji:"🌱",options:["Tưới nước cho cây","Bẻ cành cây","Giẫm lên cây non"],answer:0,explain:"Tưới nước giúp cây lớn tốt."},{id:"tnxh1-hoat-dong-o-truong-18",type:"mc",q:"Trường tổ chức văn nghệ. Minh hát hay. Minh nên làm gì?",emoji:"🎤",options:["Trốn ở nhà hôm đó","Đăng kí tham gia hát","Chê các bạn khác hát dở"],answer:1,explain:"Minh tham gia để góp vui cho lớp."},{id:"tnxh1-hoat-dong-o-truong-19",type:"tf",q:"Bạn Lan ngã khi chơi, Nam đỡ Lan dậy. Nam làm đúng.",emoji:"🤝",answer:!0,explain:"Đúng. Nam biết giúp đỡ bạn."},{id:"tnxh1-hoat-dong-o-truong-20",type:"tf",q:"Khoa đẩy bạn để giành chỗ đứng đầu hàng. Khoa làm đúng.",emoji:"🚶",answer:!1,explain:"Sai. Đẩy bạn có thể làm bạn ngã. Em xếp hàng trật tự."},{id:"tnxh1-hoat-dong-o-truong-21",type:"order",q:"Sắp xếp các việc trong buổi sáng ở trường.",emoji:"🏫",items:["Đến trường, chào thầy cô","Vào lớp học bài","Ra chơi","Vào lớp học tiếp"],explain:"Đến trường, học, ra chơi rồi học tiếp."},{id:"tnxh1-hoat-dong-o-truong-22",type:"multi",q:"Khi xếp hàng, em cần làm gì?",emoji:"🚶‍♂️",options:["Đứng thẳng hàng","Xô đẩy bạn","Không chen lấn"],answers:[0,2],explain:"Đứng thẳng hàng, không chen lấn, không xô đẩy."},{id:"tnxh1-hoat-dong-o-truong-23",type:"mc",q:"Trời mưa, giờ ra chơi em có thể chơi gì?",emoji:"🌧️",options:["Trèo lên bàn rồi nhảy xuống đất","Chạy ra giữa sân để dầm mưa","Chơi trò chơi nhẹ nhàng trong lớp"],answer:2,explain:"Trời mưa, em chơi nhẹ nhàng ở trong lớp."},{id:"tnxh1-hoat-dong-o-truong-24",type:"fill",q:"Ngôi sao trên lá cờ Tổ quốc màu …",emoji:"🇻🇳",answer:["vàng"],loose:!0,explain:"Cờ Tổ quốc nền đỏ, sao vàng."}]}],challenge:{questions:[{id:"tnxh1-hoat-dong-o-truong-25",type:"mc",q:"Đội bóng lớp em thua. Em nên làm gì?",emoji:"⚽",options:["Vui vẻ chúc mừng đội bạn","Giận dỗi và khóc lóc mãi","Chê đội bạn chơi ăn gian"],answer:0,explain:"Thắng thua là bình thường. Em vui vẻ chúc mừng bạn."},{id:"tnxh1-hoat-dong-o-truong-26",type:"multi",q:"Hoạt động nào thường có ở trường tiểu học?",emoji:"🏫",options:["Chào cờ","Đi làm ruộng thay bố mẹ","Thể dục giữa giờ","Văn nghệ"],answers:[0,2,3],explain:"Chào cờ, thể dục, văn nghệ là hoạt động ở trường."},{id:"tnxh1-hoat-dong-o-truong-27",type:"match",q:"Nối hoạt động với lợi ích.",pairs:[["Tập thể dục","Cơ thể khỏe mạnh"],["Đọc sách","Biết thêm nhiều điều"],["Trồng cây","Trường thêm xanh"]],explain:"Mỗi hoạt động mang lại một lợi ích."},{id:"tnxh1-hoat-dong-o-truong-28",type:"tf",q:"Hoạt động ở trường chỉ dành cho học sinh giỏi.",emoji:"🙌",answer:!1,explain:"Sai. Mọi học sinh đều được tham gia."},{id:"tnxh1-hoat-dong-o-truong-05",type:"multi",q:"Trò chơi nào an toàn trong giờ ra chơi?",emoji:"🪢",options:["Trèo cây cao","Ô ăn quan","Nhảy dây","Đá cầu"],answers:[1,2,3],explain:"Nhảy dây, đá cầu, ô ăn quan an toàn. Trèo cây cao dễ ngã."},{id:"tnxh1-hoat-dong-o-truong-23",type:"mc",q:"Trời mưa, giờ ra chơi em có thể chơi gì?",emoji:"🌧️",options:["Trèo lên bàn rồi nhảy xuống đất","Chạy ra giữa sân để dầm mưa","Chơi trò chơi nhẹ nhàng trong lớp"],answer:2,explain:"Trời mưa, em chơi nhẹ nhàng ở trong lớp."}]},summary:["Ở trường có giờ học, giờ ra chơi, chào cờ và nhiều hoạt động.","Em tham gia tích cực và giữ trật tự."]},{id:"tnxh1-an-toan-o-truong",title:"An toàn và vệ sinh ở trường",weeks:[10,11],learn:[{title:"Chơi an toàn",text:"Em không xô đẩy, không trèo cây, không chơi trò nguy hiểm.",example:"🚫 🧗 ✅ 🪢"},{title:"Lên xuống cầu thang",text:"Đi bên phải, bám tay vịn, không chạy, không đùa nghịch.",example:"🪜 ✋"},{title:"Lớp sạch, trường đẹp",text:"Em bỏ rác vào thùng, đi vệ sinh đúng nơi, rửa tay sạch.",example:"🗑️ 🚻 🧼"}],practice:[{questions:[{id:"tnxh1-an-toan-o-truong-01",type:"mc",q:"Khi đi cầu thang, em làm gì?",emoji:"🪜",options:["Trượt trên tay vịn","Bám tay vịn, đi từ từ","Chạy thật nhanh"],answer:1,explain:"Bám tay vịn, đi từ từ để không bị ngã."},{id:"tnxh1-an-toan-o-truong-02",type:"mc",q:"Trò chơi nào nguy hiểm?",emoji:"⚠️",options:["Nhảy dây cùng các bạn","Chơi chuyền ở góc lớp","Trèo lên tường rào"],answer:2,explain:"Trèo tường rào có thể bị ngã."},{id:"tnxh1-an-toan-o-truong-03",type:"tf",q:"Xô đẩy bạn khi chơi có thể làm bạn bị thương.",emoji:"🤕",answer:!0,explain:"Đúng. Em chơi nhẹ nhàng, không xô đẩy."},{id:"tnxh1-an-toan-o-truong-04",type:"tf",q:"Vứt rác ra sân trường cho nhanh.",emoji:"🗑️",answer:!1,explain:"Sai. Rác phải bỏ vào thùng rác."},{id:"tnxh1-an-toan-o-truong-05",type:"multi",q:"Việc nào giữ trường sạch đẹp?",emoji:"🏫",options:["Bỏ rác vào thùng","Xả nước sau khi đi vệ sinh","Bẻ cây","Đi vệ sinh đúng nơi"],answers:[0,1,3],explain:"Bỏ rác đúng chỗ, đi vệ sinh đúng nơi và xả nước giúp trường sạch."},{id:"tnxh1-an-toan-o-truong-06",type:"match",q:"Nối nơi ở trường với việc nên làm.",pairs:[["📚 Thư viện","Giữ yên lặng"],["🚶 Hành lang","Đi nhẹ nhàng"],["🚽 Nhà vệ sinh","Xả nước sau khi dùng"]],explain:"Ở mỗi nơi, em làm đúng việc để trường an toàn, sạch đẹp."},{id:"tnxh1-an-toan-o-truong-07",type:"mc",q:"Sau khi đi vệ sinh, em làm gì?",emoji:"🧼",options:["Rửa tay bằng xà phòng","Lau tay vào vạt áo","Đi ăn luôn cho kịp"],answer:0,explain:"Đi vệ sinh xong phải rửa tay bằng xà phòng."},{id:"tnxh1-an-toan-o-truong-08",type:"tf",q:"Chơi đá cầu ở cầu thang là an toàn.",emoji:"🏸",answer:!1,explain:"Sai. Cầu thang hẹp, dễ ngã, em chơi đá cầu ở chỗ rộng rãi."}]},{questions:[{id:"tnxh1-an-toan-o-truong-09",type:"mc",q:"Vì sao không chạy khi xuống cầu thang?",emoji:"🪜",options:["Vì dễ trượt chân, ngã","Vì cầu thang sẽ hỏng","Vì bị muộn giờ"],answer:0,explain:"Chạy trên cầu thang dễ bị ngã rất nguy hiểm."},{id:"tnxh1-an-toan-o-truong-10",type:"tf",q:"Uống nước ở vòi nước uống của trường, em xếp hàng chờ đến lượt.",emoji:"🚰",answer:!0,explain:"Đúng. Xếp hàng giúp không chen lấn."},{id:"tnxh1-an-toan-o-truong-11",type:"multi",q:"Những trò chơi nào KHÔNG an toàn?",emoji:"🚫",options:["Ném đá","Đánh nhau giả vờ","Trèo lên lan can","Chơi ô ăn quan"],answers:[0,1,2],explain:"Ném đá, đánh nhau, trèo lan can đều nguy hiểm. Ô ăn quan an toàn."},{id:"tnxh1-an-toan-o-truong-12",type:"mc",q:"Lớp học cần được làm gì để sạch?",emoji:"🧹",options:["Đóng kín mọi cửa","Để rác cả tuần","Quét dọn hằng ngày"],answer:2,explain:"Lớp được quét dọn hằng ngày sẽ sạch sẽ."},{id:"tnxh1-an-toan-o-truong-13",type:"match",q:"Nối nơi với việc giữ an toàn.",pairs:[["Cầu thang","Bám tay vịn"],["Sân trường","Không xô đẩy"],["Nhà vệ sinh","Đi cẩn thận vì sàn có thể trơn"]],explain:"Ở mỗi nơi, em có cách giữ an toàn."},{id:"tnxh1-an-toan-o-truong-14",type:"tf",q:"Sàn nhà vệ sinh ướt nên em có thể chạy nhảy.",emoji:"💧",answer:!1,explain:"Sai. Sàn ướt rất trơn, dễ ngã."},{id:"tnxh1-an-toan-o-truong-15",type:"mc",q:"Khi thấy bạn trèo lên lan can, em làm gì?",emoji:"⚠️",options:["Đứng vỗ tay cổ vũ bạn trèo cao","Trèo theo bạn lên lan can","Khuyên bạn xuống và báo thầy cô"],answer:2,explain:"Trèo lan can rất nguy hiểm. Em khuyên bạn và báo thầy cô."},{id:"tnxh1-an-toan-o-truong-16",type:"tf",q:"Đi vệ sinh xong, em xả nước cho sạch.",emoji:"🚽",answer:!0,explain:"Đúng. Xả nước giúp nhà vệ sinh sạch, không có mùi."}]},{questions:[{id:"tnxh1-an-toan-o-truong-17",type:"mc",q:"Vy thấy một mảnh thủy tinh vỡ ở sân trường. Vy nên làm gì?",emoji:"🔺",options:["Nhặt mảnh thủy tinh lên chơi","Báo thầy cô hoặc bác bảo vệ","Để yên đó rồi chạy đi chơi"],answer:1,explain:"Thủy tinh vỡ dễ gây đứt tay. Vy báo người lớn dọn."},{id:"tnxh1-an-toan-o-truong-18",type:"mc",q:"Bình thấy một người lạ rủ ra cổng trường. Bình làm gì?",emoji:"🚫",options:["Nhận kẹo của người lạ đó","Không đi theo, báo thầy cô","Đi theo người lạ ra cổng ngay"],answer:1,explain:"Em không đi theo người lạ và báo thầy cô."},{id:"tnxh1-an-toan-o-truong-19",type:"tf",q:"Hà rửa tay với xà phòng trước khi ăn bữa trưa ở trường. Hà làm đúng.",emoji:"🧼",answer:!0,explain:"Đúng. Rửa tay trước khi ăn giúp phòng bệnh."},{id:"tnxh1-an-toan-o-truong-20",type:"tf",q:"Dũng chơi ném bóng vào cửa kính lớp học. Dũng làm đúng.",emoji:"🪟",answer:!1,explain:"Sai. Kính vỡ có thể làm mọi người bị thương."},{id:"tnxh1-an-toan-o-truong-21",type:"order",q:"Sắp xếp các bước rửa tay.",emoji:"🧼",items:["Làm ướt tay","Xoa xà phòng","Rửa sạch dưới vòi nước","Lau khô tay"],explain:"Rửa tay: làm ướt, xoa xà phòng, rửa sạch, lau khô."},{id:"tnxh1-an-toan-o-truong-22",type:"multi",q:"Lớp em trực nhật. Các bạn làm việc gì?",emoji:"🧹",options:["Xếp bàn ghế","Viết lên tường","Quét lớp","Lau bảng"],answers:[0,2,3],explain:"Trực nhật gồm quét lớp, lau bảng, xếp bàn ghế."},{id:"tnxh1-an-toan-o-truong-23",type:"mc",q:"Cách nào giúp phòng bệnh khi ở trường?",emoji:"🧼",options:["Uống nước lã","Ăn chung một thìa với nhiều bạn","Rửa tay thường xuyên"],answer:2,explain:"Rửa tay thường xuyên giúp phòng bệnh."},{id:"tnxh1-an-toan-o-truong-24",type:"fill",q:"Đi cầu thang, em bám tay … và đi từ từ.",emoji:"🪜",answer:["vịn"],loose:!0,explain:"Bám tay vịn giúp em không bị ngã."}]}],challenge:{questions:[{id:"tnxh1-an-toan-o-truong-25",type:"mc",q:"Giờ ra chơi, An bị bạn đánh. An nên làm gì?",emoji:"🙋",options:["Báo thầy cô để giải quyết","Im lặng chịu đựng mãi","Đánh lại thật mạnh"],answer:0,explain:"An báo thầy cô để được giúp đỡ, không đánh nhau."},{id:"tnxh1-an-toan-o-truong-26",type:"match",q:"Nối việc làm với lí do.",pairs:[["Bỏ rác vào thùng","Trường sạch"],["Bám tay vịn","Không ngã"],["Rửa tay","Phòng bệnh"]],explain:"Mỗi việc làm tốt có một lí do."},{id:"tnxh1-an-toan-o-truong-27",type:"multi",q:"Khi đi vệ sinh ở trường, em cần làm gì?",emoji:"🚻",options:["Xả nước","Ném giấy xuống sàn","Rửa tay","Đi đúng chỗ"],answers:[0,2,3],explain:"Đi đúng chỗ, xả nước, rửa tay để giữ sạch và phòng bệnh."},{id:"tnxh1-an-toan-o-truong-28",type:"tf",q:"Nhặt rác ở sân trường bỏ vào thùng là việc tốt.",emoji:"♻️",answer:!0,explain:"Đúng. Nhặt rác giúp trường sạch đẹp."},{id:"tnxh1-an-toan-o-truong-18",type:"mc",q:"Bình thấy một người lạ rủ ra cổng trường. Bình làm gì?",emoji:"🚫",options:["Nhận kẹo của người lạ đó","Không đi theo, báo thầy cô","Đi theo người lạ ra cổng ngay"],answer:1,explain:"Em không đi theo người lạ và báo thầy cô."},{id:"tnxh1-an-toan-o-truong-09",type:"mc",q:"Vì sao không chạy khi xuống cầu thang?",emoji:"🪜",options:["Vì dễ trượt chân, ngã","Vì cầu thang sẽ hỏng","Vì bị muộn giờ"],answer:0,explain:"Chạy trên cầu thang dễ bị ngã rất nguy hiểm."}]},summary:["Em chơi trò chơi an toàn, không xô đẩy, không leo trèo.","Em giữ vệ sinh lớp học, trường học và rửa tay sạch."]}]},{id:"cong-dong-dia-phuong",title:"Cộng đồng địa phương",lessons:[{id:"tnxh1-noi-em-song",title:"Nơi em sống",weeks:[12,13],learn:[{title:"Làng quê",text:"Ở làng quê thường có đồng ruộng, ao hồ, nhà có vườn.",example:"🌾 🐃 🏡"},{title:"Thành phố",text:"Ở thành phố thường có nhà cao tầng, nhiều xe cộ, cửa hàng.",example:"🏙️ 🚗 🏬"},{title:"Nơi công cộng",text:"Nơi em sống có chợ, trường học, trạm y tế, công viên… dùng chung cho mọi người.",example:"🛒 🏫 🏥 🌳"}],practice:[{questions:[{id:"tnxh1-noi-em-song-01",type:"mc",q:"Cảnh nào thường thấy ở làng quê?",emoji:"🌾",options:["Đường cao tốc trên cao","Cánh đồng lúa","Nhà cao chọc trời"],answer:1,explain:"Làng quê thường có cánh đồng lúa."},{id:"tnxh1-noi-em-song-02",type:"mc",q:"Cảnh nào thường thấy ở thành phố?",emoji:"🏙️",options:["Nhà cao tầng, nhiều xe cộ","Trâu đang cày trên ruộng lúa","Ao làng có đàn vịt bơi"],answer:0,explain:"Thành phố có nhiều nhà cao tầng và xe cộ."},{id:"tnxh1-noi-em-song-03",type:"mc",q:"Muốn mua rau, cá, thịt, em cùng mẹ đến đâu?",emoji:"🛒",options:["Trạm y tế","Chợ","Trường học"],answer:1,explain:"Chợ là nơi bán rau, cá, thịt."},{id:"tnxh1-noi-em-song-04",type:"tf",q:"Trạm y tế là nơi bán rau, bán cá.",emoji:"🏥",answer:!1,explain:"Sai. Trạm y tế là nơi khám chữa bệnh, chợ mới là nơi bán rau, bán cá."},{id:"tnxh1-noi-em-song-05",type:"tf",q:"Công viên là của riêng một gia đình.",emoji:"🌳",answer:!1,explain:"Sai. Công viên là nơi công cộng, ai cũng đến chơi được."},{id:"tnxh1-noi-em-song-06",type:"match",q:"Nối nơi công cộng với việc làm ở đó.",pairs:[["🛒 Chợ","Mua bán"],["🏥 Trạm y tế","Khám bệnh"],["🌳 Công viên","Vui chơi, tập thể dục"],["🏫 Trường học","Học tập"]],explain:"Mỗi nơi công cộng phục vụ một việc."},{id:"tnxh1-noi-em-song-07",type:"multi",q:"Nơi nào là nơi công cộng?",emoji:"🏞️",options:["Phòng ngủ của em","Bến xe","Chợ","Công viên"],answers:[1,2,3],explain:"Chợ, công viên, bến xe là nơi công cộng. Phòng ngủ là nơi riêng."},{id:"tnxh1-noi-em-song-08",type:"mc",q:"Con vật nào hay giúp nhà nông cày ruộng?",emoji:"🐃",options:["Con gà","Con mèo","Con trâu"],answer:2,explain:"Trâu kéo cày giúp nhà nông."}]},{questions:[{id:"tnxh1-noi-em-song-09",type:"mc",q:"Vì sao cần giữ gìn nơi công cộng?",emoji:"🤝",options:["Vì đó là nơi dùng chung của mọi người","Vì ở đó lúc nào cũng không có ai","Vì đó là nhà riêng của một mình em"],answer:0,explain:"Nơi công cộng là của chung, ai cũng phải giữ gìn."},{id:"tnxh1-noi-em-song-10",type:"tf",q:"Nơi em sống có thể là làng quê hoặc thành phố.",emoji:"🏡🏙️",answer:!0,explain:"Đúng. Mỗi bạn sống ở một nơi khác nhau."},{id:"tnxh1-noi-em-song-11",type:"multi",q:"Việc làm nào giữ công viên sạch đẹp?",emoji:"🌷",options:["Bỏ rác vào thùng","Viết bậy lên ghế đá","Không bẻ cây hái hoa"],answers:[0,2],explain:"Bỏ rác đúng chỗ, không bẻ cây giúp công viên đẹp."},{id:"tnxh1-noi-em-song-12",type:"match",q:"Nối cảnh với nơi thường thấy.",pairs:[["Cánh đồng lúa","Làng quê"],["Nhà cao tầng","Thành phố"],["Nhà sàn trên sườn đồi","Miền núi"]],explain:"Mỗi vùng có cảnh vật riêng."},{id:"tnxh1-noi-em-song-13",type:"tf",q:"Ở chợ, em có thể chạy nhảy, xô đẩy người khác.",emoji:"🛒",answer:!1,explain:"Sai. Chợ đông người, em đi cạnh người lớn và không chạy nhảy."},{id:"tnxh1-noi-em-song-14",type:"mc",q:"Ở nơi công cộng đông người, em cần làm gì?",emoji:"👨‍👧",options:["Đi sát bên người lớn","Đi theo một người lạ","Chạy đi chơi một mình"],answer:0,explain:"Nơi đông người dễ bị lạc. Em đi sát người lớn."},{id:"tnxh1-noi-em-song-15",type:"tf",q:"Người dân ở làng quê và thành phố đều cần chợ, trường, trạm y tế.",emoji:"🏘️",answer:!0,explain:"Đúng. Ở đâu con người cũng cần học tập, mua bán, khám bệnh."},{id:"tnxh1-noi-em-song-16",type:"mc",q:"Em bị lạc ở chợ. Em nên làm gì?",emoji:"😟",options:["Đi theo một người lạ bất kì về nhà người đó","Đứng yên, nhờ cô chú bán hàng hoặc bảo vệ giúp","Chạy một mình ra đường lớn tìm bố mẹ"],answer:1,explain:"Bị lạc, em đứng yên và nhờ người tin cậy ở đó giúp gọi bố mẹ."}]},{questions:[{id:"tnxh1-noi-em-song-17",type:"mc",q:"Nhà Phúc gần biển. Cảnh nào Phúc hay thấy?",emoji:"⛵",options:["Tàu điện ngầm","Thuyền đánh cá","Ruộng bậc thang"],answer:1,explain:"Gần biển thường có thuyền đánh cá."},{id:"tnxh1-noi-em-song-18",type:"mc",q:"Em thấy vòi nước công cộng bị chảy mãi. Em làm gì?",emoji:"🚰",options:["Mở vòi nước to hơn nữa","Mặc kệ cho nước chảy mãi như thế","Khóa vòi lại hoặc báo người lớn"],answer:2,explain:"Khóa vòi để tiết kiệm nước."},{id:"tnxh1-noi-em-song-19",type:"tf",q:"Ngọc nhặt vỏ hộp sữa ở công viên bỏ vào thùng rác. Ngọc làm đúng.",emoji:"🧃",answer:!0,explain:"Đúng. Ngọc giúp nơi công cộng sạch đẹp."},{id:"tnxh1-noi-em-song-20",type:"tf",q:"Tùng hái hoa ở công viên mang về nhà. Tùng làm đúng.",emoji:"🌸",answer:!1,explain:"Sai. Hoa ở công viên là để mọi người cùng ngắm."},{id:"tnxh1-noi-em-song-21",type:"multi",q:"Ở quê, Nam có thể thấy những gì?",emoji:"🏡",options:["Ao cá","Đồng lúa","Rất nhiều nhà chọc trời","Lũy tre"],answers:[0,1,3],explain:"Làng quê có đồng lúa, ao cá, lũy tre."},{id:"tnxh1-noi-em-song-22",type:"order",q:"Sắp xếp các việc khi em cùng mẹ đi chợ.",emoji:"🛍️",items:["Nắm tay mẹ","Đi theo mẹ mua đồ","Xách giúp mẹ túi nhẹ","Cùng mẹ về nhà"],explain:"Đi chợ, em nắm tay mẹ, theo mẹ mua đồ, xách đồ nhẹ rồi về nhà."},{id:"tnxh1-noi-em-song-23",type:"mc",q:"Cách nào giúp nơi em sống thêm xanh?",emoji:"🌳",options:["Trồng cây xanh","Chặt hết cây","Đốt rác bừa bãi"],answer:0,explain:"Trồng cây giúp nơi ở xanh và mát."},{id:"tnxh1-noi-em-song-24",type:"fill",q:"Nơi mọi người đến mua bán rau, thịt, cá là cái …",emoji:"🛒",answer:["chợ"],loose:!0,explain:"Đó là cái chợ."}]}],challenge:{questions:[{id:"tnxh1-noi-em-song-25",type:"match",q:"Nối vùng với cảnh vật.",pairs:[["Miền biển","Bãi cát, thuyền"],["Miền núi","Ruộng bậc thang"],["Thành phố","Nhà cao tầng"],["Làng quê đồng bằng","Đồng lúa rộng"]],explain:"Mỗi vùng có cảnh vật riêng."},{id:"tnxh1-noi-em-song-26",type:"multi",q:"Nơi nào em có thể đến khi bị ốm?",emoji:"🏥",options:["Trạm y tế","Bệnh viện","Rạp chiếu phim"],answers:[0,1],explain:"Trạm y tế, bệnh viện là nơi khám chữa bệnh."},{id:"tnxh1-noi-em-song-27",type:"tf",q:"Giữ nơi công cộng sạch đẹp là việc của tất cả mọi người.",emoji:"🤝",answer:!0,explain:"Đúng. Ai cũng cần chung tay giữ gìn."},{id:"tnxh1-noi-em-song-28",type:"mc",q:"Vì sao không vứt rác xuống ao hồ?",emoji:"🐟",options:["Vì rác làm cho ao to ra","Vì làm nước bẩn, cá có thể chết","Vì rác nổi trên mặt nước rất đẹp"],answer:1,explain:"Rác làm nước bẩn, hại cá và cây."},{id:"tnxh1-noi-em-song-16",type:"mc",q:"Em bị lạc ở chợ. Em nên làm gì?",emoji:"😟",options:["Đi theo một người lạ bất kì về nhà người đó","Đứng yên, nhờ cô chú bán hàng hoặc bảo vệ giúp","Chạy một mình ra đường lớn tìm bố mẹ"],answer:1,explain:"Bị lạc, em đứng yên và nhờ người tin cậy ở đó giúp gọi bố mẹ."},{id:"tnxh1-noi-em-song-10",type:"tf",q:"Nơi em sống có thể là làng quê hoặc thành phố.",emoji:"🏡🏙️",answer:!0,explain:"Đúng. Mỗi bạn sống ở một nơi khác nhau."}]},summary:["Nơi em sống có thể là làng quê hoặc thành phố.","Em giữ gìn nơi công cộng sạch đẹp."]},{id:"tnxh1-cong-viec",title:"Công việc của mọi người",weeks:[13,14],learn:[{title:"Nhiều nghề",text:"Mọi người làm nhiều nghề khác nhau: nông dân, bác sĩ, giáo viên, công nhân…",example:"👩‍🌾 👨‍⚕️ 👩‍🏫 👷"},{title:"Nghề nào cũng quý",text:"Mỗi nghề đều có ích cho mọi người. Em kính trọng người lao động.",example:"🙏 💪"},{title:"Biết ơn",text:"Em biết ơn bằng cách chào hỏi, cảm ơn và giữ gìn thành quả lao động.",example:"🙇 🍚"}],practice:[{questions:[{id:"tnxh1-cong-viec-01",type:"mc",q:"Ai trồng lúa làm ra hạt gạo?",emoji:"🌾",options:["Chú phi công","Bác nông dân","Cô ca sĩ"],answer:1,explain:"Bác nông dân trồng lúa làm ra hạt gạo."},{id:"tnxh1-cong-viec-02",type:"mc",q:"Ai khám bệnh cho mọi người?",emoji:"🩺",options:["Thợ xây","Bác sĩ","Đầu bếp"],answer:1,explain:"Bác sĩ khám và chữa bệnh."},{id:"tnxh1-cong-viec-03",type:"mc",q:"Ai xây nhà?",emoji:"🧱",options:["Thợ xây","Người đưa thư","Bác sĩ"],answer:0,explain:"Thợ xây xây nhà cửa."},{id:"tnxh1-cong-viec-04",type:"tf",q:"Cô giáo là người khám chữa bệnh cho em.",emoji:"👩‍🏫",answer:!1,explain:"Sai. Cô giáo dạy học, bác sĩ mới khám chữa bệnh."},{id:"tnxh1-cong-viec-05",type:"tf",q:"Chú lính cứu hỏa trồng rau trong vườn.",emoji:"🚒",answer:!1,explain:"Sai. Chú lính cứu hỏa dập lửa, cứu người."},{id:"tnxh1-cong-viec-06",type:"match",q:"Nối người với công việc.",pairs:[["👩‍🌾 Nông dân","Trồng lúa"],["👨‍🍳 Đầu bếp","Nấu ăn"],["👮 Công an","Giữ trật tự, an ninh"],["👨‍⚕️ Bác sĩ","Chữa bệnh"]],explain:"Mỗi người làm một công việc có ích."},{id:"tnxh1-cong-viec-07",type:"multi",q:"Đồ dùng nào của bác sĩ?",emoji:"🩺",options:["Cái cày","Nhiệt kế","Ống nghe"],answers:[1,2],explain:"Bác sĩ dùng ống nghe, nhiệt kế. Cái cày là của nhà nông."},{id:"tnxh1-cong-viec-08",type:"mc",q:"Ai đánh bắt cá trên biển?",emoji:"🎣",options:["Thợ may","Ngư dân","Thợ cắt tóc"],answer:1,explain:"Ngư dân đi thuyền đánh bắt cá."}]},{questions:[{id:"tnxh1-cong-viec-09",type:"mc",q:"Vì sao em cần quý trọng hạt cơm?",emoji:"🍚",options:["Vì hạt cơm có màu trắng tinh","Vì bác nông dân vất vả làm ra","Vì mỗi hạt cơm đều rất nặng"],answer:1,explain:"Hạt gạo do nông dân vất vả trồng, em không bỏ phí."},{id:"tnxh1-cong-viec-10",type:"tf",q:"Nghề nào cũng có ích cho mọi người.",emoji:"💪",answer:!0,explain:"Đúng. Mỗi nghề góp phần giúp cuộc sống tốt đẹp."},{id:"tnxh1-cong-viec-11",type:"tf",q:"Chỉ người làm việc trong văn phòng mới đáng kính trọng.",emoji:"🙏",answer:!1,explain:"Sai. Ai lao động chăm chỉ cũng đáng kính trọng."},{id:"tnxh1-cong-viec-12",type:"multi",q:"Nghề nào làm việc ở bệnh viện?",emoji:"🏥",options:["Bác sĩ","Y tá","Ngư dân"],answers:[0,1],explain:"Bác sĩ, y tá làm ở bệnh viện. Ngư dân đi biển."},{id:"tnxh1-cong-viec-13",type:"match",q:"Nối đồ dùng với nghề.",pairs:[["✂️ Kéo, lược","Thợ cắt tóc"],["🧵 Kim chỉ","Thợ may"],["🎣 Lưới","Ngư dân"]],explain:"Mỗi nghề dùng đồ dùng riêng."},{id:"tnxh1-cong-viec-14",type:"mc",q:"Cô lao công làm việc gì?",emoji:"🧹",options:["Lái máy bay chở khách","Dạy học cho các bạn nhỏ","Quét dọn đường phố sạch sẽ"],answer:2,explain:"Cô lao công giữ đường phố sạch sẽ."},{id:"tnxh1-cong-viec-15",type:"tf",q:"Chú công an giao thông giúp mọi người đi đường an toàn.",emoji:"👮",answer:!0,explain:"Đúng. Chú hướng dẫn xe cộ đi đúng luật."},{id:"tnxh1-cong-viec-16",type:"mc",q:"Người đưa thư làm gì?",emoji:"📮",options:["Mang thư, bưu phẩm đến nhà","Nấu cơm trong nhà hàng","Chữa răng cho bệnh nhân"],answer:0,explain:"Người đưa thư mang thư, bưu phẩm đến cho mọi người."}]},{questions:[{id:"tnxh1-cong-viec-17",type:"mc",q:"Đường phố sạch là nhờ cô lao công. Em làm gì để giúp cô?",emoji:"🧹",options:["Vẽ bậy lên tường","Không vứt rác ra đường","Vứt rác để cô có việc"],answer:1,explain:"Không vứt rác bừa là giúp cô lao công đỡ vất vả."},{id:"tnxh1-cong-viec-18",type:"mc",q:"Bố An là thợ mộc. Bố An làm ra gì?",emoji:"🪚",options:["Bàn ghế, tủ bằng gỗ","Thuốc chữa bệnh cho người","Bánh mì nóng giòn"],answer:0,explain:"Thợ mộc làm đồ dùng bằng gỗ."},{id:"tnxh1-cong-viec-19",type:"tf",q:"Ăn cơm xong, Lan để thừa cơm rơi vãi khắp bàn. Lan quý trọng hạt gạo.",emoji:"🍚",answer:!1,explain:"Sai. Quý hạt gạo là ăn hết, không để rơi vãi."},{id:"tnxh1-cong-viec-20",type:"tf",q:"Minh cảm ơn bác bảo vệ đã mở cổng trường. Minh làm đúng.",emoji:"🙏",answer:!0,explain:"Đúng. Minh biết ơn người lao động."},{id:"tnxh1-cong-viec-21",type:"mc",q:"Nhà bị cháy, ai đến giúp dập lửa và cứu người?",emoji:"🚒",options:["Người bán kem","Thợ cắt tóc","Lính cứu hỏa"],answer:2,explain:"Lính cứu hỏa dập lửa và cứu người."},{id:"tnxh1-cong-viec-22",type:"order",q:"Sắp xếp quá trình làm ra hạt gạo.",emoji:"🌾",items:["Gieo mạ","Cấy lúa","Chăm sóc lúa","Gặt lúa"],explain:"Gieo mạ, cấy lúa, chăm sóc rồi gặt lúa."},{id:"tnxh1-cong-viec-23",type:"mc",q:"Lớn lên Hà muốn chữa bệnh cho mọi người. Hà muốn làm nghề gì?",emoji:"👩‍⚕️",options:["Bác sĩ","Thợ xây","Ngư dân"],answer:0,explain:"Bác sĩ là người chữa bệnh."},{id:"tnxh1-cong-viec-24",type:"fill",q:"Người trồng lúa được gọi là nông …",emoji:"👩‍🌾",answer:["dân"],loose:!0,explain:"Người trồng lúa là nông dân."}]}],challenge:{questions:[{id:"tnxh1-cong-viec-25",type:"match",q:"Nối nơi làm việc với nghề.",pairs:[["Đồng ruộng","Nông dân"],["Bệnh viện","Bác sĩ"],["Trường học","Giáo viên"],["Công trường","Thợ xây"]],explain:"Mỗi nghề làm việc ở nơi khác nhau."},{id:"tnxh1-cong-viec-26",type:"multi",q:"Việc làm nào thể hiện biết ơn người lao động?",emoji:"🙏",options:["Xé sách vở","Chào hỏi lễ phép","Giữ gìn bàn ghế","Ăn hết suất cơm"],answers:[1,2,3],explain:"Ăn hết cơm, giữ gìn đồ dùng, chào hỏi là biết ơn."},{id:"tnxh1-cong-viec-27",type:"mc",q:"Khi cần gọi công an giúp đỡ, em gọi số nào?",emoji:"👮",options:["113","115","114"],answer:0,explain:"Gọi công an: số 113."},{id:"tnxh1-cong-viec-28",type:"tf",q:"Người lao động chỉ làm việc vào ban ngày.",emoji:"🌙",answer:!1,explain:"Sai. Có người làm cả ban đêm như bác sĩ trực, bác bảo vệ."},{id:"tnxh1-cong-viec-09",type:"mc",q:"Vì sao em cần quý trọng hạt cơm?",emoji:"🍚",options:["Vì hạt cơm có màu trắng tinh","Vì bác nông dân vất vả làm ra","Vì mỗi hạt cơm đều rất nặng"],answer:1,explain:"Hạt gạo do nông dân vất vả trồng, em không bỏ phí."},{id:"tnxh1-cong-viec-22",type:"order",q:"Sắp xếp quá trình làm ra hạt gạo.",emoji:"🌾",items:["Gieo mạ","Cấy lúa","Chăm sóc lúa","Gặt lúa"],explain:"Gieo mạ, cấy lúa, chăm sóc rồi gặt lúa."}]},summary:["Mọi người làm nhiều nghề khác nhau.","Nghề nào cũng có ích, em kính trọng và biết ơn người lao động."]},{id:"tnxh1-di-duong-an-toan",title:"Đi đường an toàn",weeks:[15,16],learn:[{title:"Đèn tín hiệu",text:"Đèn đỏ: dừng lại. Đèn vàng: chuẩn bị dừng lại. Đèn xanh: được đi.",example:"🔴 🟡 🟢"},{title:"Đi bộ",text:"Em đi trên vỉa hè. Đường không có vỉa hè thì đi sát mép đường.",example:"🚶 🛣️"},{title:"Qua đường",text:"Em qua đường cùng người lớn, ở chỗ có vạch kẻ cho người đi bộ.",example:"🦓 👨‍👧"},{title:"Mũ bảo hiểm",text:"Ngồi sau xe máy, em đội mũ bảo hiểm và cài quai.",example:"⛑️ 🏍️"}],practice:[{questions:[{id:"tnxh1-di-duong-an-toan-01",type:"mc",q:"Đèn tín hiệu màu gì thì phải dừng lại?",emoji:"🚦",options:["Đèn đỏ","Đèn vàng","Đèn xanh"],answer:0,explain:"Đèn đỏ thì dừng lại."},{id:"tnxh1-di-duong-an-toan-02",type:"mc",q:"Đèn tín hiệu màu gì thì được đi?",emoji:"🚦",options:["Đèn xanh","Đèn vàng","Đèn đỏ"],answer:0,explain:"Đèn xanh thì được đi."},{id:"tnxh1-di-duong-an-toan-03",type:"mc",q:"Người đi bộ đi ở đâu?",emoji:"🚶",options:["Giữa lòng đường","Trên vỉa hè","Trên dải phân cách"],answer:1,explain:"Người đi bộ đi trên vỉa hè."},{id:"tnxh1-di-duong-an-toan-04",type:"tf",q:"Ngồi sau xe máy, em phải đội mũ bảo hiểm.",emoji:"⛑️",answer:!0,explain:"Đúng. Mũ bảo hiểm bảo vệ đầu khi có va chạm."},{id:"tnxh1-di-duong-an-toan-05",type:"tf",q:"Chơi đá bóng dưới lòng đường là an toàn.",emoji:"⚽",answer:!1,explain:"Sai. Lòng đường có xe cộ qua lại rất nguy hiểm."},{id:"tnxh1-di-duong-an-toan-06",type:"match",q:"Nối màu đèn với việc cần làm.",pairs:[["🔴 Đỏ","Dừng lại"],["🟡 Vàng","Chuẩn bị dừng lại"],["🟢 Xanh","Được đi"]],explain:"Nhớ: đỏ dừng lại, vàng chuẩn bị dừng, xanh được đi."},{id:"tnxh1-di-duong-an-toan-07",type:"multi",q:"Việc nào an toàn khi đi đường?",emoji:"🛣️",options:["Nắm tay người lớn khi qua đường","Đội mũ bảo hiểm khi đi xe máy","Đi trên vỉa hè","Chạy băng qua đường"],answers:[0,1,2],explain:"Đi vỉa hè, nắm tay người lớn, đội mũ bảo hiểm là an toàn."},{id:"tnxh1-di-duong-an-toan-08",type:"mc",q:"Em qua đường ở chỗ nào là an toàn nhất?",emoji:"🦓",options:["Chỗ có vạch kẻ cho người đi bộ","Giữa hai xe ô tô đang đỗ","Ở ngay chỗ khúc cua của đường"],answer:0,explain:"Qua đường ở chỗ có vạch kẻ cho người đi bộ, cùng người lớn."}]},{questions:[{id:"tnxh1-di-duong-an-toan-09",type:"mc",q:"Vì sao phải đội mũ bảo hiểm khi ngồi xe máy?",emoji:"⛑️",options:["Để cho tóc mọc nhanh hơn","Để nhìn đường rõ hơn","Để bảo vệ đầu khi bị ngã"],answer:2,explain:"Mũ bảo hiểm giúp bảo vệ đầu."},{id:"tnxh1-di-duong-an-toan-10",type:"tf",q:"Khi ngồi trên xe máy, em có thể đứng lên hoặc buông tay.",emoji:"🏍️",answer:!1,explain:"Sai. Em ngồi yên, bám chắc người ngồi trước để không bị ngã."},{id:"tnxh1-di-duong-an-toan-11",type:"tf",q:"Đội mũ bảo hiểm mà không cài quai cũng an toàn.",emoji:"⛑️",answer:!1,explain:"Sai. Không cài quai, mũ dễ rơi ra khi có va chạm."},{id:"tnxh1-di-duong-an-toan-12",type:"multi",q:"Việc làm nào nguy hiểm khi đi đường?",emoji:"⚠️",options:["Đi trên vỉa hè","Đùa nghịch dưới lòng đường","Thò tay, chân ra ngoài khi ngồi xe"],answers:[1,2],explain:"Đùa nghịch dưới lòng đường, thò tay chân ra ngoài xe rất nguy hiểm."},{id:"tnxh1-di-duong-an-toan-13",type:"mc",q:"Đèn vàng bật sáng. Xe cần làm gì?",emoji:"🟡",options:["Đi nhanh hơn nữa","Quay đầu xe lại","Chuẩn bị dừng lại"],answer:2,explain:"Đèn vàng báo xe chuẩn bị dừng lại."},{id:"tnxh1-di-duong-an-toan-14",type:"match",q:"Nối phương tiện với nơi đi.",pairs:[["🚗 Ô tô","Đường bộ"],["⛵ Thuyền","Đường thủy"],["✈️ Máy bay","Đường hàng không"]],explain:"Mỗi phương tiện đi trên một loại đường."},{id:"tnxh1-di-duong-an-toan-15",type:"tf",q:"Qua đường, em nhìn trái, nhìn phải xem có xe không.",emoji:"👀",answer:!0,explain:"Đúng. Quan sát kĩ trước khi qua đường."},{id:"tnxh1-di-duong-an-toan-16",type:"mc",q:"Trên xe buýt, em nên làm gì?",emoji:"🚌",options:["Thò đầu ra ngoài cửa sổ xe","Ngồi yên hoặc bám chắc tay vịn","Chạy lên chạy xuống trong xe"],answer:1,explain:"Ngồi yên, bám chắc để không bị ngã."}]},{questions:[{id:"tnxh1-di-duong-an-toan-17",type:"mc",q:"Đường đến trường của Chi không có vỉa hè. Chi đi thế nào?",emoji:"🚶‍♀️",options:["Đi sát mép đường","Đi giữa đường","Vừa đi vừa chạy nhảy"],answer:0,explain:"Không có vỉa hè thì đi sát mép đường."},{id:"tnxh1-di-duong-an-toan-18",type:"mc",q:"Quả bóng lăn ra lòng đường đông xe. Em làm gì?",emoji:"⚽",options:["Nhờ người lớn nhặt giúp","Đuổi theo quả bóng ngay","Chạy ra giữa đường nhặt bóng"],answer:0,explain:"Chạy ra đường rất nguy hiểm. Em nhờ người lớn."},{id:"tnxh1-di-duong-an-toan-19",type:"tf",q:"Bố chở Nam đi học. Nam đội mũ bảo hiểm và cài quai. Nam làm đúng.",emoji:"⛑️",answer:!0,explain:"Đúng. Nam giữ an toàn khi đi xe máy."},{id:"tnxh1-di-duong-an-toan-20",type:"tf",q:"Vy tự chạy qua đường một mình khi xe đông. Vy làm đúng.",emoji:"🚗",answer:!1,explain:"Sai. Vy cần người lớn dắt qua đường."},{id:"tnxh1-di-duong-an-toan-21",type:"order",q:"Sắp xếp các bước qua đường an toàn cùng người lớn.",emoji:"🦓",items:["Đứng chờ ở mép đường","Nhìn trái, nhìn phải","Nắm tay người lớn","Đi qua đường ở vạch kẻ"],explain:"Dừng ở mép đường, quan sát, nắm tay người lớn rồi đi theo vạch kẻ."},{id:"tnxh1-di-duong-an-toan-22",type:"multi",q:"Ngồi trên ô tô, em làm gì cho an toàn?",emoji:"🚗",options:["Thắt dây an toàn","Ngồi yên ở ghế","Thò tay ra cửa sổ"],answers:[0,1],explain:"Thắt dây an toàn và ngồi yên giúp em an toàn."},{id:"tnxh1-di-duong-an-toan-23",type:"mc",q:"Đèn tín hiệu cho người đi bộ đang đỏ. Em làm gì?",emoji:"🚦",options:["Đứng chờ","Nhảy qua lan can","Chạy thật nhanh qua"],answer:0,explain:"Đèn đỏ thì đứng chờ."},{id:"tnxh1-di-duong-an-toan-24",type:"fill",q:"Đèn tín hiệu màu … thì phải dừng lại.",emoji:"🚦",answer:["đỏ"],loose:!0,explain:"Đèn đỏ: dừng lại."}]}],challenge:{questions:[{id:"tnxh1-di-duong-an-toan-25",type:"mc",q:"Vì sao trẻ nhỏ cần người lớn dắt khi qua đường?",emoji:"👨‍👧",options:["Vì con đường lúc nào cũng rất đẹp","Vì trẻ nhỏ khó nhìn và đoán xe cộ","Vì trẻ nhỏ luôn đi rất nhanh"],answer:1,explain:"Trẻ nhỏ thấp, khó quan sát xe nên cần người lớn dắt."},{id:"tnxh1-di-duong-an-toan-26",type:"match",q:"Nối tình huống với việc nên làm.",pairs:[["Ngồi sau xe máy","Đội mũ bảo hiểm"],["Ngồi trên ô tô","Thắt dây an toàn"],["Đi bộ trên phố","Đi trên vỉa hè"],["Qua đường","Nắm tay người lớn"]],explain:"Mỗi lúc đi đường đều có cách giữ an toàn."},{id:"tnxh1-di-duong-an-toan-27",type:"tf",q:"Khi xuống xe buýt, em chờ xe dừng hẳn rồi mới bước xuống.",emoji:"🚌",answer:!0,explain:"Đúng. Xuống khi xe còn chạy rất dễ ngã."},{id:"tnxh1-di-duong-an-toan-28",type:"multi",q:"Những ai cần đội mũ bảo hiểm khi đi xe máy?",emoji:"⛑️",options:["Người ngồi sau","Người lái xe","Trẻ em ngồi trên xe"],answers:[0,1,2],explain:"Tất cả mọi người đi xe máy đều phải đội mũ bảo hiểm."},{id:"tnxh1-di-duong-an-toan-14",type:"match",q:"Nối phương tiện với nơi đi.",pairs:[["🚗 Ô tô","Đường bộ"],["⛵ Thuyền","Đường thủy"],["✈️ Máy bay","Đường hàng không"]],explain:"Mỗi phương tiện đi trên một loại đường."},{id:"tnxh1-di-duong-an-toan-18",type:"mc",q:"Quả bóng lăn ra lòng đường đông xe. Em làm gì?",emoji:"⚽",options:["Nhờ người lớn nhặt giúp","Đuổi theo quả bóng ngay","Chạy ra giữa đường nhặt bóng"],answer:0,explain:"Chạy ra đường rất nguy hiểm. Em nhờ người lớn."}]},summary:["Đèn đỏ dừng lại, đèn vàng chuẩn bị dừng, đèn xanh được đi.","Em đi trên vỉa hè, qua đường cùng người lớn.","Đi xe máy, em đội mũ bảo hiểm và cài quai."]},{id:"tnxh1-tet-va-ngay-vui",title:"Ngày vui ở quê hương em",weeks:[16,17],learn:[{title:"Tết Nguyên đán",text:"Tết Nguyên đán là Tết cổ truyền. Cả nhà sum họp, chúc Tết ông bà.",example:"🧧 🎆 🏠"},{title:"Món ăn ngày Tết",text:"Ngày Tết thường có bánh chưng hoặc bánh tét, có hoa đào hoặc hoa mai.",example:"🟩 🌸 🌼"},{title:"Tết Trung thu",text:"Tết Trung thu là Tết của thiếu nhi. Các bạn rước đèn, phá cỗ, ăn bánh trung thu.",example:"🏮 🌕 🥮"}],practice:[{questions:[{id:"tnxh1-tet-va-ngay-vui-01",type:"mc",q:"Ngày Tết, cả nhà thường làm gì?",emoji:"🧧",options:["Sum họp, chúc Tết ông bà","Không gặp ai","Ai cũng đi ngủ cả ngày"],answer:0,explain:"Ngày Tết cả nhà sum họp, chúc Tết ông bà."},{id:"tnxh1-tet-va-ngay-vui-02",type:"mc",q:"Bánh nào thường có trong ngày Tết Nguyên đán?",emoji:"🟩",options:["Bánh kem","Bánh chưng","Bánh sinh nhật"],answer:1,explain:"Bánh chưng là bánh truyền thống ngày Tết."},{id:"tnxh1-tet-va-ngay-vui-03",type:"mc",q:"Tết Trung thu, các bạn nhỏ thường làm gì?",emoji:"🏮",options:["Gói bánh chưng","Đi tắm biển","Rước đèn, phá cỗ"],answer:2,explain:"Trung thu, các bạn nhỏ rước đèn, phá cỗ."},{id:"tnxh1-tet-va-ngay-vui-04",type:"tf",q:"Tết Trung thu chỉ dành cho người lớn.",emoji:"🌕",answer:!1,explain:"Sai. Tết Trung thu là Tết của thiếu nhi."},{id:"tnxh1-tet-va-ngay-vui-05",type:"tf",q:"Ngày Tết, em chúc ông bà mạnh khỏe, sống lâu.",emoji:"👴👵",answer:!0,explain:"Đúng. Em chúc Tết ông bà lễ phép."},{id:"tnxh1-tet-va-ngay-vui-06",type:"match",q:"Nối ngày vui với hình ảnh.",pairs:[["Tết Nguyên đán","🧧 Bao lì xì"],["Tết Trung thu","🏮 Đèn ông sao"],["Ngày sinh nhật","🎂 Bánh kem có nến"]],explain:"Mỗi ngày vui có hình ảnh đặc trưng."},{id:"tnxh1-tet-va-ngay-vui-07",type:"multi",q:"Hoa nào thường dùng trang trí ngày Tết?",emoji:"🌸",options:["Hoa đào","Hoa mai","Hoa súng dưới ao"],answers:[0,1],explain:"Hoa đào, hoa mai thường dùng trang trí ngày Tết."},{id:"tnxh1-tet-va-ngay-vui-08",type:"tf",q:"Tết Trung thu có bánh chưng là món chính.",emoji:"🥮",answer:!1,explain:"Sai. Trung thu có bánh nướng, bánh dẻo. Bánh chưng có vào Tết Nguyên đán."}]},{questions:[{id:"tnxh1-tet-va-ngay-vui-09",type:"mc",q:"Vì sao Tết là dịp vui của gia đình?",emoji:"🏠",options:["Vì không phải ăn cơm","Vì được thức khuya chơi điện thoại","Vì cả nhà sum họp bên nhau"],answer:2,explain:"Tết là dịp cả nhà quây quần, sum họp."},{id:"tnxh1-tet-va-ngay-vui-10",type:"tf",q:"Trước Tết, nhà em thường dọn dẹp cho sạch đẹp.",emoji:"🧹",answer:!0,explain:"Đúng. Nhà cửa được dọn dẹp, trang trí đón Tết."},{id:"tnxh1-tet-va-ngay-vui-11",type:"multi",q:"Ngày Tết, em có thể làm gì?",emoji:"🎉",options:["Giúp mẹ dọn nhà","Đi chơi cùng gia đình","Cãi nhau với anh chị","Chúc Tết ông bà"],answers:[0,1,3],explain:"Chúc Tết, dọn nhà, đi chơi cùng gia đình là việc vui ngày Tết."},{id:"tnxh1-tet-va-ngay-vui-12",type:"mc",q:"Nhận quà mừng tuổi, em làm gì?",emoji:"🧧",options:["Mở ra xem ngay và chê ít","Nhận bằng hai tay và cảm ơn","Giật lấy bao lì xì"],answer:1,explain:"Em nhận bằng hai tay và nói lời cảm ơn."},{id:"tnxh1-tet-va-ngay-vui-13",type:"match",q:"Nối món ăn với ngày Tết.",pairs:[["🥮 Bánh nướng, bánh dẻo","Tết Trung thu"],["🟩 Bánh chưng","Tết Nguyên đán"],["🎂 Bánh kem có nến","Ngày sinh nhật"]],explain:"Mỗi dịp có món ăn riêng."},{id:"tnxh1-tet-va-ngay-vui-14",type:"tf",q:"Ngày Tết, em được đốt pháo nổ cho vui.",emoji:"🚫",answer:!1,explain:"Sai. Pháo nổ rất nguy hiểm và bị cấm."},{id:"tnxh1-tet-va-ngay-vui-15",type:"mc",q:"Tết Trung thu vào đêm trăng như thế nào?",emoji:"🌕",options:["Trăng khuyết một nửa","Trăng tròn và sáng","Không có trăng"],answer:1,explain:"Trung thu vào đêm rằm, trăng tròn và sáng."},{id:"tnxh1-tet-va-ngay-vui-16",type:"tf",q:"Bánh tét thường được gói ngày Tết ở miền Nam.",emoji:"🍙",answer:!0,explain:"Đúng. Bánh tét là bánh Tết quen thuộc ở miền Nam."}]},{questions:[{id:"tnxh1-tet-va-ngay-vui-17",type:"mc",q:"Ngày mùng Một Tết, em đến nhà ông bà. Em nói gì?",emoji:"👴",options:["Không nói gì, đi thẳng vào nhà","Ông bà cho cháu tiền đi!","Cháu chúc ông bà mạnh khỏe ạ!"],answer:2,explain:"Em chúc Tết ông bà lễ phép."},{id:"tnxh1-tet-va-ngay-vui-18",type:"mc",q:"Đêm Trung thu, lớp em rước đèn. Em làm gì cho an toàn?",emoji:"🏮",options:["Rời hàng, chạy ra đường lớn chơi","Đi theo hàng, có người lớn đi cùng","Giành đèn của bạn rồi chạy đi"],answer:1,explain:"Rước đèn cần đi theo hàng, có người lớn trông."},{id:"tnxh1-tet-va-ngay-vui-19",type:"tf",q:"Lan giúp bà gói bánh chưng. Lan làm đúng.",emoji:"🟩",answer:!0,explain:"Đúng. Lan giúp đỡ bà ngày Tết."},{id:"tnxh1-tet-va-ngay-vui-20",type:"tf",q:"Ngày Tết, Bình đòi bố mẹ mua thật nhiều đồ chơi đắt tiền.",emoji:"🧸",answer:!1,explain:"Sai. Bình nên biết đủ, không đòi hỏi."},{id:"tnxh1-tet-va-ngay-vui-21",type:"multi",q:"Đồ vật nào thường thấy vào Tết Trung thu?",emoji:"🌕",options:["Mâm cỗ hoa quả","Đèn ông sao","Đèn lồng","Cây thông Nô-en"],answers:[0,1,2],explain:"Trung thu có đèn ông sao, đèn lồng, mâm cỗ. Cây thông Nô-en dùng dịp Giáng sinh."},{id:"tnxh1-tet-va-ngay-vui-22",type:"order",q:"Sắp xếp các việc gói bánh chưng.",emoji:"🟩",items:["Rửa lá dong","Gói bánh","Luộc bánh","Vớt bánh ra"],explain:"Rửa lá, gói bánh, luộc bánh rồi vớt bánh ra."},{id:"tnxh1-tet-va-ngay-vui-23",type:"mc",q:"Mâm cỗ Trung thu thường có gì?",emoji:"🥮",options:["Bánh kem có nến","Bánh trung thu, hoa quả","Bánh chưng, dưa hành"],answer:1,explain:"Mâm cỗ Trung thu có bánh trung thu, hoa quả."},{id:"tnxh1-tet-va-ngay-vui-24",type:"fill",q:"Tết Trung thu, các bạn nhỏ rước …",emoji:"🏮",answer:["đèn"],loose:!0,explain:"Trung thu các bạn rước đèn."}]}],challenge:{questions:[{id:"tnxh1-tet-va-ngay-vui-25",type:"match",q:"Nối ngày lễ với việc làm.",pairs:[["Tết Nguyên đán","Chúc Tết ông bà"],["Tết Trung thu","Rước đèn"],["Sinh nhật bạn","Hát chúc mừng"]],explain:"Mỗi ngày vui có hoạt động riêng."},{id:"tnxh1-tet-va-ngay-vui-26",type:"multi",q:"Ngày Tết, việc nào em nên làm?",emoji:"🎆",options:["Chơi pháo nổ","Nói lời chúc tốt đẹp","Giữ an toàn, không nghịch lửa"],answers:[1,2],explain:"Em chúc Tết và giữ an toàn. Pháo nổ bị cấm và nguy hiểm."},{id:"tnxh1-tet-va-ngay-vui-27",type:"tf",q:"Ngày Tết, nhiều gia đình đi thăm họ hàng.",emoji:"🏡",answer:!0,explain:"Đúng. Tết là dịp thăm hỏi họ hàng."},{id:"tnxh1-tet-va-ngay-vui-28",type:"mc",q:"Vì sao Tết Trung thu gọi là Tết của thiếu nhi?",emoji:"🧒",options:["Vì chỉ trẻ em mới thấy trăng","Vì người lớn không được ăn bánh","Vì có nhiều trò vui dành cho trẻ em"],answer:2,explain:"Trung thu có rước đèn, phá cỗ dành cho trẻ em."},{id:"tnxh1-tet-va-ngay-vui-13",type:"match",q:"Nối món ăn với ngày Tết.",pairs:[["🥮 Bánh nướng, bánh dẻo","Tết Trung thu"],["🟩 Bánh chưng","Tết Nguyên đán"],["🎂 Bánh kem có nến","Ngày sinh nhật"]],explain:"Mỗi dịp có món ăn riêng."},{id:"tnxh1-tet-va-ngay-vui-19",type:"tf",q:"Lan giúp bà gói bánh chưng. Lan làm đúng.",emoji:"🟩",answer:!0,explain:"Đúng. Lan giúp đỡ bà ngày Tết."}]},summary:["Tết Nguyên đán cả nhà sum họp, chúc Tết ông bà.","Tết Trung thu là Tết của thiếu nhi.","Em vui Tết an toàn, lễ phép."]}]},{id:"thuc-vat-dong-vat",title:"Thực vật và động vật",lessons:[{id:"tnxh1-cay-quanh-em",title:"Cây xung quanh em",weeks:[18,19],learn:[{title:"Nhiều loại cây",text:"Quanh em có cây rau, cây ăn quả, cây hoa, cây bóng mát.",example:"🥬 🍊 🌹 🌳"},{title:"Cây khác nhau",text:"Cây có cây cao, cây thấp, cây to, cây nhỏ. Lá cây có nhiều hình dạng.",example:"🌴 🌱 🍁 🍃"},{title:"Lợi ích của cây",text:"Cây cho ta rau, quả, bóng mát, hoa đẹp và làm không khí trong lành.",example:"🥕 🍎 🌳 🌸"}],practice:[{questions:[{id:"tnxh1-cay-quanh-em-01",type:"mc",q:"Cây nào là cây rau?",emoji:"🥬",options:["Cây phượng","Cây rau cải","Cây hoa hồng"],answer:1,explain:"Rau cải là cây rau, dùng để nấu ăn."},{id:"tnxh1-cay-quanh-em-02",type:"mc",q:"Cây nào là cây ăn quả?",emoji:"🍊",options:["Cây cam","Cây hoa cúc","Cây rau muống"],answer:0,explain:"Cây cam cho quả cam để ăn."},{id:"tnxh1-cay-quanh-em-03",type:"mc",q:"Cây nào là cây hoa?",emoji:"🌹",options:["Cây bàng","Cây rau ngót","Cây hoa hồng"],answer:2,explain:"Hoa hồng là cây hoa, trồng để làm đẹp."},{id:"tnxh1-cay-quanh-em-04",type:"tf",q:"Cây bàng cho bóng mát.",emoji:"🌳",answer:!0,explain:"Đúng. Cây bàng có tán lá rộng, cho bóng mát."},{id:"tnxh1-cay-quanh-em-05",type:"tf",q:"Tất cả các cây đều cao như nhau.",emoji:"🌴🌱",answer:!1,explain:"Sai. Có cây cao, có cây thấp."},{id:"tnxh1-cay-quanh-em-06",type:"match",q:"Nối cây với nhóm cây.",pairs:[["🥬 Bắp cải","Cây rau"],["🍌 Cây chuối","Cây ăn quả"],["🌻 Hướng dương","Cây hoa"]],explain:"Cây được chia thành nhiều nhóm theo lợi ích."},{id:"tnxh1-cay-quanh-em-07",type:"multi",q:"Cây nào là cây ăn quả?",emoji:"🥭",options:["Cây rau cải","Cây bưởi","Cây ổi","Cây xoài"],answers:[1,2,3],explain:"Xoài, ổi, bưởi là cây ăn quả. Rau cải là cây rau."},{id:"tnxh1-cay-quanh-em-08",type:"mc",q:"Cây nào thường được trồng để lấy bóng mát?",emoji:"🌳",options:["Cây phượng","Cây rau muống","Cây hành"],answer:0,explain:"Cây phượng to, tán rộng, cho bóng mát."}]},{questions:[{id:"tnxh1-cay-quanh-em-09",type:"mc",q:"Vì sao nên trồng nhiều cây xanh?",emoji:"🌳",options:["Để đường phố có thật nhiều rác hơn","Để con đường hẹp lại, khó đi hơn","Để có bóng mát và không khí trong lành"],answer:2,explain:"Cây xanh cho bóng mát, làm không khí trong lành."},{id:"tnxh1-cay-quanh-em-10",type:"tf",q:"Cây có thể cho ta thức ăn.",emoji:"🥕🍎",answer:!0,explain:"Đúng. Ta ăn rau, quả, củ… từ cây."},{id:"tnxh1-cay-quanh-em-11",type:"tf",q:"Cây hoa chỉ để ăn, không để làm đẹp.",emoji:"🌷",answer:!1,explain:"Sai. Cây hoa thường trồng để làm đẹp."},{id:"tnxh1-cay-quanh-em-12",type:"multi",q:"Cây có ích gì cho con người?",emoji:"🌿",options:["Làm đường bẩn","Cho bóng mát","Làm không khí trong lành","Cho rau, quả để ăn"],answers:[1,2,3],explain:"Cây cho thức ăn, bóng mát và không khí trong lành."},{id:"tnxh1-cay-quanh-em-13",type:"match",q:"Nối cây với thứ ta lấy từ cây.",pairs:[["🍉 Cây dưa hấu","Quả để ăn"],["🌳 Cây bàng","Bóng mát"],["🌼 Cây hoa cúc","Hoa đẹp"]],explain:"Mỗi cây cho ta một lợi ích."},{id:"tnxh1-cay-quanh-em-14",type:"mc",q:"Lá cây thường có màu gì?",emoji:"🍃",options:["Màu đen","Màu tím than","Màu xanh"],answer:2,explain:"Đa số lá cây có màu xanh."},{id:"tnxh1-cay-quanh-em-15",type:"tf",q:"Cây nào cũng chỉ sống được trên cạn.",emoji:"🪷",answer:!1,explain:"Sai. Có cây sống dưới nước, ví dụ cây sen."},{id:"tnxh1-cay-quanh-em-16",type:"mc",q:"Cây nào sống dưới nước?",emoji:"🪷",options:["Cây sen","Cây phượng","Cây xoài"],answer:0,explain:"Cây sen sống ở ao, hồ."}]},{questions:[{id:"tnxh1-cay-quanh-em-17",type:"mc",q:"Sân trường nóng nắng. Nên trồng cây gì?",emoji:"☀️",options:["Cây rau mùi","Cây hành","Cây bóng mát"],answer:2,explain:"Cây bóng mát cho sân trường râm mát."},{id:"tnxh1-cay-quanh-em-18",type:"mc",q:"Bà muốn có rau ăn hằng ngày. Bà nên trồng cây gì?",emoji:"🥬",options:["Rau cải, rau muống","Cây phượng ra hoa đỏ","Cây xương rồng"],answer:0,explain:"Rau cải, rau muống là cây rau."},{id:"tnxh1-cay-quanh-em-19",type:"tf",q:"Khoa đi học về thấy chậu cây héo, Khoa tưới nước cho cây. Khoa làm đúng.",emoji:"🪴",answer:!0,explain:"Đúng. Cây cần nước để sống."},{id:"tnxh1-cay-quanh-em-20",type:"tf",q:"Cây cảnh trong nhà không cần chăm sóc.",emoji:"🪴",answer:!1,explain:"Sai. Cây nào cũng cần nước, ánh sáng và chăm sóc."},{id:"tnxh1-cay-quanh-em-21",type:"multi",q:"Vườn nhà Chi có cây cam, cây hoa hồng, cây rau cải. Cây nào cho thức ăn?",emoji:"🏡",options:["Cây rau cải","Cây hoa hồng","Cây cam"],answers:[0,2],explain:"Cam cho quả, rau cải cho rau ăn. Hoa hồng trồng để làm đẹp."},{id:"tnxh1-cay-quanh-em-22",type:"order",q:"Sắp xếp cây theo chiều cao, từ thấp đến cao.",emoji:"🌱",items:["Cây cỏ","Cây hoa hồng","Cây cau"],explain:"Cỏ thấp nhất, rồi đến hoa hồng, cây cau cao nhất."},{id:"tnxh1-cay-quanh-em-23",type:"mc",q:"Em gặp cây có gai. Em nên làm gì?",emoji:"🌵",options:["Ôm thật chặt lấy cây đó","Tránh chạm tay vào gai","Bẻ gai ra để chơi"],answer:1,explain:"Gai cây có thể đâm vào tay. Em tránh chạm vào."},{id:"tnxh1-cay-quanh-em-24",type:"fill",q:"Cây cam, cây xoài là cây ăn …",emoji:"🍊",answer:["quả","trái"],loose:!0,explain:"Cam, xoài là cây ăn quả."}]}],challenge:{questions:[{id:"tnxh1-cay-quanh-em-25",type:"match",q:"Nối cây với nơi sống.",pairs:[["🪷 Cây sen","Ao hồ"],["🌵 Cây xương rồng","Nơi khô, nhiều nắng"],["🌾 Cây lúa","Ruộng nước"]],explain:"Mỗi loại cây sống ở nơi phù hợp."},{id:"tnxh1-cay-quanh-em-26",type:"multi",q:"Cây nào là cây bóng mát thường trồng ở sân trường, đường phố?",emoji:"🌳",options:["Cây bàng","Cây rau cải","Cây phượng"],answers:[0,2],explain:"Bàng, phượng to, tán rộng nên cho bóng mát."},{id:"tnxh1-cay-quanh-em-27",type:"mc",q:"Cây nào vừa cho quả ăn vừa cho bóng mát?",emoji:"🥭",options:["Cây rau cải","Cây hoa cúc","Cây xoài"],answer:2,explain:"Cây xoài to, cho bóng mát và cho quả."},{id:"tnxh1-cay-quanh-em-28",type:"tf",q:"Cây xanh giúp không khí trong lành hơn.",emoji:"🌿",answer:!0,explain:"Đúng. Cây xanh làm không khí trong lành."},{id:"tnxh1-cay-quanh-em-09",type:"mc",q:"Vì sao nên trồng nhiều cây xanh?",emoji:"🌳",options:["Để đường phố có thật nhiều rác hơn","Để con đường hẹp lại, khó đi hơn","Để có bóng mát và không khí trong lành"],answer:2,explain:"Cây xanh cho bóng mát, làm không khí trong lành."},{id:"tnxh1-cay-quanh-em-20",type:"tf",q:"Cây cảnh trong nhà không cần chăm sóc.",emoji:"🪴",answer:!1,explain:"Sai. Cây nào cũng cần nước, ánh sáng và chăm sóc."}]},summary:["Quanh em có cây rau, cây ăn quả, cây hoa, cây bóng mát.","Cây cho ta thức ăn, bóng mát và không khí trong lành."]},{id:"tnxh1-bo-phan-cua-cay",title:"Các bộ phận của cây",weeks:[19,20],learn:[{title:"Các bộ phận",text:"Cây thường có rễ, thân, lá. Nhiều cây còn có hoa và quả.",example:"🌱 🌿 🌸 🍎"},{title:"Rễ và thân",text:"Rễ ở dưới đất, giữ cho cây đứng vững và hút nước. Thân nâng đỡ lá, hoa, quả.",example:"🌳 ⬇️"},{title:"Ăn bộ phận nào?",text:"Ta ăn lá rau cải, quả cà chua, rễ cà rốt, thân cây mía.",example:"🥬 🍅 🥕 🎋"}],practice:[{questions:[{id:"tnxh1-bo-phan-cua-cay-01",type:"mc",q:"Bộ phận nào của cây nằm dưới đất?",emoji:"🌱",options:["Lá","Hoa","Rễ"],answer:2,explain:"Rễ thường nằm dưới đất."},{id:"tnxh1-bo-phan-cua-cay-02",type:"mc",q:"Bộ phận nào giúp cây đứng vững?",emoji:"🌳",options:["Rễ","Hoa","Quả"],answer:0,explain:"Rễ bám chặt vào đất giữ cây đứng vững."},{id:"tnxh1-bo-phan-cua-cay-03",type:"mc",q:"Quả thường mọc ra từ đâu?",emoji:"🌸➡️🍎",options:["Từ hoa","Từ đất","Từ rễ"],answer:0,explain:"Hoa kết thành quả."},{id:"tnxh1-bo-phan-cua-cay-04",type:"tf",q:"Cây thường có rễ, thân, lá.",emoji:"🌿",answer:!0,explain:"Đúng. Rễ, thân, lá là các bộ phận thường có của cây."},{id:"tnxh1-bo-phan-cua-cay-05",type:"tf",q:"Rễ cây mọc trên ngọn cây.",emoji:"🌳",answer:!1,explain:"Sai. Rễ thường ở dưới đất."},{id:"tnxh1-bo-phan-cua-cay-06",type:"match",q:"Nối bộ phận của cây với hình.",pairs:[["Lá","🍃"],["Hoa","🌸"],["Quả","🍎"]],explain:"Lá, hoa, quả là các bộ phận của cây."},{id:"tnxh1-bo-phan-cua-cay-07",type:"multi",q:"Đâu là các bộ phận của cây?",emoji:"🌿",options:["Rễ","Thân","Cánh","Lá"],answers:[0,1,3],explain:"Cây có rễ, thân, lá. Cánh là bộ phận của chim."},{id:"tnxh1-bo-phan-cua-cay-08",type:"mc",q:"Trong quả thường có gì?",emoji:"🍉",options:["Hạt","Rễ","Cành"],answer:0,explain:"Trong quả thường có hạt."}]},{questions:[{id:"tnxh1-bo-phan-cua-cay-09",type:"mc",q:"Rễ cây có nhiệm vụ gì?",emoji:"🌱",options:["Hút nước, giữ cây đứng vững","Giúp cây đi lại khắp vườn","Đón ánh nắng giúp cây"],answer:0,explain:"Rễ hút nước từ đất và giữ cây."},{id:"tnxh1-bo-phan-cua-cay-10",type:"mc",q:"Thân cây có nhiệm vụ gì?",emoji:"🌳",options:["Hút nước từ trong lòng đất","Nâng đỡ lá, hoa, quả","Đón chim đến làm tổ"],answer:1,explain:"Thân nâng đỡ cành, lá, hoa, quả."},{id:"tnxh1-bo-phan-cua-cay-11",type:"tf",q:"Gieo hạt xuống đất, hạt có thể mọc thành cây non.",emoji:"🌰🌱",answer:!0,explain:"Đúng. Hạt gặp đất ẩm sẽ nảy mầm thành cây."},{id:"tnxh1-bo-phan-cua-cay-12",type:"tf",q:"Cây nào cũng có hoa màu đỏ.",emoji:"🌼🌹🌸",answer:!1,explain:"Sai. Hoa có nhiều màu khác nhau."},{id:"tnxh1-bo-phan-cua-cay-13",type:"match",q:"Nối rau, quả với bộ phận ta ăn.",pairs:[["🥬 Rau cải","Lá"],["🍅 Cà chua","Quả"],["🥕 Cà rốt","Rễ"],["🎋 Cây mía","Thân"]],explain:"Ta ăn nhiều bộ phận khác nhau của cây."},{id:"tnxh1-bo-phan-cua-cay-14",type:"multi",q:"Ta ăn quả của những cây nào?",emoji:"🍌",options:["Cây cà chua","Cây chuối","Cây dưa hấu","Cây rau cải"],answers:[0,1,2],explain:"Cà chua, chuối, dưa hấu cho ta quả. Rau cải ta ăn lá."},{id:"tnxh1-bo-phan-cua-cay-15",type:"mc",q:"Ta ăn bộ phận nào của cây cà rốt?",emoji:"🥕",options:["Hoa","Rễ","Quả"],answer:1,explain:"Củ cà rốt là phần rễ của cây."},{id:"tnxh1-bo-phan-cua-cay-16",type:"tf",q:"Khi ăn súp lơ, ta ăn phần rễ của cây.",emoji:"🥦",answer:!1,explain:"Sai. Phần súp lơ ta ăn là hoa của cây."}]},{questions:[{id:"tnxh1-bo-phan-cua-cay-17",type:"mc",q:"Cây con bị nhổ lên, đứt hết rễ. Điều gì có thể xảy ra?",emoji:"🥀",options:["Cây sẽ cao lên nhanh hơn trước","Cây bị héo vì không hút được nước","Cây sẽ ra thật nhiều quả hơn"],answer:1,explain:"Không có rễ, cây không hút được nước nên héo."},{id:"tnxh1-bo-phan-cua-cay-18",type:"mc",q:"Muốn có cây non, Thảo có thể làm gì?",emoji:"🌱",options:["Gieo hạt vào đất ẩm","Bỏ hạt vào tủ lạnh","Ném hạt ra đường"],answer:0,explain:"Hạt gieo vào đất ẩm sẽ nảy mầm."},{id:"tnxh1-bo-phan-cua-cay-19",type:"tf",q:"Cây đậu nảy mầm từ hạt đậu.",emoji:"🫘",answer:!0,explain:"Đúng. Hạt đậu nảy mầm thành cây đậu."},{id:"tnxh1-bo-phan-cua-cay-20",type:"tf",q:"Bẻ hết lá của cây thì cây sẽ lớn nhanh hơn.",emoji:"🍃",answer:!1,explain:"Sai. Lá rất cần cho cây. Bẻ hết lá cây sẽ yếu."},{id:"tnxh1-bo-phan-cua-cay-21",type:"order",q:"Sắp xếp quá trình lớn lên của cây đậu.",emoji:"🌱",items:["Hạt đậu","Hạt nảy mầm","Cây non","Cây ra hoa, có quả"],explain:"Hạt nảy mầm, thành cây non, lớn lên ra hoa, có quả."},{id:"tnxh1-bo-phan-cua-cay-22",type:"multi",q:"Rau nào ta ăn phần lá?",emoji:"🥬",options:["Rau cải","Bắp cải","Cà chua","Rau ngót"],answers:[0,1,3],explain:"Rau cải, bắp cải, rau ngót ta ăn lá. Cà chua ta ăn quả."},{id:"tnxh1-bo-phan-cua-cay-23",type:"mc",q:"Hà chỉ vào phần màu xanh, mỏng, mọc trên cành. Đó là bộ phận gì?",emoji:"🍃",options:["Lá","Rễ","Hạt"],answer:0,explain:"Phần xanh, mỏng mọc trên cành là lá."},{id:"tnxh1-bo-phan-cua-cay-24",type:"fill",q:"Bộ phận của cây ở dưới đất là …",emoji:"🌱",answer:["rễ"],loose:!0,explain:"Rễ cây thường ở dưới đất."}]}],challenge:{questions:[{id:"tnxh1-bo-phan-cua-cay-25",type:"match",q:"Nối bộ phận với việc nó làm.",pairs:[["Rễ","Hút nước"],["Thân","Nâng đỡ cành lá"],["Hoa","Kết thành quả"]],explain:"Mỗi bộ phận của cây có một nhiệm vụ."},{id:"tnxh1-bo-phan-cua-cay-26",type:"multi",q:"Bộ phận nào của cây ta có thể ăn?",emoji:"🥗",options:["Quả cam","Rễ cà rốt","Lá rau cải","Hoa súp lơ"],answers:[0,1,2,3],explain:"Tất cả đều ăn được: lá rau cải, rễ cà rốt, quả cam, hoa súp lơ."},{id:"tnxh1-bo-phan-cua-cay-27",type:"tf",q:"Thân cây mía có vị ngọt, ta ăn được.",emoji:"🎋",answer:!0,explain:"Đúng. Ta ăn thân cây mía."},{id:"tnxh1-bo-phan-cua-cay-28",type:"mc",q:"Cây non cần gì để lớn lên?",emoji:"🌱☀️💧",options:["Kẹo và bánh","Bóng tối hoàn toàn","Nước, ánh sáng và đất"],answer:2,explain:"Cây cần nước, ánh sáng, đất để lớn lên."},{id:"tnxh1-bo-phan-cua-cay-13",type:"match",q:"Nối rau, quả với bộ phận ta ăn.",pairs:[["🥬 Rau cải","Lá"],["🍅 Cà chua","Quả"],["🥕 Cà rốt","Rễ"],["🎋 Cây mía","Thân"]],explain:"Ta ăn nhiều bộ phận khác nhau của cây."},{id:"tnxh1-bo-phan-cua-cay-21",type:"order",q:"Sắp xếp quá trình lớn lên của cây đậu.",emoji:"🌱",items:["Hạt đậu","Hạt nảy mầm","Cây non","Cây ra hoa, có quả"],explain:"Hạt nảy mầm, thành cây non, lớn lên ra hoa, có quả."}]},summary:["Cây thường có rễ, thân, lá; nhiều cây có hoa, quả.","Rễ hút nước, thân nâng đỡ, hoa kết thành quả.","Ta ăn được nhiều bộ phận của cây."]},{id:"tnxh1-con-vat-quanh-em",title:"Con vật xung quanh em",weeks:[20,21],learn:[{title:"Nhiều con vật",text:"Quanh em có nhiều con vật: chó, mèo, gà, cá, chim, bướm…",example:"🐶 🐱 🐔 🐟 🐦 🦋"},{title:"Nơi sống",text:"Có con vật sống trên cạn, có con vật sống dưới nước, có con vật biết bay.",example:"🐄 🐟 🐦"},{title:"Lợi ích",text:"Nhiều con vật có ích: gà đẻ trứng, bò cho sữa, chó trông nhà, mèo bắt chuột.",example:"🥚 🥛 🏠 🐭"}],practice:[{questions:[{id:"tnxh1-con-vat-quanh-em-01",type:"mc",q:"Con vật nào sống dưới nước?",emoji:"🐟",options:["Con cá","Con mèo","Con gà"],answer:0,explain:"Cá sống dưới nước."},{id:"tnxh1-con-vat-quanh-em-02",type:"mc",q:"Con vật nào biết bay?",emoji:"🐦",options:["Con chim","Con lợn","Con chó"],answer:0,explain:"Chim có cánh và biết bay."},{id:"tnxh1-con-vat-quanh-em-03",type:"mc",q:"Con vật nào kêu “meo meo”?",emoji:"🐱",options:["Con vịt","Con bò","Con mèo"],answer:2,explain:"Mèo kêu meo meo."},{id:"tnxh1-con-vat-quanh-em-04",type:"tf",q:"Con gà đẻ trứng.",emoji:"🐔🥚",answer:!0,explain:"Đúng. Gà mái đẻ trứng."},{id:"tnxh1-con-vat-quanh-em-05",type:"tf",q:"Con cá sống trên cây.",emoji:"🐟",answer:!1,explain:"Sai. Cá sống dưới nước."},{id:"tnxh1-con-vat-quanh-em-06",type:"match",q:"Nối con vật với tiếng kêu.",pairs:[["🐶 Chó","Gâu gâu"],["🐱 Mèo","Meo meo"],["🐓 Gà trống","Ò ó o"],["🦆 Vịt","Cạp cạp"]],explain:"Mỗi con vật có tiếng kêu riêng."},{id:"tnxh1-con-vat-quanh-em-07",type:"multi",q:"Con vật nào được nuôi trong nhà?",emoji:"🏠",options:["Con mèo","Con chó","Con gà","Con hổ"],answers:[0,1,2],explain:"Chó, mèo, gà là vật nuôi. Hổ là con vật hoang dã."},{id:"tnxh1-con-vat-quanh-em-08",type:"mc",q:"Con vật nào sống trong rừng?",emoji:"🐒",options:["Con khỉ","Con chó nhà","Con gà"],answer:0,explain:"Khỉ sống trong rừng."}]},{questions:[{id:"tnxh1-con-vat-quanh-em-09",type:"mc",q:"Con mèo có ích gì?",emoji:"🐱🐭",options:["Bắt chuột","Đẻ trứng","Kéo cày"],answer:0,explain:"Mèo bắt chuột."},{id:"tnxh1-con-vat-quanh-em-10",type:"mc",q:"Con bò cho ta gì?",emoji:"🐄🥛",options:["Mật ong","Trứng","Sữa"],answer:2,explain:"Bò sữa cho ta sữa."},{id:"tnxh1-con-vat-quanh-em-11",type:"tf",q:"Con bướm làm ra mật ong.",emoji:"🦋🍯",answer:!1,explain:"Sai. Con ong mới làm ra mật ong."},{id:"tnxh1-con-vat-quanh-em-12",type:"tf",q:"Con chó có ích vì biết trông nhà.",emoji:"🐶",answer:!0,explain:"Đúng. Chó trông nhà, báo khi có người lạ."},{id:"tnxh1-con-vat-quanh-em-13",type:"match",q:"Nối con vật với lợi ích.",pairs:[["🐔 Gà","Cho trứng"],["🐝 Ong","Cho mật"],["🐱 Mèo","Bắt chuột"],["🐃 Trâu","Kéo cày"]],explain:"Nhiều con vật có ích cho con người."},{id:"tnxh1-con-vat-quanh-em-14",type:"multi",q:"Con vật nào sống dưới nước?",emoji:"🌊",options:["Con trâu","Con tôm","Con cá"],answers:[1,2],explain:"Cá, tôm sống dưới nước. Trâu sống trên cạn."},{id:"tnxh1-con-vat-quanh-em-15",type:"tf",q:"Con voi là con vật rất nhỏ.",emoji:"🐘",answer:!1,explain:"Sai. Voi là con vật rất to."},{id:"tnxh1-con-vat-quanh-em-16",type:"mc",q:"Con vật nào vừa đi được trên cạn vừa bơi được dưới nước?",emoji:"🦆",options:["Con cá","Con vịt","Con mèo"],answer:1,explain:"Vịt đi trên cạn và bơi dưới nước."}]},{questions:[{id:"tnxh1-con-vat-quanh-em-17",type:"mc",q:"Nhà Bình có nhiều chuột. Bình nên nuôi con gì?",emoji:"🐭",options:["Con mèo","Con cá","Con thỏ"],answer:0,explain:"Mèo bắt chuột."},{id:"tnxh1-con-vat-quanh-em-18",type:"mc",q:"Ngọc muốn có trứng ăn hằng ngày. Nhà Ngọc nên nuôi con gì?",emoji:"🥚",options:["Con chó","Con gà","Con mèo"],answer:1,explain:"Gà đẻ trứng."},{id:"tnxh1-con-vat-quanh-em-19",type:"tf",q:"Đến vườn thú, Nam ném đá vào chuồng khỉ. Nam làm đúng.",emoji:"🐒",answer:!1,explain:"Sai. Ném đá làm con vật đau và sợ hãi."},{id:"tnxh1-con-vat-quanh-em-20",type:"tf",q:"Cá vàng nuôi trong bể cần được cho ăn và thay nước.",emoji:"🐠",answer:!0,explain:"Đúng. Cá cần thức ăn và nước sạch."},{id:"tnxh1-con-vat-quanh-em-21",type:"multi",q:"Con vật nào biết bay?",emoji:"🦋",options:["Con ong","Con rùa","Con bướm","Con chim"],answers:[0,2,3],explain:"Chim, bướm, ong biết bay. Rùa không bay được."},{id:"tnxh1-con-vat-quanh-em-22",type:"order",q:"Sắp xếp các con vật từ nhỏ đến to.",emoji:"🐜🐘",items:["Con kiến","Con mèo","Con bò","Con voi"],explain:"Kiến nhỏ nhất, rồi mèo, bò, voi to nhất."},{id:"tnxh1-con-vat-quanh-em-23",type:"mc",q:"Con vật nào có thể sống ở vườn nhà em?",emoji:"🪱",options:["Con giun đất","Con lạc đà","Con cá voi"],answer:0,explain:"Giun đất sống trong đất vườn."},{id:"tnxh1-con-vat-quanh-em-24",type:"fill",q:"Con vật kêu “gâu gâu” là con …",emoji:"🐶",answer:["chó"],loose:!0,explain:"Chó kêu gâu gâu."}]}],challenge:{questions:[{id:"tnxh1-con-vat-quanh-em-25",type:"match",q:"Nối con vật với nơi sống.",pairs:[["🐟 Cá","Dưới nước"],["🐒 Khỉ","Trong rừng"],["🐔 Gà","Chuồng gà"],["🪱 Giun đất","Trong đất"]],explain:"Mỗi con vật sống ở nơi phù hợp."},{id:"tnxh1-con-vat-quanh-em-26",type:"multi",q:"Con vật nào là vật nuôi trong nhà?",emoji:"🐷",options:["Con hổ","Con vịt","Con sư tử","Con lợn"],answers:[1,3],explain:"Lợn, vịt là vật nuôi. Hổ, sư tử là con vật hoang dã."},{id:"tnxh1-con-vat-quanh-em-27",type:"mc",q:"Con vật nào có thể giúp hoa kết quả khi bay từ hoa này sang hoa khác?",emoji:"🐝🌸",options:["Con cá","Con giun","Con ong"],answer:2,explain:"Ong bay từ hoa này sang hoa khác, giúp hoa kết quả."},{id:"tnxh1-con-vat-quanh-em-28",type:"tf",q:"Con vật nào cũng có thể nuôi trong nhà.",emoji:"🐅",answer:!1,explain:"Sai. Hổ, sư tử là con vật hoang dã, không nuôi trong nhà."},{id:"tnxh1-con-vat-quanh-em-16",type:"mc",q:"Con vật nào vừa đi được trên cạn vừa bơi được dưới nước?",emoji:"🦆",options:["Con cá","Con vịt","Con mèo"],answer:1,explain:"Vịt đi trên cạn và bơi dưới nước."},{id:"tnxh1-con-vat-quanh-em-19",type:"tf",q:"Đến vườn thú, Nam ném đá vào chuồng khỉ. Nam làm đúng.",emoji:"🐒",answer:!1,explain:"Sai. Ném đá làm con vật đau và sợ hãi."}]},summary:["Quanh em có nhiều con vật sống ở nhiều nơi.","Nhiều con vật có ích cho con người."]},{id:"tnxh1-bo-phan-con-vat",title:"Các bộ phận của con vật",weeks:[21,22],learn:[{title:"Ba phần",text:"Con vật thường có đầu, mình và bộ phận để di chuyển.",example:"🐶 🐟 🐦"},{title:"Di chuyển",text:"Con vật di chuyển bằng chân, bằng cánh hoặc bằng vây. Con rắn thì bò bằng mình.",example:"🦵 🪽 🐟 🐍"},{title:"Thức ăn",text:"Có con ăn cỏ, có con ăn thịt, có con ăn hạt.",example:"🐄 🌿  ·  🐯 🍖  ·  🐔 🌾"}],practice:[{questions:[{id:"tnxh1-bo-phan-con-vat-01",type:"mc",q:"Con chim bay bằng gì?",emoji:"🐦",options:["Bằng đuôi","Bằng cánh","Bằng vây"],answer:1,explain:"Chim bay bằng cánh."},{id:"tnxh1-bo-phan-con-vat-02",type:"mc",q:"Con cá bơi bằng gì?",emoji:"🐟",options:["Bằng hai cái cánh","Bằng vây và đuôi","Bằng bốn cái chân"],answer:1,explain:"Cá bơi nhờ vây và đuôi."},{id:"tnxh1-bo-phan-con-vat-03",type:"number",q:"Con gà có mấy chân?",emoji:"🐔",answer:2,explain:"Con gà có 2 chân."},{id:"tnxh1-bo-phan-con-vat-04",type:"number",q:"Con chó có mấy chân?",emoji:"🐶",answer:4,explain:"Con chó có 4 chân."},{id:"tnxh1-bo-phan-con-vat-05",type:"tf",q:"Con rắn có bốn chân.",emoji:"🐍",answer:!1,explain:"Sai. Rắn không có chân, nó di chuyển bằng cách trườn."},{id:"tnxh1-bo-phan-con-vat-06",type:"tf",q:"Con cá đi bằng bốn chân.",emoji:"🐟",answer:!1,explain:"Sai. Cá không có chân, cá bơi bằng vây."},{id:"tnxh1-bo-phan-con-vat-07",type:"match",q:"Nối con vật với cách di chuyển.",pairs:[["🐦 Chim","Bay"],["🐟 Cá","Bơi"],["🐍 Rắn","Bò, trườn"],["🐎 Ngựa","Chạy"]],explain:"Mỗi con vật di chuyển theo cách riêng."},{id:"tnxh1-bo-phan-con-vat-08",type:"multi",q:"Con vật thường có những phần nào?",emoji:"🐾",options:["Rễ","Mình","Đầu","Bộ phận để di chuyển"],answers:[1,2,3],explain:"Con vật có đầu, mình, bộ phận di chuyển. Rễ là của cây."}]},{questions:[{id:"tnxh1-bo-phan-con-vat-09",type:"mc",q:"Con bò ăn gì?",emoji:"🐄🌿",options:["Chuột","Cá","Cỏ"],answer:2,explain:"Bò ăn cỏ."},{id:"tnxh1-bo-phan-con-vat-10",type:"mc",q:"Con mèo thích ăn gì?",emoji:"🐱",options:["Cỏ xanh non","Cá, chuột","Lá cây"],answer:1,explain:"Mèo ăn cá, bắt chuột."},{id:"tnxh1-bo-phan-con-vat-11",type:"tf",q:"Con gà ăn thóc, hạt ngô.",emoji:"🐔🌽",answer:!0,explain:"Đúng. Gà ăn thóc, ngô và cả sâu bọ."},{id:"tnxh1-bo-phan-con-vat-12",type:"tf",q:"Con hổ ăn cỏ như con bò.",emoji:"🐯",answer:!1,explain:"Sai. Hổ là con vật ăn thịt."},{id:"tnxh1-bo-phan-con-vat-13",type:"match",q:"Nối con vật với thức ăn.",pairs:[["🐄 Bò","Cỏ"],["🐔 Gà","Thóc"],["🐰 Thỏ","Cà rốt, rau"],["🐯 Hổ","Thịt"]],explain:"Mỗi con vật ăn thức ăn khác nhau."},{id:"tnxh1-bo-phan-con-vat-14",type:"multi",q:"Con vật nào có cánh?",emoji:"🪽",options:["Con gà","Con chó","Con chim","Con vịt"],answers:[0,2,3],explain:"Gà, vịt, chim có cánh. Chó không có cánh."},{id:"tnxh1-bo-phan-con-vat-15",type:"mc",q:"Con vật nào có mai cứng trên lưng?",emoji:"🐢",options:["Con rùa","Con mèo","Con thỏ"],answer:0,explain:"Rùa có mai cứng che chở cơ thể."},{id:"tnxh1-bo-phan-con-vat-16",type:"mc",q:"Con voi có chiếc mũi rất dài gọi là gì?",emoji:"🐘",options:["Cái mỏ","Cái vây","Cái vòi"],answer:2,explain:"Mũi voi dài gọi là vòi."}]},{questions:[{id:"tnxh1-bo-phan-con-vat-17",type:"mc",q:"Con vật có mỏ, có cánh, có hai chân, đẻ trứng. Đó là con gì?",emoji:"🐔",options:["Con gà","Con mèo","Con cá"],answer:0,explain:"Gà có mỏ, cánh, hai chân và đẻ trứng."},{id:"tnxh1-bo-phan-con-vat-18",type:"mc",q:"Con vật sống dưới nước, có vây, có đuôi. Đó là con gì?",emoji:"🐟",options:["Con cá","Con thỏ","Con chim"],answer:0,explain:"Cá sống dưới nước, có vây và đuôi."},{id:"tnxh1-bo-phan-con-vat-19",type:"number",q:"Hai con gà có tất cả mấy chân?",emoji:"🐔🐔",answer:4,explain:"Mỗi con gà có 2 chân. Hai con gà có 4 chân."},{id:"tnxh1-bo-phan-con-vat-20",type:"tf",q:"Con chim vừa biết bay vừa biết đi bằng hai chân.",emoji:"🐦",answer:!0,explain:"Đúng. Chim bay bằng cánh và đi bằng chân."},{id:"tnxh1-bo-phan-con-vat-21",type:"tf",q:"Con thỏ có cánh để bay.",emoji:"🐰",answer:!1,explain:"Sai. Thỏ không có cánh, thỏ nhảy bằng chân."},{id:"tnxh1-bo-phan-con-vat-22",type:"multi",q:"Con vật nào có bốn chân?",emoji:"🐾",options:["Con mèo","Con bò","Con gà","Con chó"],answers:[0,1,3],explain:"Chó, mèo, bò có bốn chân. Gà có hai chân."},{id:"tnxh1-bo-phan-con-vat-23",type:"mc",q:"Con thỏ có đôi tai như thế nào?",emoji:"🐰",options:["Nằm ở chân","Không có tai","Dài"],answer:2,explain:"Thỏ có đôi tai dài."},{id:"tnxh1-bo-phan-con-vat-24",type:"fill",q:"Con chim bay bằng đôi …",emoji:"🐦",answer:["cánh"],loose:!0,explain:"Chim bay bằng cánh."}]}],challenge:{questions:[{id:"tnxh1-bo-phan-con-vat-25",type:"match",q:"Nối con vật với đặc điểm nổi bật.",pairs:[["🐘 Voi","Có vòi dài"],["🐢 Rùa","Có mai cứng"],["🦒 Hươu cao cổ","Có cổ dài"],["🐰 Thỏ","Có tai dài"]],explain:"Mỗi con vật có đặc điểm riêng."},{id:"tnxh1-bo-phan-con-vat-26",type:"number",q:"Một con chó và một con gà có tất cả mấy chân?",emoji:"🐶🐔",answer:6,explain:"Chó có 4 chân, gà có 2 chân. 4 cộng 2 bằng 6."},{id:"tnxh1-bo-phan-con-vat-27",type:"multi",q:"Con vật nào bơi được dưới nước?",emoji:"🌊",options:["Con cá","Con vịt","Con bướm"],answers:[0,1],explain:"Cá và vịt bơi được dưới nước. Bướm bay chứ không bơi."},{id:"tnxh1-bo-phan-con-vat-28",type:"mc",q:"Con vật nào có cánh nhưng chỉ bay được thấp và gần?",emoji:"🐔",options:["Con chim én","Con gà","Con đại bàng"],answer:1,explain:"Gà có cánh nhưng chỉ bay thấp và gần. Đại bàng, chim én bay cao, bay xa."},{id:"tnxh1-bo-phan-con-vat-05",type:"tf",q:"Con rắn có bốn chân.",emoji:"🐍",answer:!1,explain:"Sai. Rắn không có chân, nó di chuyển bằng cách trườn."},{id:"tnxh1-bo-phan-con-vat-17",type:"mc",q:"Con vật có mỏ, có cánh, có hai chân, đẻ trứng. Đó là con gì?",emoji:"🐔",options:["Con gà","Con mèo","Con cá"],answer:0,explain:"Gà có mỏ, cánh, hai chân và đẻ trứng."}]},summary:["Con vật thường có đầu, mình và bộ phận di chuyển.","Con vật di chuyển bằng chân, cánh, vây hoặc bò bằng mình."]},{id:"tnxh1-cham-soc-cay-con-vat",title:"Chăm sóc và bảo vệ cây, con vật",weeks:[22,23],learn:[{title:"Chăm sóc cây",text:"Cây cần nước, ánh sáng, không khí và đất. Em tưới nước, nhổ cỏ cho cây.",example:"💧 ☀️ 🪴"},{title:"Chăm sóc con vật",text:"Em cho con vật ăn, uống và giữ chuồng sạch sẽ.",example:"🥣 🐶 🧹"},{title:"Bảo vệ",text:"Em không bẻ cây, hái hoa nơi công cộng, không đánh đập con vật.",example:"🚫 🌸 🐱"}],practice:[{questions:[{id:"tnxh1-cham-soc-cay-con-vat-01",type:"mc",q:"Cây cần gì để sống?",emoji:"🌱",options:["Kẹo ngọt, bánh quy","Bóng tối suốt ngày","Nước, ánh sáng, đất"],answer:2,explain:"Cây cần nước, ánh sáng, đất."},{id:"tnxh1-cham-soc-cay-con-vat-02",type:"mc",q:"Em làm gì để chăm sóc cây?",emoji:"🚿",options:["Bẻ cành cây chơi","Tưới nước cho cây","Giẫm lên gốc cây"],answer:1,explain:"Tưới nước giúp cây sống tốt."},{id:"tnxh1-cham-soc-cay-con-vat-03",type:"mc",q:"Em làm gì để chăm sóc chú chó nhỏ?",emoji:"🐶",options:["Cho chó ăn, uống nước","Kéo đuôi chó","Nhốt chó không cho ăn"],answer:0,explain:"Chó cần được cho ăn uống đầy đủ."},{id:"tnxh1-cham-soc-cay-con-vat-04",type:"tf",q:"Bẻ cành, hái hoa ở công viên là việc nên làm.",emoji:"🌸",answer:!1,explain:"Sai. Em bảo vệ cây hoa ở nơi công cộng."},{id:"tnxh1-cham-soc-cay-con-vat-05",type:"tf",q:"Giữ chuồng sạch giúp con vật khỏe mạnh.",emoji:"🏠",answer:!0,explain:"Đúng. Chuồng sạch giúp con vật ít bị bệnh."},{id:"tnxh1-cham-soc-cay-con-vat-06",type:"match",q:"Nối việc làm với cây hoặc con vật.",pairs:[["🚿 Tưới nước","Chậu hoa"],["🌾 Cho ăn thóc","Đàn gà"],["🐟 Thay nước bể","Cá vàng"]],explain:"Mỗi cây, con vật cần được chăm sóc phù hợp."},{id:"tnxh1-cham-soc-cay-con-vat-07",type:"multi",q:"Việc làm nào bảo vệ con vật?",emoji:"🐾",options:["Ném đá vào chim","Cho con vật ăn đủ","Không trêu chọc con vật"],answers:[1,2],explain:"Cho ăn đủ, không trêu chọc là bảo vệ con vật."},{id:"tnxh1-cham-soc-cay-con-vat-08",type:"tf",q:"Cây để trong tối lâu ngày sẽ yếu đi.",emoji:"🌑🪴",answer:!0,explain:"Đúng. Cây cần ánh sáng để sống."}]},{questions:[{id:"tnxh1-cham-soc-cay-con-vat-09",type:"mc",q:"Vì sao phải nhổ cỏ dại quanh cây rau?",emoji:"🌿",options:["Để cây rau héo đi, không lớn được nữa","Để cỏ không tranh nước, tranh đất với rau","Để vườn rau có thật nhiều cỏ dại hơn"],answer:1,explain:"Cỏ dại tranh nước với cây rau."},{id:"tnxh1-cham-soc-cay-con-vat-10",type:"tf",q:"Chim non rơi khỏi tổ, em nên báo người lớn để giúp chim.",emoji:"🐣",answer:!0,explain:"Đúng. Người lớn giúp đưa chim về chỗ an toàn."},{id:"tnxh1-cham-soc-cay-con-vat-11",type:"multi",q:"Việc nào giúp cây lớn tốt?",emoji:"🌻",options:["Bứt lá chơi","Nhổ cỏ dại","Tưới nước","Để cây ra chỗ có ánh sáng"],answers:[1,2,3],explain:"Tưới nước, nhổ cỏ, cho cây ánh sáng giúp cây lớn tốt."},{id:"tnxh1-cham-soc-cay-con-vat-12",type:"mc",q:"Vì sao không nên bắt chim non?",emoji:"🐦",options:["Vì chim non đã biết nói như người","Vì chim non rất to, rất nặng","Vì chim non cần chim mẹ chăm sóc"],answer:2,explain:"Chim non còn nhỏ, cần chim mẹ chăm sóc."},{id:"tnxh1-cham-soc-cay-con-vat-13",type:"match",q:"Nối hành động với đúng hoặc sai.",pairs:[["Cho mèo ăn","Nên làm"],["Kéo đuôi mèo","Không nên làm"],["Hỏi người lớn khi chưa biết chăm cây","Việc làm đúng đắn"]],explain:"Em đối xử tốt với cây và con vật."},{id:"tnxh1-cham-soc-cay-con-vat-14",type:"tf",q:"Tưới thật nhiều nước cho cây xương rồng mỗi giờ là tốt.",emoji:"🌵",answer:!1,explain:"Sai. Xương rồng cần ít nước, tưới quá nhiều cây sẽ thối rễ."},{id:"tnxh1-cham-soc-cay-con-vat-15",type:"mc",q:"Đi chơi công viên, em thấy biển “Không giẫm lên cỏ”. Em làm gì?",emoji:"🌱",options:["Nhổ cỏ chơi","Chạy trên bãi cỏ","Đi trên lối đi"],answer:2,explain:"Em đi trên lối đi để bảo vệ cỏ."},{id:"tnxh1-cham-soc-cay-con-vat-16",type:"tf",q:"Em có thể trồng cây vào chai nhựa cũ.",emoji:"♻️🌱",answer:!0,explain:"Đúng. Chai nhựa cũ có thể làm chậu trồng cây nhỏ."}]},{questions:[{id:"tnxh1-cham-soc-cay-con-vat-17",type:"mc",q:"Chậu hoa của lớp bị héo vì nắng. Em làm gì?",emoji:"🥀",options:["Bứt hết lá của cây","Tưới nước cho cây","Vứt chậu hoa đi"],answer:1,explain:"Cây héo vì thiếu nước, em tưới nước cho cây."},{id:"tnxh1-cham-soc-cay-con-vat-18",type:"mc",q:"Ngày nắng nóng, chú chó nhà em thở hổn hển. Em làm gì?",emoji:"🐶☀️",options:["Cho chó uống nước, đưa vào chỗ mát","Không quan tâm, để chó tự chơi","Buộc chó ở ngoài trời nắng to"],answer:0,explain:"Nắng nóng, chó cần nước và chỗ mát."},{id:"tnxh1-cham-soc-cay-con-vat-19",type:"tf",q:"Dũng hái hết hoa ở vườn trường để chơi. Dũng làm đúng.",emoji:"🌺",answer:!1,explain:"Sai. Hoa ở vườn trường là để mọi người cùng ngắm."},{id:"tnxh1-cham-soc-cay-con-vat-20",type:"tf",q:"Phúc cùng ông cho đàn gà ăn mỗi sáng. Phúc làm đúng.",emoji:"🐔",answer:!0,explain:"Đúng. Phúc biết chăm sóc vật nuôi."},{id:"tnxh1-cham-soc-cay-con-vat-21",type:"order",q:"Sắp xếp các bước trồng cây vào chậu.",emoji:"🪴",items:["Cho đất vào chậu","Đặt cây con vào giữa","Lấp đất, nén nhẹ","Tưới nước"],explain:"Cho đất, đặt cây, lấp đất rồi tưới nước."},{id:"tnxh1-cham-soc-cay-con-vat-22",type:"multi",q:"Vy nuôi một chú mèo. Vy cần làm gì?",emoji:"🐱",options:["Ném mèo lên cao","Chơi nhẹ nhàng với mèo","Giữ chỗ nằm của mèo sạch","Cho mèo ăn, uống"],answers:[1,2,3],explain:"Cho ăn uống, giữ chỗ nằm sạch, chơi nhẹ nhàng là chăm sóc mèo."},{id:"tnxh1-cham-soc-cay-con-vat-23",type:"mc",q:"Em thấy bạn rung cây làm tổ chim rơi. Em nói gì?",emoji:"🪺",options:["Bạn rung cây mạnh hơn nữa đi","Cho tớ cùng rung cây với bạn nhé","Bạn đừng rung cây, chim non sẽ bị ngã"],answer:2,explain:"Em khuyên bạn để bảo vệ chim."},{id:"tnxh1-cham-soc-cay-con-vat-24",type:"fill",q:"Cây héo vì thiếu nước, em tưới … cho cây.",emoji:"💧",answer:["nước"],loose:!0,explain:"Cây cần nước để sống."}]}],challenge:{questions:[{id:"tnxh1-cham-soc-cay-con-vat-25",type:"match",q:"Nối vấn đề với cách chăm sóc.",pairs:[["Cây héo","Tưới nước"],["Vườn nhiều cỏ dại","Nhổ cỏ"],["Bể cá bẩn","Thay nước"],["Chó đói","Cho chó ăn"]],explain:"Biết vấn đề để chăm sóc đúng cách."},{id:"tnxh1-cham-soc-cay-con-vat-26",type:"multi",q:"Việc nào bảo vệ cây xanh nơi công cộng?",emoji:"🌳",options:["Đóng đinh vào cây","Không bẻ cành","Trồng thêm cây","Không viết lên thân cây"],answers:[1,2,3],explain:"Không bẻ cành, không viết lên cây, trồng thêm cây là bảo vệ cây."},{id:"tnxh1-cham-soc-cay-con-vat-27",type:"mc",q:"Vì sao cần chăm sóc, bảo vệ cây và con vật?",emoji:"🌏",options:["Vì chúng có ích và làm cuộc sống đẹp hơn","Vì để mang chúng đi bán lấy tiền","Vì để lấy chúng làm đồ chơi cho em"],answer:0,explain:"Cây và con vật có ích, làm cuộc sống tươi đẹp."},{id:"tnxh1-cham-soc-cay-con-vat-28",type:"tf",q:"Cho con vật ăn bánh kẹo của người là cách chăm sóc tốt nhất.",emoji:"🍬",answer:!1,explain:"Sai. Mỗi con vật cần thức ăn phù hợp."},{id:"tnxh1-cham-soc-cay-con-vat-10",type:"tf",q:"Chim non rơi khỏi tổ, em nên báo người lớn để giúp chim.",emoji:"🐣",answer:!0,explain:"Đúng. Người lớn giúp đưa chim về chỗ an toàn."},{id:"tnxh1-cham-soc-cay-con-vat-21",type:"order",q:"Sắp xếp các bước trồng cây vào chậu.",emoji:"🪴",items:["Cho đất vào chậu","Đặt cây con vào giữa","Lấp đất, nén nhẹ","Tưới nước"],explain:"Cho đất, đặt cây, lấp đất rồi tưới nước."}]},summary:["Cây cần nước, ánh sáng, đất; em tưới nước, nhổ cỏ cho cây.","Em cho con vật ăn uống, giữ chuồng sạch, không trêu chọc chúng."]},{id:"tnxh1-an-toan-cay-con-vat",title:"Cẩn thận với cây và con vật",weeks:[23,24],learn:[{title:"Con vật có thể gây hại",text:"Chó lạ có thể cắn, ong có thể đốt, mèo có thể cào.",example:"🐕 🐝 🐈"},{title:"Cây có thể gây hại",text:"Có cây có gai, có cây có nhựa độc. Em không ăn lá, quả lạ.",example:"🌵 🍒 🚫"},{title:"Khi bị cắn, bị đốt",text:"Em báo ngay bố mẹ, thầy cô để được giúp đỡ.",example:"📣 🩹"}],practice:[{questions:[{id:"tnxh1-an-toan-cay-con-vat-01",type:"mc",q:"Gặp chó lạ, em làm gì?",emoji:"🐕",options:["Lại gần trêu chọc chó","Đứng xa, không trêu chọc","Chạy lại ôm chú chó"],answer:1,explain:"Chó lạ có thể cắn. Em tránh xa, không trêu chọc."},{id:"tnxh1-an-toan-cay-con-vat-02",type:"mc",q:"Con vật nào có thể đốt gây đau?",emoji:"🐝",options:["Con ong","Con thỏ","Con cá vàng"],answer:0,explain:"Ong có thể đốt gây đau, sưng."},{id:"tnxh1-an-toan-cay-con-vat-03",type:"tf",q:"Ăn quả lạ ngoài vườn là an toàn.",emoji:"🍒",answer:!1,explain:"Sai. Quả lạ có thể có độc. Em hỏi người lớn trước."},{id:"tnxh1-an-toan-cay-con-vat-04",type:"tf",q:"Bị chó cắn, em phải báo ngay người lớn.",emoji:"🩹",answer:!0,explain:"Đúng. Bị chó cắn cần được người lớn đưa đi khám ngay."},{id:"tnxh1-an-toan-cay-con-vat-05",type:"match",q:"Nối con vật với điều có thể xảy ra.",pairs:[["🐕 Chó lạ","Cắn"],["🐝 Ong","Đốt"],["🐈 Mèo","Cào"]],explain:"Biết để cẩn thận khi ở gần con vật."},{id:"tnxh1-an-toan-cay-con-vat-06",type:"multi",q:"Cây nào có gai, cần cẩn thận?",emoji:"🌵",options:["Cây rau muống","Cây hoa hồng","Cây xương rồng"],answers:[1,2],explain:"Xương rồng, hoa hồng có gai. Rau muống không có gai."},{id:"tnxh1-an-toan-cay-con-vat-07",type:"mc",q:"Thấy tổ ong trên cây, em làm gì?",emoji:"🐝",options:["Ném đá vào tổ ong","Tránh xa, báo người lớn","Lấy que dài chọc vào tổ"],answer:1,explain:"Chọc tổ ong, ong sẽ đốt rất nguy hiểm."},{id:"tnxh1-an-toan-cay-con-vat-08",type:"tf",q:"Nấm mọc dại có thể có độc.",emoji:"🍄",answer:!0,explain:"Đúng. Không hái và ăn nấm lạ."}]},{questions:[{id:"tnxh1-an-toan-cay-con-vat-09",type:"mc",q:"Vì sao không nên trêu chó khi chó đang ăn?",emoji:"🐕🍖",options:["Vì chó sẽ ngủ","Vì chó sẽ no hơn","Vì chó có thể cắn"],answer:2,explain:"Chó đang ăn bị trêu dễ nổi giận và cắn."},{id:"tnxh1-an-toan-cay-con-vat-10",type:"tf",q:"Sau khi chơi với chó, mèo, em cần rửa tay bằng xà phòng.",emoji:"🧼",answer:!0,explain:"Đúng. Rửa tay giúp em sạch sẽ, phòng bệnh."},{id:"tnxh1-an-toan-cay-con-vat-11",type:"multi",q:"Việc nào an toàn khi ở gần con vật?",emoji:"🐾",options:["Hỏi chủ trước khi vuốt ve","Không trêu chọc","Kéo đuôi, giật tai"],answers:[0,1],explain:"Hỏi chủ, không trêu chọc là an toàn."},{id:"tnxh1-an-toan-cay-con-vat-12",type:"mc",q:"Đi chơi ngoài đồng, em thấy con rắn. Em làm gì?",emoji:"🐍",options:["Tránh xa và gọi người lớn","Lấy gậy chọc con rắn","Lại gần để bắt con rắn"],answer:0,explain:"Rắn có thể cắn. Em tránh xa và gọi người lớn."},{id:"tnxh1-an-toan-cay-con-vat-13",type:"match",q:"Nối tình huống với việc nên làm.",pairs:[["Bị ong đốt","Báo người lớn ngay"],["Thấy quả lạ","Không ăn, hỏi người lớn"],["Gặp chó lạ","Đứng xa, không trêu"]],explain:"Gặp nguy hiểm, em bình tĩnh và nhờ người lớn."},{id:"tnxh1-an-toan-cay-con-vat-14",type:"tf",q:"Vuốt ve con mèo lạ ngoài đường là an toàn.",emoji:"🐈",answer:!1,explain:"Sai. Mèo lạ có thể cào, cắn. Em không lại gần."},{id:"tnxh1-an-toan-cay-con-vat-15",type:"mc",q:"Khi đi vào vườn nhiều cây có gai, em nên làm gì?",emoji:"👟",options:["Đi giày dép, cẩn thận","Nhắm mắt đi","Đi chân đất chạy nhảy"],answer:0,explain:"Đi giày dép giúp chân không bị gai đâm."},{id:"tnxh1-an-toan-cay-con-vat-16",type:"tf",q:"Muỗi đốt có thể truyền bệnh.",emoji:"🦟",answer:!0,explain:"Đúng. Muỗi đốt có thể gây bệnh, em ngủ màn để tránh muỗi."}]},{questions:[{id:"tnxh1-an-toan-cay-con-vat-17",type:"mc",q:"Lan thấy bông hoa đẹp có gai. Lan muốn ngửi. Lan làm gì?",emoji:"🌹",options:["Nắm thật chặt lấy cành hoa có gai","Cúi xuống ngửi nhẹ, không chạm gai","Bứt thật mạnh bông hoa ra khỏi cây"],answer:1,explain:"Lan cẩn thận để không bị gai đâm."},{id:"tnxh1-an-toan-cay-con-vat-18",type:"mc",q:"Một chú chó lạ sủa và chạy lại gần. Em làm gì?",emoji:"🐕",options:["Đứng yên, không chạy, gọi người lớn","Chạy thật nhanh và hét thật to","Lại gần trêu cho chó sủa to hơn"],answer:0,explain:"Đứng yên, không trêu chó và gọi người lớn giúp."},{id:"tnxh1-an-toan-cay-con-vat-19",type:"tf",q:"Minh bị mèo cào chảy máu nhưng giấu bố mẹ. Minh làm đúng.",emoji:"🩹",answer:!1,explain:"Sai. Minh cần báo bố mẹ để được chăm sóc."},{id:"tnxh1-an-toan-cay-con-vat-20",type:"tf",q:"Ngủ trong màn giúp tránh bị muỗi đốt.",emoji:"🛏️🦟",answer:!0,explain:"Đúng. Màn ngăn muỗi đốt khi ngủ."},{id:"tnxh1-an-toan-cay-con-vat-21",type:"multi",q:"Những việc nào nguy hiểm?",emoji:"⚠️",options:["Ngắm hoa trong vườn","Ăn nấm lạ","Trêu chó lạ","Chọc tổ ong"],answers:[1,2,3],explain:"Chọc tổ ong, ăn nấm lạ, trêu chó lạ đều nguy hiểm."},{id:"tnxh1-an-toan-cay-con-vat-22",type:"order",q:"Sắp xếp các việc khi em bị ong đốt.",emoji:"🐝",items:["Ra xa chỗ có ong","Báo ngay người lớn","Để người lớn xử lí vết đốt"],explain:"Ra xa chỗ có ong, báo người lớn để được giúp."},{id:"tnxh1-an-toan-cay-con-vat-23",type:"mc",q:"Tùng muốn sờ chú chó của hàng xóm. Tùng nên làm gì trước?",emoji:"🐶",options:["Hỏi chủ của chú chó","Kéo đuôi chú chó","Ôm ngay lấy chú chó"],answer:0,explain:"Hỏi chủ trước để biết chó có hiền không."},{id:"tnxh1-an-toan-cay-con-vat-24",type:"fill",q:"Thấy quả lạ, em không …, em hỏi người lớn.",emoji:"🍒",answer:["ăn"],loose:!0,explain:"Quả lạ có thể có độc, em không ăn."}]}],challenge:{questions:[{id:"tnxh1-an-toan-cay-con-vat-25",type:"match",q:"Nối mối nguy với cách phòng tránh.",pairs:[["Muỗi đốt","Ngủ trong màn"],["Gai đâm chân","Đi giày dép"],["Chó cắn","Không trêu chó"],["Ăn phải quả độc","Không ăn quả lạ"]],explain:"Biết phòng tránh để giữ an toàn."},{id:"tnxh1-an-toan-cay-con-vat-26",type:"multi",q:"Bị chó cắn, cần làm gì?",emoji:"🏥",options:["Báo ngay người lớn","Giấu đi không nói","Đi khám, tiêm phòng theo lời bác sĩ"],answers:[0,2],explain:"Bị chó cắn cần báo người lớn và đi khám ngay."},{id:"tnxh1-an-toan-cay-con-vat-27",type:"mc",q:"Vì sao không nên đến gần con vật đang chăm con nhỏ?",emoji:"🐕🐶",options:["Vì lúc đó con vật đang rất vui vẻ","Vì con vật mẹ đang ngủ rất say ở trong ổ","Vì con vật mẹ có thể tấn công để bảo vệ con"],answer:2,explain:"Con vật mẹ bảo vệ con nên dễ tấn công người lạ."},{id:"tnxh1-an-toan-cay-con-vat-28",type:"tf",q:"Con vật hiền cũng có thể cắn khi bị trêu chọc.",emoji:"🐱",answer:!0,explain:"Đúng. Bị trêu, con vật có thể sợ và cắn."},{id:"tnxh1-an-toan-cay-con-vat-10",type:"tf",q:"Sau khi chơi với chó, mèo, em cần rửa tay bằng xà phòng.",emoji:"🧼",answer:!0,explain:"Đúng. Rửa tay giúp em sạch sẽ, phòng bệnh."},{id:"tnxh1-an-toan-cay-con-vat-19",type:"tf",q:"Minh bị mèo cào chảy máu nhưng giấu bố mẹ. Minh làm đúng.",emoji:"🩹",answer:!1,explain:"Sai. Minh cần báo bố mẹ để được chăm sóc."}]},summary:["Chó lạ, ong, rắn, cây có gai có thể gây hại.","Em không trêu con vật, không ăn quả, nấm lạ.","Bị cắn, bị đốt, em báo ngay người lớn."]}]},{id:"con-nguoi-suc-khoe",title:"Con người và sức khỏe",lessons:[{id:"tnxh1-co-the-em",title:"Cơ thể em",weeks:[25,26],learn:[{title:"Các phần cơ thể",text:"Cơ thể em có đầu, mình, hai tay và hai chân.",example:"🙂 👕 🙌 🦵"},{title:"Trên khuôn mặt",text:"Khuôn mặt có mắt, mũi, miệng; hai bên đầu có hai tai.",example:"👀 👃 👄 👂"},{title:"Cử động",text:"Nhờ có tay, chân, em cầm, nắm, đi, chạy, nhảy được.",example:"✋ 🏃 🤸"}],practice:[{questions:[{id:"tnxh1-co-the-em-01",type:"mc",q:"Cơ thể em gồm những phần nào?",emoji:"🧍",options:["Rễ, thân, lá, hoa","Cánh, vây, đuôi","Đầu, mình, tay, chân"],answer:2,explain:"Cơ thể người gồm đầu, mình, tay và chân."},{id:"tnxh1-co-the-em-02",type:"number",q:"Em có mấy bàn tay?",emoji:"🙌",answer:2,explain:"Em có hai bàn tay."},{id:"tnxh1-co-the-em-03",type:"number",q:"Một bàn tay có mấy ngón?",emoji:"✋",answer:5,explain:"Mỗi bàn tay có năm ngón."},{id:"tnxh1-co-the-em-04",type:"tf",q:"Mắt, mũi, miệng nằm ở sau gáy.",emoji:"🙂",answer:!1,explain:"Sai. Mắt, mũi, miệng nằm trên khuôn mặt."},{id:"tnxh1-co-the-em-05",type:"tf",q:"Tai mọc ở dưới bàn chân.",emoji:"👂",answer:!1,explain:"Sai. Hai tai ở hai bên đầu."},{id:"tnxh1-co-the-em-06",type:"match",q:"Nối bộ phận với hình.",pairs:[["Mắt","👀"],["Mũi","👃"],["Tai","👂"],["Miệng","👄"]],explain:"Đây là các bộ phận trên đầu, mặt."},{id:"tnxh1-co-the-em-07",type:"multi",q:"Bộ phận nào ở trên đầu, khuôn mặt?",emoji:"🙂",options:["Đầu gối","Mắt","Mũi","Tai"],answers:[1,2,3],explain:"Mắt, mũi, tai ở đầu, mặt. Đầu gối ở chân."},{id:"tnxh1-co-the-em-08",type:"mc",q:"Em dùng bộ phận nào để đi, chạy?",emoji:"🏃",options:["Chân","Đôi tai","Cái mũi"],answer:0,explain:"Em đi, chạy bằng chân."}]},{questions:[{id:"tnxh1-co-the-em-09",type:"mc",q:"Em dùng bộ phận nào để cầm bút?",emoji:"✏️",options:["Tay","Tai","Chân"],answer:0,explain:"Em cầm bút bằng tay."},{id:"tnxh1-co-the-em-10",type:"number",q:"Hai bàn tay có tất cả mấy ngón?",emoji:"🙌",answer:10,explain:"Mỗi bàn tay có 5 ngón. Hai bàn tay có 10 ngón."},{id:"tnxh1-co-the-em-11",type:"tf",q:"Nhờ có tay, chân, em làm được nhiều việc.",emoji:"🤸",answer:!0,explain:"Đúng. Tay chân giúp em cầm, nắm, đi lại, vui chơi."},{id:"tnxh1-co-the-em-12",type:"tf",q:"Cơ thể của mọi người đều giống hệt nhau.",emoji:"👫",answer:!1,explain:"Sai. Mỗi người có chiều cao, khuôn mặt khác nhau."},{id:"tnxh1-co-the-em-13",type:"match",q:"Nối hoạt động với bộ phận chính.",pairs:[["Đá bóng","Chân"],["Vỗ tay","Tay"],["Gật đầu","Đầu"]],explain:"Mỗi hoạt động dùng một bộ phận chính."},{id:"tnxh1-co-the-em-14",type:"multi",q:"Hoạt động nào cần dùng tay?",emoji:"✋",options:["Viết bài","Nghe nhạc","Vỗ tay","Cầm thìa ăn cơm"],answers:[0,2,3],explain:"Viết, vỗ tay, cầm thìa cần tay. Nghe nhạc dùng tai."},{id:"tnxh1-co-the-em-15",type:"mc",q:"Bộ phận nào nối đầu với mình?",emoji:"🧍",options:["Bàn chân","Cổ","Khuỷu tay"],answer:1,explain:"Cổ nối đầu với mình, giúp đầu quay được."},{id:"tnxh1-co-the-em-16",type:"tf",q:"Khi lớn lên, em cao hơn và nặng hơn.",emoji:"📏",answer:!0,explain:"Đúng. Cơ thể em lớn lên mỗi ngày."}]},{questions:[{id:"tnxh1-co-the-em-17",type:"mc",q:"Bình bị đau chân nên chưa đá bóng được. Bộ phận nào của Bình bị đau?",emoji:"🦵",options:["Đôi mắt","Chân","Đôi tai"],answer:1,explain:"Đá bóng cần chân, chân đau thì chưa chơi được."},{id:"tnxh1-co-the-em-18",type:"mc",q:"Để nhảy dây, em cần dùng những bộ phận nào nhiều nhất?",emoji:"🪢",options:["Tay và chân","Mũi và tai","Chỉ cái miệng"],answer:0,explain:"Tay quay dây, chân nhảy."},{id:"tnxh1-co-the-em-19",type:"tf",q:"Vy so chiều cao với bạn và thấy mình thấp hơn. Như vậy là bình thường.",emoji:"📏",answer:!0,explain:"Đúng. Mỗi bạn cao thấp khác nhau, đó là bình thường."},{id:"tnxh1-co-the-em-20",type:"tf",q:"Thấy bạn có điểm khác mình, em nên trêu chọc bạn.",emoji:"🤝",answer:!1,explain:"Sai. Em tôn trọng sự khác nhau của các bạn."},{id:"tnxh1-co-the-em-21",type:"order",q:"Sắp xếp các bộ phận từ trên đầu xuống dưới.",emoji:"🧍",items:["Đầu","Cổ","Mình","Chân"],explain:"Từ trên xuống: đầu, cổ, mình, chân."},{id:"tnxh1-co-the-em-22",type:"multi",q:"Việc nào giúp cơ thể khỏe mạnh?",emoji:"💪",options:["Thức rất khuya","Ngủ đủ giấc","Tập thể dục","Ăn uống đủ chất"],answers:[1,2,3],explain:"Tập thể dục, ăn đủ chất, ngủ đủ giúp cơ thể khỏe."},{id:"tnxh1-co-the-em-23",type:"mc",q:"Đi học về, An đo thấy mình cao hơn năm trước. Vì sao?",emoji:"📏",options:["Vì cái thước đo bị hỏng","Vì cơ thể An đang lớn lên","Vì An vừa ăn một cái kẹo"],answer:1,explain:"Trẻ em lớn lên nên cao hơn theo thời gian."},{id:"tnxh1-co-the-em-24",type:"fill",q:"Em cầm bút bằng …",emoji:"✋",answer:["tay"],loose:!0,explain:"Em cầm bút bằng tay."}]}],challenge:{questions:[{id:"tnxh1-co-the-em-25",type:"match",q:"Nối bộ phận với việc nó giúp em.",pairs:[["Chân","Đi, chạy"],["Tay","Cầm, nắm"],["Cổ","Quay đầu"],["Miệng","Ăn, nói"]],explain:"Mỗi bộ phận giúp em làm những việc khác nhau."},{id:"tnxh1-co-the-em-26",type:"number",q:"Hai bàn chân có tất cả mấy ngón?",emoji:"🦶🦶",answer:10,explain:"Mỗi bàn chân có 5 ngón. Hai bàn chân có 10 ngón."},{id:"tnxh1-co-the-em-27",type:"multi",q:"Bộ phận nào ở chân?",emoji:"🦵",options:["Đầu gối","Khuỷu tay","Ngón chân","Bàn chân"],answers:[0,2,3],explain:"Đầu gối, bàn chân, ngón chân ở chân. Khuỷu tay ở tay."},{id:"tnxh1-co-the-em-28",type:"tf",q:"Cơ thể có nhiều bộ phận, bộ phận nào cũng cần được giữ gìn.",emoji:"🧍",answer:!0,explain:"Đúng. Em giữ gìn mọi bộ phận của cơ thể."},{id:"tnxh1-co-the-em-10",type:"number",q:"Hai bàn tay có tất cả mấy ngón?",emoji:"🙌",answer:10,explain:"Mỗi bàn tay có 5 ngón. Hai bàn tay có 10 ngón."},{id:"tnxh1-co-the-em-22",type:"multi",q:"Việc nào giúp cơ thể khỏe mạnh?",emoji:"💪",options:["Thức rất khuya","Ngủ đủ giấc","Tập thể dục","Ăn uống đủ chất"],answers:[1,2,3],explain:"Tập thể dục, ăn đủ chất, ngủ đủ giúp cơ thể khỏe."}]},summary:["Cơ thể em có đầu, mình, tay, chân.","Nhờ các bộ phận, em làm được nhiều việc."]},{id:"tnxh1-cac-giac-quan",title:"Các giác quan",weeks:[26,27],learn:[{title:"Năm giác quan",text:"Em có năm giác quan: mắt, tai, mũi, lưỡi và da.",example:"👀 👂 👃 👅 ✋"},{title:"Mắt, tai, mũi",text:"Mắt để nhìn. Tai để nghe. Mũi để ngửi.",example:"👀 🌈  ·  👂 🎵  ·  👃 🌸"},{title:"Lưỡi và da",text:"Lưỡi để nếm vị. Da giúp em biết nóng, lạnh, trơn, nhám.",example:"👅 🍋  ·  ✋ 🧊"}],practice:[{questions:[{id:"tnxh1-cac-giac-quan-01",type:"mc",q:"Em nhìn mọi vật bằng gì?",emoji:"👀",options:["Tai","Mũi","Mắt"],answer:2,explain:"Mắt giúp em nhìn."},{id:"tnxh1-cac-giac-quan-02",type:"mc",q:"Em nghe tiếng chim hót bằng gì?",emoji:"🐦🎵",options:["Tai","Mắt","Lưỡi"],answer:0,explain:"Tai giúp em nghe."},{id:"tnxh1-cac-giac-quan-03",type:"mc",q:"Em ngửi mùi hoa thơm bằng gì?",emoji:"🌸",options:["Mũi","Da","Tai"],answer:0,explain:"Mũi giúp em ngửi."},{id:"tnxh1-cac-giac-quan-04",type:"number",q:"Em có mấy giác quan?",emoji:"🖐️",answer:5,explain:"Em có năm giác quan: mắt, tai, mũi, lưỡi, da."},{id:"tnxh1-cac-giac-quan-05",type:"tf",q:"Mũi giúp em biết vị ngọt, vị chua.",emoji:"👃",answer:!1,explain:"Sai. Lưỡi giúp em nếm vị, mũi giúp em ngửi mùi."},{id:"tnxh1-cac-giac-quan-06",type:"tf",q:"Tai giúp em nhìn màu sắc.",emoji:"🌈",answer:!1,explain:"Sai. Mắt mới giúp em nhìn màu sắc."},{id:"tnxh1-cac-giac-quan-07",type:"match",q:"Nối giác quan với việc nó giúp em.",pairs:[["👀 Mắt","Nhìn"],["👂 Tai","Nghe"],["👃 Mũi","Ngửi"],["👅 Lưỡi","Nếm"]],explain:"Mỗi giác quan giúp em biết một điều."},{id:"tnxh1-cac-giac-quan-08",type:"multi",q:"Đâu là giác quan?",emoji:"🧒",options:["Tóc","Da","Mắt","Tai"],answers:[1,2,3],explain:"Mắt, tai, da là giác quan. Tóc không phải giác quan."}]},{questions:[{id:"tnxh1-cac-giac-quan-09",type:"mc",q:"Nhờ giác quan nào em biết cốc nước nóng hay lạnh khi chạm vào?",emoji:"🥤",options:["Da","Mũi","Tai"],answer:0,explain:"Da giúp em biết nóng, lạnh."},{id:"tnxh1-cac-giac-quan-10",type:"mc",q:"Nhờ giác quan nào em biết quả chanh có vị chua?",emoji:"🍋",options:["Đôi tai","Lưỡi","Đôi mắt"],answer:1,explain:"Lưỡi giúp em nếm vị chua."},{id:"tnxh1-cac-giac-quan-11",type:"tf",q:"Nhắm mắt lại, em vẫn có thể nghe tiếng nói.",emoji:"🙈👂",answer:!0,explain:"Đúng. Nghe bằng tai, không cần mắt."},{id:"tnxh1-cac-giac-quan-12",type:"tf",q:"Bịt mũi lại, em ngửi mùi thơm rõ hơn.",emoji:"👃",answer:!1,explain:"Sai. Bịt mũi thì khó ngửi thấy mùi."},{id:"tnxh1-cac-giac-quan-13",type:"match",q:"Nối vật với giác quan giúp em biết về nó.",pairs:[["🎵 Tiếng đàn","Tai"],["🌈 Màu cầu vồng","Mắt"],["🍬 Vị ngọt của kẹo","Lưỡi"],["🧊 Viên đá lạnh","Da"]],explain:"Mỗi giác quan giúp em nhận biết khác nhau."},{id:"tnxh1-cac-giac-quan-14",type:"multi",q:"Ăn một quả cam, em dùng giác quan nào?",emoji:"🍊",options:["Mắt nhìn màu cam","Lưỡi nếm vị ngọt","Mũi ngửi mùi thơm"],answers:[0,1,2],explain:"Ăn quả cam, em dùng cả mắt, mũi và lưỡi."},{id:"tnxh1-cac-giac-quan-15",type:"mc",q:"Vị của đường là vị gì?",emoji:"🍬",options:["Ngọt","Chua","Đắng"],answer:0,explain:"Đường có vị ngọt."},{id:"tnxh1-cac-giac-quan-16",type:"mc",q:"Vị của muối là vị gì?",emoji:"🧂",options:["Ngọt","Mặn","Chua"],answer:1,explain:"Muối có vị mặn."}]},{questions:[{id:"tnxh1-cac-giac-quan-17",type:"mc",q:"Trong bóng tối, em sờ một vật mềm, mịn. Giác quan nào giúp em?",emoji:"🧸",options:["Lưỡi","Da","Mắt"],answer:1,explain:"Da giúp em biết vật mềm hay cứng, mịn hay nhám."},{id:"tnxh1-cac-giac-quan-18",type:"mc",q:"Đang ở trong phòng, Hà ngửi thấy mùi khét. Hà nên làm gì?",emoji:"💨",options:["Bịt mũi ngồi im","Đi ngủ tiếp","Báo ngay người lớn"],answer:2,explain:"Mùi khét có thể do cháy. Hà báo người lớn ngay."},{id:"tnxh1-cac-giac-quan-19",type:"tf",q:"Nghe tiếng còi xe sau lưng, em biết có xe đang đến gần.",emoji:"📯🚗",answer:!0,explain:"Đúng. Tai giúp em nghe tiếng còi xe để tránh."},{id:"tnxh1-cac-giac-quan-20",type:"tf",q:"Không cần mắt, ta vẫn biết được bông hoa màu gì.",emoji:"🌺",answer:!1,explain:"Sai. Muốn biết màu sắc, ta cần nhìn bằng mắt."},{id:"tnxh1-cac-giac-quan-21",type:"multi",q:"Giác quan nào giúp em biết có đám cháy?",emoji:"🔥",options:["Lưỡi nếm vị","Mắt nhìn thấy khói","Mũi ngửi thấy mùi khét"],answers:[1,2],explain:"Mắt thấy khói, mũi ngửi thấy mùi khét giúp em biết có cháy."},{id:"tnxh1-cac-giac-quan-22",type:"mc",q:"Đang chơi ở sân, em biết hết giờ ra chơi nhờ nghe tiếng trống. Giác quan nào giúp em?",emoji:"🥁",options:["Mắt","Lưỡi","Tai"],answer:2,explain:"Tai giúp em nghe tiếng trống."},{id:"tnxh1-cac-giac-quan-23",type:"mc",q:"Chơi trò bịt mắt đoán đồ vật, em dùng giác quan nào để đoán?",emoji:"🙈",options:["Da khi sờ đồ vật","Mắt nhìn đồ vật","Tóc trên đầu"],answer:0,explain:"Bịt mắt, em sờ đồ vật bằng tay, da giúp em đoán."},{id:"tnxh1-cac-giac-quan-24",type:"fill",q:"Em nghe bằng …",emoji:"👂",answer:["tai"],loose:!0,explain:"Tai giúp em nghe."}]}],challenge:{questions:[{id:"tnxh1-cac-giac-quan-25",type:"match",q:"Nối vị với thức ăn.",pairs:[["Ngọt","🍬 Kẹo"],["Chua","🍋 Chanh"],["Mặn","🧂 Muối"]],explain:"Lưỡi giúp em nhận ra các vị."},{id:"tnxh1-cac-giac-quan-26",type:"multi",q:"Khi đi trong vườn hoa, em có thể dùng giác quan nào?",emoji:"🌷",options:["Tai nghe chim hót","Mũi ngửi hương","Mắt ngắm hoa","Da cảm thấy gió mát"],answers:[0,1,2,3],explain:"Em dùng cả mắt, mũi, tai, da để cảm nhận vườn hoa."},{id:"tnxh1-cac-giac-quan-27",type:"mc",q:"Bạn Khoa nghe không rõ. Bộ phận nào của Khoa cần được khám?",emoji:"👂",options:["Tai","Lưỡi","Mũi"],answer:0,explain:"Nghe không rõ thì cần khám tai."},{id:"tnxh1-cac-giac-quan-28",type:"tf",q:"Các giác quan giúp em biết mọi vật xung quanh.",emoji:"🌍",answer:!0,explain:"Đúng. Nhờ giác quan, em nhìn, nghe, ngửi, nếm và cảm nhận."},{id:"tnxh1-cac-giac-quan-09",type:"mc",q:"Nhờ giác quan nào em biết cốc nước nóng hay lạnh khi chạm vào?",emoji:"🥤",options:["Da","Mũi","Tai"],answer:0,explain:"Da giúp em biết nóng, lạnh."},{id:"tnxh1-cac-giac-quan-21",type:"multi",q:"Giác quan nào giúp em biết có đám cháy?",emoji:"🔥",options:["Lưỡi nếm vị","Mắt nhìn thấy khói","Mũi ngửi thấy mùi khét"],answers:[1,2],explain:"Mắt thấy khói, mũi ngửi thấy mùi khét giúp em biết có cháy."}]},summary:["Em có năm giác quan: mắt, tai, mũi, lưỡi, da.","Các giác quan giúp em biết mọi vật xung quanh."]},{id:"tnxh1-bao-ve-giac-quan",title:"Bảo vệ mắt và tai",weeks:[27,28],learn:[{title:"Bảo vệ mắt",text:"Đọc sách nơi đủ ánh sáng, ngồi ngay ngắn. Không nhìn thẳng vào Mặt Trời.",example:"📖 💡 🕶️"},{title:"Ti vi, điện thoại",text:"Em ngồi xa màn hình và không xem quá lâu.",example:"📺 ⏰"},{title:"Bảo vệ tai",text:"Không ngoáy tai bằng vật nhọn, không nghe âm thanh quá to.",example:"👂 🚫 🔊"}],practice:[{questions:[{id:"tnxh1-bao-ve-giac-quan-01",type:"mc",q:"Đọc sách ở đâu tốt cho mắt?",emoji:"💡",options:["Dưới chăn tối","Nơi đủ ánh sáng","Trong bóng tối"],answer:1,explain:"Đọc nơi đủ ánh sáng giúp mắt không mỏi."},{id:"tnxh1-bao-ve-giac-quan-02",type:"mc",q:"Em nên làm gì khi trời nắng gắt?",emoji:"🕶️",options:["Đội mũ, đeo kính râm","Nhìn thẳng vào Mặt Trời","Không đội gì"],answer:0,explain:"Đội mũ, đeo kính giúp che mắt khỏi nắng."},{id:"tnxh1-bao-ve-giac-quan-03",type:"tf",q:"Không được ngoáy tai bằng que nhọn.",emoji:"👂",answer:!0,explain:"Đúng. Que nhọn có thể làm đau, làm hỏng tai."},{id:"tnxh1-bao-ve-giac-quan-04",type:"tf",q:"Xem ti vi thật gần màn hình là tốt cho mắt.",emoji:"📺",answer:!1,explain:"Sai. Ngồi quá gần màn hình làm mắt mỏi, hại mắt."},{id:"tnxh1-bao-ve-giac-quan-05",type:"multi",q:"Việc nào giúp bảo vệ mắt?",emoji:"👀",options:["Đọc sách nơi đủ sáng","Ngồi xa màn hình","Dụi mắt bằng tay bẩn"],answers:[0,1],explain:"Đọc nơi đủ sáng, ngồi xa màn hình giúp bảo vệ mắt."},{id:"tnxh1-bao-ve-giac-quan-06",type:"match",q:"Nối việc làm với giác quan được bảo vệ.",pairs:[["Không nghe nhạc quá to","Bảo vệ tai"],["Đọc sách nơi đủ sáng","Bảo vệ mắt"],["Không ăn đồ quá nóng","Bảo vệ lưỡi"]],explain:"Mỗi việc làm bảo vệ một giác quan."},{id:"tnxh1-bao-ve-giac-quan-07",type:"mc",q:"Khi bụi bay vào mắt, em làm gì?",emoji:"😣",options:["Lấy que nhỏ khều bụi ra","Không dụi mắt, nhờ người lớn giúp","Dụi mắt thật mạnh cho hết bụi"],answer:1,explain:"Dụi mắt có thể làm mắt đau thêm. Em nhờ người lớn."},{id:"tnxh1-bao-ve-giac-quan-08",type:"tf",q:"Ngồi xem điện thoại cả ngày không làm mỏi mắt.",emoji:"📱",answer:!1,explain:"Sai. Xem lâu làm mắt mỏi. Em xem ít và cho mắt nghỉ."}]},{questions:[{id:"tnxh1-bao-ve-giac-quan-09",type:"mc",q:"Vì sao không nên hét to vào tai bạn?",emoji:"🙉",options:["Vì có thể làm tai bạn đau","Vì tai bạn sẽ to ra","Vì bạn sẽ cao lên nhanh hơn"],answer:0,explain:"Âm thanh quá to có thể làm hại tai."},{id:"tnxh1-bao-ve-giac-quan-10",type:"tf",q:"Khi xem ti vi, em nên ngồi thật sát màn hình.",emoji:"📺",answer:!1,explain:"Sai. Ngồi xa màn hình giúp mắt đỡ mỏi."},{id:"tnxh1-bao-ve-giac-quan-11",type:"multi",q:"Việc nào có hại cho tai?",emoji:"👂",options:["Ngoáy tai bằng que nhọn","Để nước bẩn vào tai","Nghe nhạc quá to","Lau vành tai bằng khăn sạch"],answers:[0,1,2],explain:"Nghe quá to, ngoáy tai, để nước bẩn vào tai đều có hại."},{id:"tnxh1-bao-ve-giac-quan-12",type:"mc",q:"Đọc sách, em ngồi thế nào?",emoji:"📖",options:["Nằm sấp trên giường để đọc sách","Cúi thật sát mặt vào trang sách","Ngồi ngay ngắn, sách để vừa tầm mắt"],answer:2,explain:"Ngồi ngay ngắn giúp mắt và lưng khỏe."},{id:"tnxh1-bao-ve-giac-quan-13",type:"match",q:"Nối tình huống với cách làm đúng.",pairs:[["Bụi bay vào mắt","Nhờ người lớn giúp"],["Tai bị đau","Báo bố mẹ đưa đi khám"],["Trời nắng gắt","Đội mũ, đeo kính"]],explain:"Biết cách làm đúng để bảo vệ mắt và tai."},{id:"tnxh1-bao-ve-giac-quan-14",type:"tf",q:"Mắt nhìn mờ thì cần đi khám mắt.",emoji:"👓",answer:!0,explain:"Đúng. Bác sĩ sẽ khám và giúp em nhìn rõ hơn."},{id:"tnxh1-bao-ve-giac-quan-15",type:"mc",q:"Sau một lúc đọc sách, em nên làm gì cho mắt nghỉ?",emoji:"🌳",options:["Nhìn thẳng vào bóng đèn sáng","Xem điện thoại thêm một lúc","Nhìn ra xa, nhìn cây xanh"],answer:2,explain:"Nhìn ra xa, nhìn cây xanh giúp mắt nghỉ ngơi."},{id:"tnxh1-bao-ve-giac-quan-16",type:"tf",q:"Nghe ti vi to hết cỡ giúp tai khỏe hơn.",emoji:"🔊",answer:!1,explain:"Sai. Âm thanh quá to làm hại tai."}]},{questions:[{id:"tnxh1-bao-ve-giac-quan-17",type:"mc",q:"Nam vừa đi bơi về, tai có nước. Nam làm gì?",emoji:"🏊",options:["Nghiêng đầu cho nước chảy ra, nhờ người lớn lau","Đổ thêm nước vào tai cho sạch hơn","Lấy que nhọn ngoáy thật sâu vào bên trong tai"],answer:0,explain:"Nghiêng đầu cho nước ra, không dùng que nhọn."},{id:"tnxh1-bao-ve-giac-quan-18",type:"mc",q:"Trời tối, Chi muốn đọc truyện. Chi làm gì?",emoji:"💡",options:["Đọc trong bóng tối","Đọc dưới chăn","Bật đèn cho đủ sáng"],answer:2,explain:"Đọc nơi đủ sáng để bảo vệ mắt."},{id:"tnxh1-bao-ve-giac-quan-19",type:"tf",q:"Thảo dùng chung khăn mặt với nhiều bạn. Thảo làm đúng.",emoji:"🧻",answer:!1,explain:"Sai. Dùng chung khăn mặt dễ lây bệnh về mắt."},{id:"tnxh1-bao-ve-giac-quan-20",type:"tf",q:"Dũng xem ti vi một lúc rồi đi ra ngoài chơi. Dũng làm đúng.",emoji:"📺",answer:!0,explain:"Đúng. Không xem quá lâu giúp mắt khỏe."},{id:"tnxh1-bao-ve-giac-quan-21",type:"multi",q:"Lớp học ồn ào quá. Em có thể làm gì?",emoji:"🤫",options:["Nhắc bạn giữ trật tự","Nói nhỏ nhẹ","Hét to hơn bạn"],answers:[0,1],explain:"Nói nhỏ, nhắc bạn giữ trật tự giúp bảo vệ tai mọi người."},{id:"tnxh1-bao-ve-giac-quan-22",type:"order",q:"Sắp xếp các việc rửa mặt sạch.",emoji:"🧼",items:["Rửa sạch tay","Làm ướt khăn sạch","Lau mắt, mặt nhẹ nhàng","Giặt khăn, phơi khô"],explain:"Rửa tay, làm ướt khăn, lau mặt rồi giặt phơi khăn."},{id:"tnxh1-bao-ve-giac-quan-23",type:"mc",q:"Khi chơi, bạn ném cát vào mặt. Điều gì có thể xảy ra?",emoji:"⚠️",options:["Cát bay vào mắt gây đau","Mắt sẽ nhìn rõ hơn","Không sao cả, vẫn chơi tiếp"],answer:0,explain:"Cát vào mắt gây đau. Không ném cát vào bạn."},{id:"tnxh1-bao-ve-giac-quan-24",type:"fill",q:"Khi trời nắng gắt, em đội mũ và đeo … râm.",emoji:"🕶️",answer:["kính"],loose:!0,explain:"Kính râm giúp che mắt khỏi nắng chói."}]}],challenge:{questions:[{id:"tnxh1-bao-ve-giac-quan-25",type:"match",q:"Nối việc làm với lí do.",pairs:[["Ngồi xa ti vi","Mắt đỡ mỏi"],["Không ngoáy tai bằng que","Tai không bị thương"],["Đọc nơi đủ sáng","Mắt nhìn rõ"]],explain:"Mỗi việc làm đều giúp bảo vệ giác quan."},{id:"tnxh1-bao-ve-giac-quan-26",type:"multi",q:"Những việc nào bảo vệ mắt và tai?",emoji:"👀👂",options:["Không dùng chung khăn mặt","Khám mắt khi nhìn mờ","Ngồi sát màn hình","Nghe nhạc vừa phải"],answers:[0,1,3],explain:"Khám mắt, không dùng chung khăn, nghe vừa phải giúp bảo vệ mắt và tai."},{id:"tnxh1-bao-ve-giac-quan-27",type:"mc",q:"Vì sao không được nhìn thẳng vào Mặt Trời?",emoji:"☀️",options:["Vì Mặt Trời sẽ tắt ngay lập tức","Vì ánh nắng mạnh có thể làm hại mắt","Vì đôi mắt sẽ to ra"],answer:1,explain:"Ánh sáng Mặt Trời rất mạnh, có thể làm hại mắt."},{id:"tnxh1-bao-ve-giac-quan-28",type:"tf",q:"Khi mắt bị đau, đỏ, em nên báo bố mẹ.",emoji:"👁️",answer:!0,explain:"Đúng. Bố mẹ sẽ đưa em đi khám."},{id:"tnxh1-bao-ve-giac-quan-14",type:"tf",q:"Mắt nhìn mờ thì cần đi khám mắt.",emoji:"👓",answer:!0,explain:"Đúng. Bác sĩ sẽ khám và giúp em nhìn rõ hơn."},{id:"tnxh1-bao-ve-giac-quan-21",type:"multi",q:"Lớp học ồn ào quá. Em có thể làm gì?",emoji:"🤫",options:["Nhắc bạn giữ trật tự","Nói nhỏ nhẹ","Hét to hơn bạn"],answers:[0,1],explain:"Nói nhỏ, nhắc bạn giữ trật tự giúp bảo vệ tai mọi người."}]},summary:["Đọc sách nơi đủ sáng, ngồi xa màn hình để bảo vệ mắt.","Không ngoáy tai bằng vật nhọn, không nghe âm thanh quá to."]},{id:"tnxh1-ve-sinh-co-the",title:"Giữ vệ sinh cơ thể",weeks:[28,29],learn:[{title:"Rửa tay",text:"Rửa tay bằng xà phòng trước khi ăn, sau khi đi vệ sinh và khi tay bẩn.",example:"🧼 🍽️ 🚽"},{title:"Đánh răng",text:"Đánh răng buổi sáng sau khi ngủ dậy và buổi tối trước khi đi ngủ.",example:"🪥 🌅 🌙"},{title:"Tắm gội",text:"Tắm gội thường xuyên, thay quần áo sạch, cắt ngắn móng tay.",example:"🛁 👕 💅"}],practice:[{questions:[{id:"tnxh1-ve-sinh-co-the-01",type:"mc",q:"Em rửa tay bằng gì cho sạch?",emoji:"🧼",options:["Nước sạch và xà phòng","Nước bẩn trong chậu","Cát ở ngoài sân"],answer:0,explain:"Rửa tay bằng xà phòng và nước sạch."},{id:"tnxh1-ve-sinh-co-the-02",type:"mc",q:"Em dùng gì để đánh răng?",emoji:"🪥",options:["Bàn chải và kem đánh răng","Lược chải tóc và gương","Khăn mặt và chậu nước"],answer:0,explain:"Em đánh răng bằng bàn chải và kem đánh răng."},{id:"tnxh1-ve-sinh-co-the-03",type:"tf",q:"Em rửa tay trước khi ăn.",emoji:"🍽️",answer:!0,explain:"Đúng. Rửa tay trước khi ăn để không đưa vi khuẩn vào miệng."},{id:"tnxh1-ve-sinh-co-the-04",type:"tf",q:"Không cần rửa tay sau khi đi vệ sinh.",emoji:"🚽",answer:!1,explain:"Sai. Phải rửa tay bằng xà phòng sau khi đi vệ sinh."},{id:"tnxh1-ve-sinh-co-the-05",type:"number",q:"Mỗi ngày em đánh răng ít nhất mấy lần?",emoji:"🪥",answer:2,explain:"Em đánh răng ít nhất 2 lần: buổi sáng và buổi tối."},{id:"tnxh1-ve-sinh-co-the-06",type:"match",q:"Nối đồ dùng với việc vệ sinh.",pairs:[["🪥 Bàn chải","Đánh răng"],["🧼 Xà phòng","Rửa tay"],["💅 Bấm móng tay","Cắt móng tay"],["🧴 Dầu gội","Gội đầu"]],explain:"Mỗi đồ dùng giúp em giữ vệ sinh."},{id:"tnxh1-ve-sinh-co-the-07",type:"multi",q:"Khi nào em cần rửa tay?",emoji:"🧼",options:["Khi vừa rửa tay xong","Sau khi đi vệ sinh","Sau khi chơi đất cát","Trước khi ăn"],answers:[1,2,3],explain:"Rửa tay trước khi ăn, sau khi đi vệ sinh, sau khi chơi bẩn."},{id:"tnxh1-ve-sinh-co-the-08",type:"mc",q:"Móng tay dài, bẩn thì em làm gì?",emoji:"💅",options:["Nhờ người lớn cắt ngắn","Cắn móng tay cho ngắn","Để mặc, không cần làm gì"],answer:0,explain:"Móng tay cần được cắt ngắn, giữ sạch."}]},{questions:[{id:"tnxh1-ve-sinh-co-the-09",type:"mc",q:"Vì sao phải rửa tay trước khi ăn?",emoji:"🦠",options:["Để ăn được nhanh hơn","Để vi khuẩn không vào miệng","Để bàn tay mềm và trắng hơn"],answer:1,explain:"Tay bẩn có vi khuẩn, rửa tay giúp phòng bệnh."},{id:"tnxh1-ve-sinh-co-the-10",type:"mc",q:"Vì sao phải đánh răng trước khi đi ngủ?",emoji:"🦷",options:["Để răng không bị sâu","Để răng mọc to hơn","Để được thức khuya hơn"],answer:0,explain:"Đánh răng giúp làm sạch răng, phòng sâu răng."},{id:"tnxh1-ve-sinh-co-the-11",type:"tf",q:"Ăn nhiều kẹo mà không đánh răng dễ bị sâu răng.",emoji:"🍬🦷",answer:!0,explain:"Đúng. Kẹo bám vào răng dễ gây sâu răng."},{id:"tnxh1-ve-sinh-co-the-12",type:"tf",q:"Mặc lại quần áo đẫm mồ hôi nhiều ngày là sạch sẽ.",emoji:"👕",answer:!1,explain:"Sai. Quần áo bẩn cần được thay và giặt sạch."},{id:"tnxh1-ve-sinh-co-the-13",type:"match",q:"Nối việc vệ sinh với lợi ích.",pairs:[["Đánh răng","Răng chắc khỏe"],["Rửa tay","Phòng bệnh"],["Tắm gội","Cơ thể sạch, thơm"]],explain:"Giữ vệ sinh giúp cơ thể khỏe mạnh."},{id:"tnxh1-ve-sinh-co-the-14",type:"multi",q:"Việc nào giữ cơ thể sạch sẽ?",emoji:"🛁",options:["Cắt móng tay","Tắm gội thường xuyên","Đi chân đất lội bùn","Thay quần áo sạch"],answers:[0,1,3],explain:"Tắm gội, thay quần áo, cắt móng tay giúp cơ thể sạch."},{id:"tnxh1-ve-sinh-co-the-15",type:"mc",q:"Tắm xong, em lau người bằng gì?",emoji:"🛁",options:["Quần áo bẩn","Khăn tắm sạch","Rèm cửa"],answer:1,explain:"Lau người bằng khăn tắm sạch, khô."},{id:"tnxh1-ve-sinh-co-the-16",type:"tf",q:"Mỗi người nên dùng khăn mặt và bàn chải riêng.",emoji:"🪥",answer:!0,explain:"Đúng. Dùng đồ riêng giúp tránh lây bệnh."}]},{questions:[{id:"tnxh1-ve-sinh-co-the-17",type:"mc",q:"Chơi đá bóng xong, người đầy mồ hôi. Minh làm gì?",emoji:"⚽",options:["Mặc nguyên quần áo đi ngủ","Ăn ngay mà không rửa tay","Tắm rửa, thay quần áo sạch"],answer:2,explain:"Tắm rửa, thay quần áo giúp cơ thể sạch sẽ."},{id:"tnxh1-ve-sinh-co-the-18",type:"mc",q:"Lan chơi với mèo xong định ăn bánh. Lan cần làm gì trước?",emoji:"🐱🍰",options:["Lau tay vào áo cho sạch","Rửa tay bằng xà phòng","Ăn bánh luôn"],answer:1,explain:"Chơi với con vật xong cần rửa tay trước khi ăn."},{id:"tnxh1-ve-sinh-co-the-19",type:"tf",q:"Phúc dùng chung bàn chải đánh răng với em. Phúc làm đúng.",emoji:"🪥",answer:!1,explain:"Sai. Mỗi người dùng bàn chải riêng."},{id:"tnxh1-ve-sinh-co-the-20",type:"tf",q:"Ngọc đánh răng xong rồi mới đi ngủ. Ngọc làm đúng.",emoji:"🌙",answer:!0,explain:"Đúng. Đánh răng trước khi ngủ giúp răng không bị sâu."},{id:"tnxh1-ve-sinh-co-the-21",type:"order",q:"Sắp xếp các bước rửa tay.",emoji:"🧼",items:["Làm ướt tay","Xoa xà phòng khắp tay","Rửa sạch xà phòng","Lau khô tay"],explain:"Làm ướt, xoa xà phòng, rửa sạch rồi lau khô."},{id:"tnxh1-ve-sinh-co-the-22",type:"multi",q:"Ho, hắt hơi, em nên làm gì?",emoji:"🤧",options:["Hắt hơi thẳng vào mặt bạn","Quay đi chỗ khác, không hướng vào bạn","Che miệng bằng khăn hoặc khuỷu tay"],answers:[1,2],explain:"Che miệng và quay đi để không lây bệnh cho bạn."},{id:"tnxh1-ve-sinh-co-the-23",type:"mc",q:"Răng sâu, đau nhức. Em nên làm gì?",emoji:"🦷",options:["Không đánh răng nữa cho đỡ đau","Báo bố mẹ đưa đi khám răng","Ăn thêm thật nhiều kẹo"],answer:1,explain:"Bác sĩ nha khoa sẽ chữa răng cho em."},{id:"tnxh1-ve-sinh-co-the-24",type:"fill",q:"Em rửa tay bằng xà … và nước sạch.",emoji:"🧼",answer:["phòng"],loose:!0,explain:"Rửa tay bằng xà phòng."}]}],challenge:{questions:[{id:"tnxh1-ve-sinh-co-the-25",type:"order",q:"Sắp xếp các việc đánh răng.",emoji:"🪥",items:["Lấy kem lên bàn chải","Chải mặt trong, mặt ngoài răng","Súc miệng bằng nước sạch","Rửa sạch bàn chải"],explain:"Lấy kem, chải răng, súc miệng, rửa bàn chải."},{id:"tnxh1-ve-sinh-co-the-26",type:"match",q:"Nối thời điểm với việc vệ sinh.",pairs:[["Buổi sáng ngủ dậy","Đánh răng, rửa mặt"],["Trước bữa ăn","Rửa tay"],["Sau khi chơi thể thao","Tắm, thay quần áo"]],explain:"Mỗi lúc có việc vệ sinh phù hợp."},{id:"tnxh1-ve-sinh-co-the-27",type:"mc",q:"Thức ăn nào ăn nhiều dễ gây sâu răng?",emoji:"🍭",options:["Rau xanh","Nước lọc","Kẹo ngọt"],answer:2,explain:"Đồ ngọt bám vào răng dễ gây sâu răng."},{id:"tnxh1-ve-sinh-co-the-28",type:"tf",q:"Chỉ cần rửa tay bằng nước, không cần xà phòng, là đủ sạch.",emoji:"🧼",answer:!1,explain:"Sai. Xà phòng giúp rửa trôi vi khuẩn tốt hơn."},{id:"tnxh1-ve-sinh-co-the-05",type:"number",q:"Mỗi ngày em đánh răng ít nhất mấy lần?",emoji:"🪥",answer:2,explain:"Em đánh răng ít nhất 2 lần: buổi sáng và buổi tối."},{id:"tnxh1-ve-sinh-co-the-22",type:"multi",q:"Ho, hắt hơi, em nên làm gì?",emoji:"🤧",options:["Hắt hơi thẳng vào mặt bạn","Quay đi chỗ khác, không hướng vào bạn","Che miệng bằng khăn hoặc khuỷu tay"],answers:[1,2],explain:"Che miệng và quay đi để không lây bệnh cho bạn."}]},summary:["Em rửa tay bằng xà phòng trước khi ăn và sau khi đi vệ sinh.","Em đánh răng sáng và tối, tắm gội, thay quần áo sạch."]},{id:"tnxh1-an-uong-van-dong",title:"Ăn uống, vận động và nghỉ ngơi",weeks:[29,30],learn:[{title:"Ăn đủ chất",text:"Em ăn đủ bữa, ăn nhiều loại thức ăn: cơm, thịt, cá, trứng, rau, quả.",example:"🍚 🍗 🐟 🥚 🥦 🍎"},{title:"Uống nước",text:"Em uống đủ nước sạch mỗi ngày, ít uống nước ngọt có ga.",example:"💧 🥤🚫"},{title:"Vận động và nghỉ ngơi",text:"Em vận động, chơi thể thao và ngủ đủ giấc để khỏe mạnh.",example:"🏃 ⚽ 😴"}],practice:[{questions:[{id:"tnxh1-an-uong-van-dong-01",type:"mc",q:"Bữa ăn nào có lợi cho sức khỏe?",emoji:"🍱",options:["Chỉ có kẹo","Cơm, cá, rau, quả","Chỉ có nước ngọt"],answer:1,explain:"Ăn đủ nhiều loại thức ăn giúp cơ thể khỏe."},{id:"tnxh1-an-uong-van-dong-02",type:"mc",q:"Em nên uống gì hằng ngày?",emoji:"💧",options:["Nước sạch","Nước lã chưa đun sôi","Nước ao hồ"],answer:0,explain:"Uống nước sạch để không bị bệnh."},{id:"tnxh1-an-uong-van-dong-03",type:"tf",q:"Ăn sáng giúp em có sức để học tập.",emoji:"🥣",answer:!0,explain:"Đúng. Bữa sáng cho em sức khỏe để học."},{id:"tnxh1-an-uong-van-dong-04",type:"tf",q:"Chỉ ăn bánh kẹo, không ăn cơm là tốt.",emoji:"🍬",answer:!1,explain:"Sai. Em cần ăn đủ bữa, đủ chất."},{id:"tnxh1-an-uong-van-dong-05",type:"multi",q:"Thức ăn nào tốt cho sức khỏe?",emoji:"🥗",options:["Nhiều kẹo ngọt","Cá","Rau xanh","Hoa quả"],answers:[1,2,3],explain:"Rau, quả, cá tốt cho sức khỏe. Ăn nhiều kẹo hại răng."},{id:"tnxh1-an-uong-van-dong-06",type:"match",q:"Nối hoạt động với lợi ích.",pairs:[["🏃 Chạy nhảy","Cơ thể khỏe"],["😴 Ngủ đủ giấc","Tỉnh táo khi học"],["🥦 Ăn rau","Đủ chất"]],explain:"Ăn, vận động, nghỉ ngơi hợp lí giúp em khỏe mạnh."},{id:"tnxh1-an-uong-van-dong-07",type:"mc",q:"Buổi tối, em nên đi ngủ thế nào?",emoji:"🌙",options:["Thức rất khuya xem điện thoại","Không ngủ","Ngủ sớm, đủ giấc"],answer:2,explain:"Ngủ sớm, đủ giấc giúp cơ thể khỏe và lớn lên."},{id:"tnxh1-an-uong-van-dong-08",type:"tf",q:"Tập thể dục giúp cơ thể khỏe mạnh.",emoji:"🤸",answer:!0,explain:"Đúng. Vận động giúp em khỏe và vui vẻ."}]},{questions:[{id:"tnxh1-an-uong-van-dong-09",type:"mc",q:"Vì sao cần ăn nhiều loại thức ăn?",emoji:"🍽️",options:["Để ăn được nhanh hơn","Để bụng to ra thật nhanh","Để cơ thể có đủ chất"],answer:2,explain:"Mỗi loại thức ăn cho cơ thể chất khác nhau."},{id:"tnxh1-an-uong-van-dong-10",type:"tf",q:"Uống nhiều nước ngọt có ga tốt hơn uống nước lọc.",emoji:"🥤",answer:!1,explain:"Sai. Nước lọc tốt hơn. Nước ngọt nhiều đường hại răng."},{id:"tnxh1-an-uong-van-dong-11",type:"multi",q:"Việc nào giúp em lớn lên khỏe mạnh?",emoji:"💪",options:["Vận động hằng ngày","Ăn đủ bữa","Ngủ đủ giấc","Bỏ bữa sáng"],answers:[0,1,2],explain:"Ăn đủ, ngủ đủ, vận động giúp em khỏe mạnh."},{id:"tnxh1-an-uong-van-dong-12",type:"mc",q:"Ăn cơm xong, em nên làm gì?",emoji:"🍚",options:["Nghỉ ngơi một lúc","Chạy nhảy thật mạnh ngay","Đi bơi ngay"],answer:0,explain:"Ăn xong nên nghỉ một lúc, không vận động mạnh ngay."},{id:"tnxh1-an-uong-van-dong-13",type:"match",q:"Nối thức ăn với nhóm.",pairs:[["🥦 Súp lơ xanh","Rau"],["🍌 Chuối","Quả"],["🐟 Cá","Thịt, cá"],["🍚 Cơm","Tinh bột, gạo"]],explain:"Mỗi thức ăn thuộc một nhóm."},{id:"tnxh1-an-uong-van-dong-14",type:"tf",q:"Vừa ăn vừa xem ti vi là thói quen tốt.",emoji:"📺",answer:!1,explain:"Sai. Em nên tập trung ăn cùng gia đình."},{id:"tnxh1-an-uong-van-dong-15",type:"mc",q:"Em nên ăn quả như thế nào cho sạch?",emoji:"🍎",options:["Rửa sạch hoặc gọt vỏ trước khi ăn","Nhặt quả rơi dưới đất ăn ngay","Không cần rửa, ăn luôn cho nhanh"],answer:0,explain:"Quả cần rửa sạch, gọt vỏ trước khi ăn."},{id:"tnxh1-an-uong-van-dong-16",type:"tf",q:"Ngủ trưa một chút giúp buổi chiều em tỉnh táo.",emoji:"😴",answer:!0,explain:"Đúng. Nghỉ trưa giúp em có sức học buổi chiều."}]},{questions:[{id:"tnxh1-an-uong-van-dong-17",type:"mc",q:"Khoa không thích ăn rau. Khoa nên làm gì?",emoji:"🥦",options:["Chỉ ăn kẹo để thay cho rau","Bỏ hẳn rau, không ăn nữa","Tập ăn rau mỗi ngày một ít"],answer:2,explain:"Rau rất tốt, Khoa tập ăn dần mỗi ngày."},{id:"tnxh1-an-uong-van-dong-18",type:"mc",q:"Trời nóng, chơi xong khát nước. Em uống gì?",emoji:"💧",options:["Nước sạch đã đun sôi để nguội","Nước mưa đọng trong vũng","Nước máy chưa được đun sôi"],answer:0,explain:"Uống nước sạch, đun sôi để nguội."},{id:"tnxh1-an-uong-van-dong-19",type:"tf",q:"Thảo thức khuya xem điện thoại, sáng dậy mệt. Thảo nên ngủ sớm hơn.",emoji:"📱😴",answer:!0,explain:"Đúng. Ngủ sớm giúp Thảo khỏe và tỉnh táo."},{id:"tnxh1-an-uong-van-dong-20",type:"tf",q:"Ngồi một chỗ chơi điện tử cả ngày giúp cơ thể khỏe.",emoji:"🎮",answer:!1,explain:"Sai. Em cần vận động, ra ngoài chơi."},{id:"tnxh1-an-uong-van-dong-21",type:"order",q:"Sắp xếp các việc trước bữa ăn tối.",emoji:"🍚",items:["Rửa tay","Giúp mẹ dọn bát đũa","Mời ông bà, bố mẹ","Ăn cơm"],explain:"Rửa tay, dọn bát, mời người lớn rồi ăn."},{id:"tnxh1-an-uong-van-dong-22",type:"multi",q:"Môn thể thao nào em có thể tập?",emoji:"🏊",options:["Nhảy dây","Leo lên mái nhà","Bơi khi có người lớn trông","Đá cầu"],answers:[0,2,3],explain:"Bơi có người lớn, đá cầu, nhảy dây là thể thao an toàn."},{id:"tnxh1-an-uong-van-dong-23",type:"mc",q:"Bữa sáng nào tốt nhất trước khi đi học?",emoji:"🥣",options:["Bát phở hoặc bát cháo, cốc sữa","Nhịn đói, không ăn gì cả rồi đi học","Chỉ ăn một gói bim bim"],answer:0,explain:"Bữa sáng đủ chất giúp em có sức học tập."},{id:"tnxh1-an-uong-van-dong-24",type:"fill",q:"Em uống nước … để không bị bệnh.",emoji:"💧",answer:["sạch"],loose:!0,explain:"Em uống nước sạch."}]}],challenge:{questions:[{id:"tnxh1-an-uong-van-dong-25",type:"match",q:"Nối thói quen với kết quả.",pairs:[["Ăn nhiều đồ ngọt","Dễ sâu răng"],["Ngủ đủ giấc","Tỉnh táo"],["Vận động hằng ngày","Cơ thể khỏe"],["Bỏ bữa sáng","Đói, mệt khi học"]],explain:"Thói quen tốt giúp em khỏe mạnh."},{id:"tnxh1-an-uong-van-dong-26",type:"multi",q:"Ngày nắng nóng, em cần làm gì?",emoji:"☀️",options:["Đội mũ khi ra ngoài","Chạy ngoài nắng giữa trưa","Uống đủ nước","Chơi ở chỗ râm mát"],answers:[0,2,3],explain:"Uống đủ nước, đội mũ, chơi chỗ mát để không bị say nắng."},{id:"tnxh1-an-uong-van-dong-27",type:"mc",q:"Một ngày của em nên thế nào?",emoji:"⏰",options:["Có giờ học, giờ chơi, giờ ngủ hợp lí","Chỉ ngồi xem ti vi từ sáng đến tối","Chỉ chơi suốt ngày, không học bài"],answer:0,explain:"Học, chơi, ngủ hợp lí giúp em khỏe và học tốt."},{id:"tnxh1-an-uong-van-dong-28",type:"tf",q:"Ăn quá no rồi chạy nhảy ngay có thể bị đau bụng.",emoji:"🤢",answer:!0,explain:"Đúng. Ăn xong nên nghỉ một lúc."},{id:"tnxh1-an-uong-van-dong-12",type:"mc",q:"Ăn cơm xong, em nên làm gì?",emoji:"🍚",options:["Nghỉ ngơi một lúc","Chạy nhảy thật mạnh ngay","Đi bơi ngay"],answer:0,explain:"Ăn xong nên nghỉ một lúc, không vận động mạnh ngay."},{id:"tnxh1-an-uong-van-dong-22",type:"multi",q:"Môn thể thao nào em có thể tập?",emoji:"🏊",options:["Nhảy dây","Leo lên mái nhà","Bơi khi có người lớn trông","Đá cầu"],answers:[0,2,3],explain:"Bơi có người lớn, đá cầu, nhảy dây là thể thao an toàn."}]},summary:["Em ăn đủ bữa, đủ chất, uống nước sạch.","Em vận động hằng ngày và ngủ đủ giấc."]},{id:"tnxh1-an-toan-co-the",title:"Giữ an toàn cho cơ thể",weeks:[30,30],learn:[{title:"Vùng riêng tư",text:"Vùng cơ thể được đồ lót, đồ bơi che lại là vùng riêng tư. Không ai được chạm vào vùng đó.",example:"🩱 🩲 🚫"},{title:"Ba việc cần nhớ",text:"Nếu ai đó chạm vào làm em sợ, em nói “Không!”, chạy đi và kể với người lớn tin cậy.",example:"✋ 🏃 🗣️"},{title:"Người lạ",text:"Em không nhận quà, không đi theo người lạ.",example:"🍬 🚫 🧑"}],practice:[{questions:[{id:"tnxh1-an-toan-co-the-01",type:"mc",q:"Vùng nào trên cơ thể là vùng riêng tư?",emoji:"🩱",options:["Mái tóc và đôi tai","Đôi bàn tay và cánh tay","Vùng được đồ bơi che lại"],answer:2,explain:"Vùng được đồ lót, đồ bơi che lại là vùng riêng tư."},{id:"tnxh1-an-toan-co-the-02",type:"mc",q:"Người lạ cho kẹo và rủ đi chơi. Em làm gì?",emoji:"🍬",options:["Nhận kẹo và đi theo người đó","Không nhận, không đi theo","Hỏi xin thêm thật nhiều kẹo"],answer:1,explain:"Em không nhận quà, không đi theo người lạ."},{id:"tnxh1-an-toan-co-the-03",type:"tf",q:"Em có quyền nói “Không!” khi ai đó chạm vào làm em sợ.",emoji:"✋",answer:!0,explain:"Đúng. Cơ thể em là của em. Em có quyền nói không."},{id:"tnxh1-an-toan-co-the-04",type:"tf",q:"Có chuyện làm em sợ, em nên giấu kín, không kể với ai.",emoji:"🗣️",answer:!1,explain:"Sai. Em kể ngay với bố mẹ, thầy cô hoặc người lớn tin cậy."},{id:"tnxh1-an-toan-co-the-05",type:"multi",q:"Ai là người lớn tin cậy em có thể kể chuyện?",emoji:"🧑‍🤝‍🧑",options:["Bố mẹ","Ông bà","Thầy cô giáo","Người lạ ngoài đường"],answers:[0,1,2],explain:"Bố mẹ, thầy cô, ông bà là người tin cậy. Không kể chuyện với người lạ."},{id:"tnxh1-an-toan-co-the-06",type:"order",q:"Sắp xếp ba việc cần làm khi gặp người làm em sợ.",emoji:"✋🏃🗣️",items:["Nói “Không!”","Chạy đi","Kể với người lớn tin cậy"],explain:"Nói không, chạy đi, kể với người lớn tin cậy."},{id:"tnxh1-an-toan-co-the-07",type:"mc",q:"Khi đi chơi nơi đông người, em đi thế nào?",emoji:"👨‍👧",options:["Đi theo một người lạ","Tự đi một mình đến chỗ khác","Đi sát người lớn trong nhà"],answer:2,explain:"Đi sát người lớn để không bị lạc."},{id:"tnxh1-an-toan-co-the-08",type:"tf",q:"Em nên nhớ số điện thoại của bố hoặc mẹ.",emoji:"📞",answer:!0,explain:"Đúng. Nhớ số điện thoại để gọi khi cần giúp."}]},{questions:[{id:"tnxh1-an-toan-co-the-09",type:"mc",q:"Vì sao em không được đi theo người lạ?",emoji:"⚠️",options:["Vì người lạ đi nhanh","Vì có thể gặp nguy hiểm","Vì người lạ cao"],answer:1,explain:"Đi theo người lạ có thể gặp nguy hiểm."},{id:"tnxh1-an-toan-co-the-10",type:"tf",q:"Bác sĩ khám bệnh khi có bố mẹ ở bên là việc bình thường.",emoji:"🩺",answer:!0,explain:"Đúng. Bác sĩ khám bệnh khi có bố mẹ đi cùng."},{id:"tnxh1-an-toan-co-the-11",type:"tf",q:"Người quen mà làm em sợ thì em cũng không được kể với ai.",emoji:"🗣️",answer:!1,explain:"Sai. Ai làm em sợ, em cũng kể với người lớn tin cậy."},{id:"tnxh1-an-toan-co-the-12",type:"multi",q:"Việc nào giúp em an toàn?",emoji:"🛡️",options:["Kể với bố mẹ khi thấy sợ","Không nhận quà của người lạ","Không mở cửa cho người lạ","Đi theo người lạ"],answers:[0,1,2],explain:"Không mở cửa, không nhận quà của người lạ, kể với bố mẹ giúp em an toàn."},{id:"tnxh1-an-toan-co-the-13",type:"match",q:"Nối tình huống với việc nên làm.",pairs:[["Người lạ cho quà","Từ chối"],["Bị lạc ở chợ","Nhờ cô bán hàng hoặc bảo vệ"],["Có ai làm em sợ","Kể với người lớn tin cậy"]],explain:"Em bình tĩnh, làm đúng để giữ an toàn."},{id:"tnxh1-an-toan-co-the-14",type:"mc",q:"Tan học, bố mẹ chưa đến đón. Em làm gì?",emoji:"🏫",options:["Đi nhờ xe của một người lạ","Chờ trong trường cùng thầy cô","Tự đi bộ về nhà một mình"],answer:1,explain:"Em chờ trong trường cùng thầy cô."},{id:"tnxh1-an-toan-co-the-15",type:"tf",q:"Thay quần áo ở nơi kín đáo là đúng.",emoji:"🚪",answer:!0,explain:"Đúng. Em thay quần áo ở nơi kín đáo."},{id:"tnxh1-an-toan-co-the-16",type:"mc",q:"Muốn gọi bố mẹ khi cần giúp đỡ, em cần nhớ gì?",emoji:"📞",options:["Số điện thoại của bố mẹ","Tên của con mèo nhà em","Màu áo của bạn ngồi cạnh"],answer:0,explain:"Nhớ số điện thoại bố mẹ để gọi khi cần."}]},{questions:[{id:"tnxh1-an-toan-co-the-17",type:"mc",q:"Một người lạ nói: “Mẹ cháu nhờ chú đón cháu.” Em làm gì?",emoji:"🏫",options:["Nhận kẹo của chú rồi đi theo chú","Không đi, báo thầy cô gọi điện cho mẹ","Đi theo người lạ ngay lập tức"],answer:1,explain:"Em không đi theo, nhờ thầy cô gọi hỏi mẹ."},{id:"tnxh1-an-toan-co-the-18",type:"mc",q:"Có người bảo em giữ bí mật một chuyện làm em sợ. Em làm gì?",emoji:"🗣️",options:["Giữ kín chuyện đó mãi","Khóc một mình, không nói ai","Kể ngay với bố mẹ"],answer:2,explain:"Chuyện làm em sợ không phải bí mật. Em kể với bố mẹ."},{id:"tnxh1-an-toan-co-the-19",type:"tf",q:"Bình bị lạc trong siêu thị, Bình đến nhờ cô thu ngân giúp. Bình làm đúng.",emoji:"🛒",answer:!0,explain:"Đúng. Cô thu ngân là người làm việc ở siêu thị, có thể giúp gọi bố mẹ."},{id:"tnxh1-an-toan-co-the-20",type:"tf",q:"An ở nhà một mình, mở cửa cho người lạ vào. An làm đúng.",emoji:"🚪",answer:!1,explain:"Sai. An không mở cửa cho người lạ."},{id:"tnxh1-an-toan-co-the-21",type:"multi",q:"Em cần nhớ những gì để được giúp khi bị lạc?",emoji:"🏠",options:["Nhớ địa chỉ nhà","Nhớ tên phim hoạt hình","Nhớ số điện thoại bố mẹ","Nhớ tên bố mẹ"],answers:[0,2,3],explain:"Nhớ tên, số điện thoại bố mẹ và địa chỉ nhà giúp em khi bị lạc."},{id:"tnxh1-an-toan-co-the-22",type:"match",q:"Nối người với cách em ứng xử.",pairs:[["Bố mẹ","Kể mọi chuyện làm em lo"],["Người lạ cho quà","Lắc đầu từ chối"],["Bạn cùng lớp","Chơi vui, tôn trọng nhau"]],explain:"Em biết ứng xử đúng với mỗi người."},{id:"tnxh1-an-toan-co-the-23",type:"mc",q:"Bạn trêu chạm vào vùng riêng tư của em. Em làm gì?",emoji:"✋",options:["Cười cho qua rồi thôi","Nói “Không!” và báo thầy cô","Im lặng, không kể với ai"],answer:1,explain:"Em nói không và báo thầy cô."},{id:"tnxh1-an-toan-co-the-24",type:"fill",q:"Khi ai đó làm em sợ, em nói “…!” rồi chạy đi.",emoji:"✋",answer:["không"],loose:!0,explain:"Em nói “Không!”, chạy đi và kể với người lớn tin cậy."}]}],challenge:{questions:[{id:"tnxh1-an-toan-co-the-25",type:"multi",q:"Chuyện nào em cần kể ngay với người lớn tin cậy?",emoji:"🗣️",options:["Em được điểm tốt","Người lạ rủ đi chơi","Có người chạm vào vùng riêng tư","Có người dọa nạt em"],answers:[1,2,3],explain:"Chuyện làm em sợ hoặc nguy hiểm, em kể ngay. Điểm tốt thì vui vẻ khoe bố mẹ."},{id:"tnxh1-an-toan-co-the-26",type:"mc",q:"Vì sao em cần kể với người lớn tin cậy khi gặp chuyện làm em sợ?",emoji:"🛡️",options:["Để bị người lớn mắng thêm","Để người lớn bảo vệ, giúp đỡ em","Để được người lớn cho thêm quà"],answer:1,explain:"Người lớn tin cậy sẽ bảo vệ và giúp em."},{id:"tnxh1-an-toan-co-the-27",type:"tf",q:"Cơ thể của em là của em, em cần được tôn trọng.",emoji:"🧒",answer:!0,explain:"Đúng. Mọi người cần tôn trọng cơ thể của em."},{id:"tnxh1-an-toan-co-the-28",type:"match",q:"Nối tình huống với số điện thoại.",pairs:[["Cần công an giúp","113"],["Có cháy","114"],["Cần cấp cứu","115"]],explain:"Nhớ: 113 công an, 114 cứu hỏa, 115 cấp cứu."},{id:"tnxh1-an-toan-co-the-17",type:"mc",q:"Một người lạ nói: “Mẹ cháu nhờ chú đón cháu.” Em làm gì?",emoji:"🏫",options:["Nhận kẹo của chú rồi đi theo chú","Không đi, báo thầy cô gọi điện cho mẹ","Đi theo người lạ ngay lập tức"],answer:1,explain:"Em không đi theo, nhờ thầy cô gọi hỏi mẹ."},{id:"tnxh1-an-toan-co-the-19",type:"tf",q:"Bình bị lạc trong siêu thị, Bình đến nhờ cô thu ngân giúp. Bình làm đúng.",emoji:"🛒",answer:!0,explain:"Đúng. Cô thu ngân là người làm việc ở siêu thị, có thể giúp gọi bố mẹ."}]},summary:["Vùng đồ bơi che lại là vùng riêng tư.","Gặp chuyện làm em sợ: nói “Không!”, chạy đi, kể với người lớn tin cậy.","Em không nhận quà, không đi theo người lạ."]}]},{id:"trai-dat-bau-troi",title:"Trái Đất và bầu trời",lessons:[{id:"tnxh1-bau-troi-ban-ngay",title:"Bầu trời ban ngày",weeks:[31,32],learn:[{title:"Ban ngày",text:"Ban ngày có Mặt Trời. Trời sáng, ta nhìn thấy mây trên bầu trời.",example:"☀️ ☁️ 🌤️"},{title:"Mặt Trời",text:"Mặt Trời chiếu sáng và sưởi ấm cho mọi vật trên Trái Đất.",example:"☀️ 🌍 🌱"},{title:"Mọc và lặn",text:"Buổi sáng Mặt Trời mọc, buổi chiều Mặt Trời lặn.",example:"🌅 🌇"}],practice:[{questions:[{id:"tnxh1-bau-troi-ban-ngay-01",type:"mc",q:"Ban ngày, trên bầu trời ta thấy gì chiếu sáng?",emoji:"☀️",options:["Đom đóm","Mặt Trời","Bóng đèn"],answer:1,explain:"Ban ngày có Mặt Trời chiếu sáng."},{id:"tnxh1-bau-troi-ban-ngay-02",type:"mc",q:"Mặt Trời mọc vào lúc nào?",emoji:"🌅",options:["Buổi tối","Buổi sáng","Nửa đêm"],answer:1,explain:"Mặt Trời mọc vào buổi sáng."},{id:"tnxh1-bau-troi-ban-ngay-03",type:"tf",q:"Mặt Trời chiếu sáng và sưởi ấm mọi vật.",emoji:"☀️",answer:!0,explain:"Đúng. Nhờ Mặt Trời, mọi vật được chiếu sáng và sưởi ấm."},{id:"tnxh1-bau-troi-ban-ngay-04",type:"tf",q:"Ban ngày, bầu trời tối đen như mực.",emoji:"🌤️",answer:!1,explain:"Sai. Ban ngày có Mặt Trời nên trời sáng."},{id:"tnxh1-bau-troi-ban-ngay-05",type:"match",q:"Nối thời điểm với hình ảnh.",pairs:[["Bình minh","🌅 Mặt Trời mọc"],["Hoàng hôn","🌇 Mặt Trời lặn"],["Ban đêm","🌙 Trăng sao"]],explain:"Mỗi lúc trong ngày bầu trời khác nhau."},{id:"tnxh1-bau-troi-ban-ngay-06",type:"multi",q:"Ban ngày, em có thể thấy gì trên bầu trời?",emoji:"🌤️",options:["Mặt Trời","Mây","Đèn đường bật sáng","Chim bay"],answers:[0,1,3],explain:"Ban ngày có Mặt Trời, mây, chim bay."},{id:"tnxh1-bau-troi-ban-ngay-07",type:"mc",q:"Mặt Trời lặn vào lúc nào?",emoji:"🌇",options:["Buổi chiều","Buổi sáng sớm","Giữa trưa"],answer:0,explain:"Mặt Trời lặn vào buổi chiều."},{id:"tnxh1-bau-troi-ban-ngay-08",type:"tf",q:"Mây có nhiều hình dạng khác nhau.",emoji:"☁️",answer:!0,explain:"Đúng. Mây có thể trông giống con vật, đồ vật."}]},{questions:[{id:"tnxh1-bau-troi-ban-ngay-09",type:"mc",q:"Vì sao ban ngày trời sáng?",emoji:"☀️",options:["Vì trời có nhiều gió thổi","Vì có thật nhiều mây trắng","Vì có Mặt Trời chiếu sáng"],answer:2,explain:"Mặt Trời chiếu sáng làm trời sáng."},{id:"tnxh1-bau-troi-ban-ngay-10",type:"mc",q:"Mặt Trời mọc ở phía nào?",emoji:"🌅",options:["Phía tây","Dưới đất","Phía đông"],answer:2,explain:"Mặt Trời mọc ở phía đông."},{id:"tnxh1-bau-troi-ban-ngay-11",type:"tf",q:"Mặt Trời lặn ở phía đông.",emoji:"🌇",answer:!1,explain:"Sai. Mặt Trời mọc ở phía đông, lặn ở phía tây."},{id:"tnxh1-bau-troi-ban-ngay-12",type:"tf",q:"Cây xanh không cần ánh sáng Mặt Trời.",emoji:"🌱",answer:!1,explain:"Sai. Cây cần ánh sáng để sống và lớn lên."},{id:"tnxh1-bau-troi-ban-ngay-13",type:"multi",q:"Mặt Trời có ích gì?",emoji:"🌞",options:["Sưởi ấm","Giúp cây xanh lớn lên","Chiếu sáng"],answers:[0,1,2],explain:"Mặt Trời chiếu sáng, sưởi ấm và giúp cây lớn."},{id:"tnxh1-bau-troi-ban-ngay-14",type:"match",q:"Nối hoạt động với lúc trong ngày.",pairs:[["Ngủ dậy, đi học","Buổi sáng"],["Ăn trưa, nghỉ trưa","Buổi trưa"],["Ngắm Mặt Trời lặn","Buổi chiều"]],explain:"Mỗi lúc trong ngày em làm việc khác nhau."},{id:"tnxh1-bau-troi-ban-ngay-15",type:"mc",q:"Mẹ phơi quần áo ngoài nắng để làm gì?",emoji:"👕☀️",options:["Cho quần áo nhanh khô","Cho quần áo ướt hơn","Cho quần áo bẩn thêm"],answer:0,explain:"Nắng làm quần áo nhanh khô."},{id:"tnxh1-bau-troi-ban-ngay-16",type:"tf",q:"Buổi trưa, nắng thường gắt hơn buổi sáng sớm.",emoji:"🌞",answer:!0,explain:"Đúng. Trưa nắng gắt, em đội mũ khi ra ngoài."}]},{questions:[{id:"tnxh1-bau-troi-ban-ngay-17",type:"mc",q:"Buổi trưa nắng gắt, em đi học về. Em cần làm gì?",emoji:"🧢",options:["Bỏ mũ ra cầm trên tay","Đứng giữa trời phơi nắng","Đội mũ, đi chỗ có bóng râm"],answer:2,explain:"Đội mũ, đi chỗ râm giúp em không bị say nắng."},{id:"tnxh1-bau-troi-ban-ngay-18",type:"mc",q:"Muốn phơi quần áo nhanh khô, ta phơi ở đâu?",emoji:"👕",options:["Nơi có nắng, có gió","Trong tủ đóng kín","Dưới gầm giường tối"],answer:0,explain:"Nắng và gió giúp quần áo nhanh khô."},{id:"tnxh1-bau-troi-ban-ngay-19",type:"tf",q:"Đứng ở hiên nhà buổi sáng, Lan thấy Mặt Trời mọc lên. Lúc đó trời đang sáng dần.",emoji:"🌅",answer:!0,explain:"Đúng. Mặt Trời mọc, trời sáng dần."},{id:"tnxh1-bau-troi-ban-ngay-20",type:"tf",q:"Nhìn thẳng vào Mặt Trời giữa trưa tốt cho mắt.",emoji:"😎",answer:!1,explain:"Sai. Nhìn thẳng vào Mặt Trời làm hại mắt."},{id:"tnxh1-bau-troi-ban-ngay-21",type:"order",q:"Sắp xếp các lúc trong ngày.",emoji:"🕐",items:["Buổi sáng","Buổi trưa","Buổi chiều","Buổi tối"],explain:"Sáng, trưa, chiều rồi đến tối."},{id:"tnxh1-bau-troi-ban-ngay-22",type:"multi",q:"Khi ra nắng, em làm gì để bảo vệ mình?",emoji:"☀️",options:["Đứng ngoài nắng thật lâu","Mặc áo dài tay","Uống đủ nước","Đội mũ"],answers:[1,2,3],explain:"Đội mũ, mặc áo dài tay, uống đủ nước để không bị say nắng."},{id:"tnxh1-bau-troi-ban-ngay-23",type:"mc",q:"Chậu cây để trong phòng tối lâu ngày. Em nên làm gì?",emoji:"🪴",options:["Đưa ra chỗ có ánh sáng","Úp kín chậu cây lại","Cất chậu cây vào trong tủ"],answer:0,explain:"Cây cần ánh sáng Mặt Trời."},{id:"tnxh1-bau-troi-ban-ngay-24",type:"fill",q:"Mặt Trời mọc ở phía …",emoji:"🌅",answer:["đông"],loose:!0,explain:"Mặt Trời mọc ở phía đông."}]}],challenge:{questions:[{id:"tnxh1-bau-troi-ban-ngay-25",type:"match",q:"Nối hình ảnh với lời tả.",pairs:[["☀️ Mặt Trời","Chiếu sáng, sưởi ấm"],["☁️ Mây","Trôi trên bầu trời"],["🌅 Bình minh","Mặt Trời mọc"]],explain:"Bầu trời ban ngày có Mặt Trời và mây."},{id:"tnxh1-bau-troi-ban-ngay-26",type:"mc",q:"Buổi sáng, bóng của cái cây ngả về phía nào?",emoji:"🌳",options:["Phía tây, ngược phía Mặt Trời","Không có bóng","Phía đông, cùng phía Mặt Trời"],answer:0,explain:"Buổi sáng Mặt Trời ở phía đông nên bóng ngả về phía tây."},{id:"tnxh1-bau-troi-ban-ngay-27",type:"multi",q:"Điều nào đúng về Mặt Trời?",emoji:"🌞",options:["Mặt Trời mọc lúc nửa đêm","Mặt Trời lặn buổi chiều","Mặt Trời mọc buổi sáng"],answers:[1,2],explain:"Mặt Trời mọc buổi sáng, lặn buổi chiều."},{id:"tnxh1-bau-troi-ban-ngay-28",type:"tf",q:"Nếu không có Mặt Trời, Trái Đất sẽ tối và lạnh.",emoji:"🌍",answer:!0,explain:"Đúng. Mặt Trời cho ánh sáng và hơi ấm."},{id:"tnxh1-bau-troi-ban-ngay-10",type:"mc",q:"Mặt Trời mọc ở phía nào?",emoji:"🌅",options:["Phía tây","Dưới đất","Phía đông"],answer:2,explain:"Mặt Trời mọc ở phía đông."},{id:"tnxh1-bau-troi-ban-ngay-17",type:"mc",q:"Buổi trưa nắng gắt, em đi học về. Em cần làm gì?",emoji:"🧢",options:["Bỏ mũ ra cầm trên tay","Đứng giữa trời phơi nắng","Đội mũ, đi chỗ có bóng râm"],answer:2,explain:"Đội mũ, đi chỗ râm giúp em không bị say nắng."}]},summary:["Ban ngày có Mặt Trời, trời sáng, có mây.","Mặt Trời mọc phía đông vào buổi sáng, lặn phía tây vào buổi chiều."]},{id:"tnxh1-bau-troi-ban-dem",title:"Bầu trời ban đêm",weeks:[32,33],learn:[{title:"Ban đêm",text:"Ban đêm trời tối. Ta có thể thấy Mặt Trăng và các ngôi sao.",example:"🌙 ⭐ 🌌"},{title:"Mặt Trăng",text:"Mặt Trăng có lúc tròn, có lúc khuyết. Có đêm không thấy trăng.",example:"🌕 🌓 🌒"},{title:"Nghỉ ngơi",text:"Ban đêm là lúc mọi người nghỉ ngơi, ngủ để lấy lại sức.",example:"😴 🛏️"}],practice:[{questions:[{id:"tnxh1-bau-troi-ban-dem-01",type:"mc",q:"Ban đêm, ta có thể thấy gì trên bầu trời?",emoji:"🌙⭐",options:["Mặt Trời lúc giữa trưa","Mặt Trăng và các ngôi sao","Cầu vồng bảy màu"],answer:1,explain:"Ban đêm trời quang, ta thấy trăng và sao."},{id:"tnxh1-bau-troi-ban-dem-02",type:"mc",q:"Ban đêm, mọi người thường làm gì?",emoji:"😴",options:["Đi học ở trường","Phơi lúa","Nghỉ ngơi, đi ngủ"],answer:2,explain:"Ban đêm là lúc nghỉ ngơi, đi ngủ."},{id:"tnxh1-bau-troi-ban-dem-03",type:"tf",q:"Ban đêm trời sáng hơn ban ngày.",emoji:"🌌",answer:!1,explain:"Sai. Ban đêm không có ánh sáng Mặt Trời nên trời tối hơn."},{id:"tnxh1-bau-troi-ban-dem-04",type:"tf",q:"Mặt Trăng lúc nào cũng tròn.",emoji:"🌓",answer:!1,explain:"Sai. Mặt Trăng có lúc tròn, có lúc khuyết."},{id:"tnxh1-bau-troi-ban-dem-05",type:"match",q:"Nối hình với tên gọi.",pairs:[["🌕","Trăng tròn"],["🌙","Trăng khuyết"],["⭐","Ngôi sao"]],explain:"Ban đêm ta thấy trăng và sao."},{id:"tnxh1-bau-troi-ban-dem-06",type:"multi",q:"Bầu trời ban đêm có thể có gì?",emoji:"🌌",options:["Mặt Trăng","Mây","Sao","Mặt Trời đang chiếu sáng"],answers:[0,1,2],explain:"Ban đêm có thể thấy trăng, sao, mây. Mặt Trời không chiếu sáng ban đêm."},{id:"tnxh1-bau-troi-ban-dem-07",type:"mc",q:"Ban đêm trời có mây dày, ta có thể thấy sao không?",emoji:"☁️🌙",options:["Khó thấy sao","Thấy rất rõ","Thấy sao to như Mặt Trời"],answer:0,explain:"Mây dày che khuất nên khó thấy sao."},{id:"tnxh1-bau-troi-ban-dem-08",type:"tf",q:"Đêm trời quang, ta có thể nhìn thấy nhiều ngôi sao.",emoji:"✨",answer:!0,explain:"Đúng. Trời quang không mây, sao hiện rõ."}]},{questions:[{id:"tnxh1-bau-troi-ban-dem-09",type:"mc",q:"Vì sao ban đêm trời tối?",emoji:"🌑",options:["Vì mọi người đều đi ngủ","Vì không có ánh sáng Mặt Trời","Vì đèn đường đã bị tắt hết"],answer:1,explain:"Ban đêm không có ánh sáng Mặt Trời nên trời tối."},{id:"tnxh1-bau-troi-ban-dem-10",type:"tf",q:"Đêm rằm, trăng thường tròn và sáng.",emoji:"🌕",answer:!0,explain:"Đúng. Đêm rằm trăng tròn, sáng."},{id:"tnxh1-bau-troi-ban-dem-11",type:"multi",q:"Ban đêm, em nên làm gì?",emoji:"🛏️",options:["Ra đường chơi một mình","Đánh răng trước khi ngủ","Đi ngủ đúng giờ"],answers:[1,2],explain:"Ban đêm em vệ sinh và đi ngủ đúng giờ."},{id:"tnxh1-bau-troi-ban-dem-12",type:"mc",q:"Ban đêm, nhà em dùng gì để thắp sáng?",emoji:"💡",options:["Bóng đèn điện","Ánh cầu vồng","Ánh Mặt Trời"],answer:0,explain:"Ban đêm ta bật đèn điện để thắp sáng."},{id:"tnxh1-bau-troi-ban-dem-13",type:"match",q:"Nối lúc trong ngày với bầu trời.",pairs:[["Ban ngày","Có Mặt Trời chiếu sáng"],["Ban đêm","Có thể thấy trăng, sao"],["Lúc hoàng hôn","Mặt Trời lặn"]],explain:"Bầu trời ban ngày và ban đêm khác nhau."},{id:"tnxh1-bau-troi-ban-dem-14",type:"tf",q:"Ban đêm, đường phố tối nên cần có đèn đường.",emoji:"🛣️💡",answer:!0,explain:"Đúng. Đèn đường giúp mọi người đi lại an toàn."},{id:"tnxh1-bau-troi-ban-dem-15",type:"mc",q:"Ngôi sao trên bầu trời trông như thế nào?",emoji:"✨",options:["Màu xanh lá cây","Nhỏ, lấp lánh","To như quả bóng"],answer:1,explain:"Nhìn từ xa, sao trông nhỏ và lấp lánh."},{id:"tnxh1-bau-troi-ban-dem-16",type:"tf",q:"Ban đêm, ai cũng phải đi làm như ban ngày.",emoji:"🌙",answer:!1,explain:"Sai. Ban đêm đa số mọi người nghỉ ngơi, chỉ một số người làm việc."}]},{questions:[{id:"tnxh1-bau-troi-ban-dem-17",type:"mc",q:"Đêm Trung thu, trăng như thế nào?",emoji:"🌕🏮",options:["Khuyết như lưỡi liềm","Tròn và sáng","Không có trăng"],answer:1,explain:"Trung thu vào đêm rằm, trăng tròn và sáng."},{id:"tnxh1-bau-troi-ban-dem-18",type:"mc",q:"Buổi tối Vy muốn ngắm sao. Vy nên ngắm cùng ai?",emoji:"🔭",options:["Một mình ngoài đường","Một mình trên mái nhà","Cùng bố mẹ, ở sân nhà"],answer:2,explain:"Ngắm sao cùng người lớn ở nơi an toàn."},{id:"tnxh1-bau-troi-ban-dem-19",type:"tf",q:"Minh thức khuya ngắm sao, sáng hôm sau dậy rất mệt. Minh nên đi ngủ sớm hơn.",emoji:"😴",answer:!0,explain:"Đúng. Ngủ đủ giấc giúp Minh khỏe."},{id:"tnxh1-bau-troi-ban-dem-20",type:"tf",q:"Ban đêm, bóng tối giúp em đọc sách rõ hơn.",emoji:"📖",answer:!1,explain:"Sai. Em cần bật đèn đủ sáng khi đọc sách."},{id:"tnxh1-bau-troi-ban-dem-21",type:"order",q:"Sắp xếp các việc buổi tối.",emoji:"🌙",items:["Ăn tối cùng gia đình","Học bài","Đánh răng","Đi ngủ"],explain:"Ăn tối, học bài, đánh răng rồi đi ngủ."},{id:"tnxh1-bau-troi-ban-dem-22",type:"multi",q:"Điều nào khác nhau giữa ban ngày và ban đêm?",emoji:"🌞🌙",options:["Ban ngày sáng, ban đêm tối","Ban đêm mọi người thường nghỉ ngơi","Ban ngày có Mặt Trời chiếu sáng"],answers:[0,1,2],explain:"Ban ngày sáng có Mặt Trời; ban đêm tối, mọi người nghỉ ngơi."},{id:"tnxh1-bau-troi-ban-dem-23",type:"mc",q:"Ra ngoài buổi tối, em cần làm gì cho an toàn?",emoji:"🔦",options:["Đi một mình vào chỗ tối","Chơi dưới lòng đường","Đi cùng người lớn"],answer:2,explain:"Buổi tối em đi cùng người lớn."},{id:"tnxh1-bau-troi-ban-dem-24",type:"fill",q:"Ban đêm, ta thấy Mặt Trăng và các ngôi …",emoji:"⭐",answer:["sao"],loose:!0,explain:"Ban đêm trời quang ta thấy trăng và sao."}]}],challenge:{questions:[{id:"tnxh1-bau-troi-ban-dem-25",type:"match",q:"Nối hình dạng Mặt Trăng với tên gọi.",pairs:[["🌕","Trăng tròn"],["🌓","Trăng nửa vầng"],["🌒","Trăng lưỡi liềm"]],explain:"Mặt Trăng thay đổi hình dạng trong tháng."},{id:"tnxh1-bau-troi-ban-dem-26",type:"multi",q:"Ai có thể làm việc vào ban đêm?",emoji:"🌙",options:["Bác bảo vệ","Chú lính cứu hỏa trực","Bác sĩ trực bệnh viện"],answers:[0,1,2],explain:"Bác sĩ trực, bảo vệ, lính cứu hỏa có thể làm việc ban đêm."},{id:"tnxh1-bau-troi-ban-dem-27",type:"mc",q:"Vì sao ban đêm cần ngủ đủ giấc?",emoji:"😴",options:["Để trời sáng nhanh hơn một chút","Để Mặt Trăng tròn hơn","Để cơ thể nghỉ ngơi, lấy lại sức"],answer:2,explain:"Ngủ đủ giúp cơ thể khỏe, lấy lại sức."},{id:"tnxh1-bau-troi-ban-dem-28",type:"tf",q:"Có đêm ta không nhìn thấy Mặt Trăng.",emoji:"🌑",answer:!0,explain:"Đúng. Có đêm không thấy trăng, hoặc mây che mất trăng."},{id:"tnxh1-bau-troi-ban-dem-12",type:"mc",q:"Ban đêm, nhà em dùng gì để thắp sáng?",emoji:"💡",options:["Bóng đèn điện","Ánh cầu vồng","Ánh Mặt Trời"],answer:0,explain:"Ban đêm ta bật đèn điện để thắp sáng."},{id:"tnxh1-bau-troi-ban-dem-21",type:"order",q:"Sắp xếp các việc buổi tối.",emoji:"🌙",items:["Ăn tối cùng gia đình","Học bài","Đánh răng","Đi ngủ"],explain:"Ăn tối, học bài, đánh răng rồi đi ngủ."}]},summary:["Ban đêm trời tối, có thể thấy Mặt Trăng và sao.","Mặt Trăng có lúc tròn, lúc khuyết.","Ban đêm là lúc nghỉ ngơi."]},{id:"tnxh1-thoi-tiet",title:"Thời tiết",weeks:[33,34],learn:[{title:"Các kiểu thời tiết",text:"Thời tiết có lúc nắng, lúc mưa, lúc có gió, có mây.",example:"☀️ 🌧️ 🌬️ ☁️"},{title:"Nóng và lạnh",text:"Có ngày trời nóng, có ngày trời lạnh.",example:"🥵 🥶"},{title:"Thời tiết thay đổi",text:"Thời tiết có thể thay đổi trong ngày. Em xem dự báo thời tiết để chuẩn bị.",example:"🌤️ ➡️ 🌧️ 📺"}],practice:[{questions:[{id:"tnxh1-thoi-tiet-01",type:"mc",q:"Trời đang mưa. Hình nào đúng?",options:["🌙","🌤️","🌧️"],answer:2,explain:"Hình mây và mưa là trời đang mưa."},{id:"tnxh1-thoi-tiet-02",type:"mc",q:"Trời nắng. Hình nào đúng?",options:["❄️","☀️","🌧️"],answer:1,explain:"Hình Mặt Trời là trời nắng."},{id:"tnxh1-thoi-tiet-03",type:"tf",q:"Thời tiết có lúc nắng, lúc mưa.",emoji:"🌦️",answer:!0,explain:"Đúng. Thời tiết thay đổi: nắng, mưa, gió, mây."},{id:"tnxh1-thoi-tiet-04",type:"tf",q:"Ngày nào thời tiết cũng giống hệt nhau.",emoji:"📅",answer:!1,explain:"Sai. Thời tiết thay đổi từng ngày."},{id:"tnxh1-thoi-tiet-05",type:"match",q:"Nối thời tiết với hình.",pairs:[["Nắng","☀️"],["Mưa","🌧️"],["Có gió","🌬️"],["Nhiều mây","☁️"]],explain:"Mỗi kiểu thời tiết có hình ảnh riêng."},{id:"tnxh1-thoi-tiet-06",type:"multi",q:"Đâu là các kiểu thời tiết?",emoji:"🌦️",options:["Nắng","Gió","Cái bàn","Mưa"],answers:[0,1,3],explain:"Nắng, mưa, gió là thời tiết. Cái bàn là đồ vật."},{id:"tnxh1-thoi-tiet-07",type:"mc",q:"Trời có gió, lá cây như thế nào?",emoji:"🍃",options:["Biến mất","Đứng yên tuyệt đối","Lay động, đung đưa"],answer:2,explain:"Có gió, lá cây đung đưa."},{id:"tnxh1-thoi-tiet-08",type:"tf",q:"Sau cơn mưa, khi có nắng, có thể xuất hiện cầu vồng.",emoji:"🌈",answer:!0,explain:"Đúng. Cầu vồng có thể xuất hiện khi vừa có mưa vừa có nắng."}]},{questions:[{id:"tnxh1-thoi-tiet-09",type:"mc",q:"Làm sao biết trời có gió?",emoji:"🎏",options:["Thấy Mặt Trăng tròn trên trời","Thấy lá cây, cờ bay phấp phới","Thấy sàn nhà sạch sẽ"],answer:1,explain:"Lá cây lay động, cờ bay cho biết có gió."},{id:"tnxh1-thoi-tiet-10",type:"mc",q:"Trước khi mưa, bầu trời thường thế nào?",emoji:"🌩️",options:["Có nhiều mây đen","Trong xanh không mây","Rất nhiều sao"],answer:0,explain:"Mây đen kéo đến là trời sắp mưa."},{id:"tnxh1-thoi-tiet-11",type:"tf",q:"Trời mưa to có thể kèm sấm sét.",emoji:"⛈️",answer:!0,explain:"Đúng. Mưa giông thường có sấm sét."},{id:"tnxh1-thoi-tiet-12",type:"tf",q:"Trời lạnh, em mặc áo cộc tay là ấm nhất.",emoji:"🥶",answer:!1,explain:"Sai. Trời lạnh em mặc áo ấm."},{id:"tnxh1-thoi-tiet-13",type:"match",q:"Nối thời tiết với điều em cảm thấy.",pairs:[["Nắng gắt","Nóng bức"],["Gió mùa lạnh","Lạnh, rét"],["Gió nhẹ","Mát mẻ"]],explain:"Thời tiết làm em cảm thấy khác nhau."},{id:"tnxh1-thoi-tiet-14",type:"multi",q:"Dấu hiệu nào cho biết trời sắp mưa?",emoji:"🌩️",options:["Có sấm","Trời quang, nhiều nắng","Gió thổi mạnh","Mây đen kéo đến"],answers:[0,2,3],explain:"Mây đen, gió mạnh, có sấm là dấu hiệu trời sắp mưa."},{id:"tnxh1-thoi-tiet-15",type:"mc",q:"Em biết thời tiết ngày mai nhờ đâu?",emoji:"📺",options:["Nhìn vào chiếc đồng hồ","Đếm các ngón tay","Nghe dự báo thời tiết"],answer:2,explain:"Dự báo thời tiết cho biết thời tiết sắp tới."},{id:"tnxh1-thoi-tiet-16",type:"tf",q:"Thời tiết có thể thay đổi ngay trong một ngày.",emoji:"🌤️🌧️",answer:!0,explain:"Đúng. Sáng nắng, chiều có thể mưa."}]},{questions:[{id:"tnxh1-thoi-tiet-17",type:"mc",q:"Mây đen kéo đến, gió thổi mạnh. Chuyện gì có thể xảy ra?",emoji:"🌧️",options:["Trời sắp có tuyết rơi khắp nơi","Mặt Trời sắp mọc","Trời sắp mưa"],answer:2,explain:"Mây đen, gió mạnh báo trời sắp mưa."},{id:"tnxh1-thoi-tiet-18",type:"mc",q:"Mẹ đang phơi quần áo, trời sắp mưa. Em giúp mẹ việc gì?",emoji:"👕🌧️",options:["Phơi thêm quần áo","Đóng cửa đi ngủ","Cất quần áo vào nhà"],answer:2,explain:"Em giúp mẹ cất quần áo để không bị ướt."},{id:"tnxh1-thoi-tiet-19",type:"tf",q:"Nghe dự báo ngày mai mưa, Nam chuẩn bị áo mưa. Nam làm đúng.",emoji:"🧥",answer:!0,explain:"Đúng. Nam chuẩn bị trước để không bị ướt."},{id:"tnxh1-thoi-tiet-20",type:"tf",q:"Trời có sấm sét, Chi chạy ra cánh đồng chơi. Chi làm đúng.",emoji:"⚡",answer:!1,explain:"Sai. Có sấm sét, Chi phải vào nhà trú."},{id:"tnxh1-thoi-tiet-21",type:"order",q:"Sắp xếp diễn biến của một cơn mưa.",emoji:"🌦️",items:["Mây đen kéo đến","Trời đổ mưa","Mưa tạnh","Trời quang trở lại"],explain:"Mây đen kéo đến, mưa, tạnh rồi trời quang."},{id:"tnxh1-thoi-tiet-22",type:"multi",q:"Ngày nắng đẹp, em có thể làm gì?",emoji:"☀️",options:["Chơi ở sân có bóng râm","Đi dã ngoại cùng gia đình","Phơi quần áo"],answers:[0,1,2],explain:"Ngày nắng đẹp hợp để phơi đồ, đi chơi, chơi ở chỗ râm."},{id:"tnxh1-thoi-tiet-23",type:"mc",q:"Trời gió to, em không nên làm gì?",emoji:"🌳💨",options:["Đi vào trong nhà","Đứng dưới cây to","Đóng cửa sổ lại"],answer:1,explain:"Gió to có thể làm gãy cành cây. Không đứng dưới cây to."},{id:"tnxh1-thoi-tiet-24",type:"fill",q:"Trời có nhiều mây đen là sắp có …",emoji:"🌧️",answer:["mưa"],loose:!0,explain:"Mây đen báo hiệu trời sắp mưa."}]}],challenge:{questions:[{id:"tnxh1-thoi-tiet-25",type:"match",q:"Nối dấu hiệu với thời tiết.",pairs:[["Lá cây lay động","Có gió"],["Mây đen kéo đến","Sắp mưa"],["Mặt Trời chói chang","Trời nắng"],["Vừa mưa vừa nắng","Có thể có cầu vồng"]],explain:"Quan sát dấu hiệu để biết thời tiết."},{id:"tnxh1-thoi-tiet-26",type:"multi",q:"Vì sao cần nghe dự báo thời tiết?",emoji:"📺",options:["Để mang ô, áo mưa khi cần","Để chuẩn bị quần áo phù hợp","Để Mặt Trời mọc sớm hơn"],answers:[0,1],explain:"Biết thời tiết để chuẩn bị quần áo, áo mưa phù hợp."},{id:"tnxh1-thoi-tiet-27",type:"mc",q:"Ngày gió mùa lạnh, buổi sáng em ra ngoài cần gì?",emoji:"🧣",options:["Kính bơi và phao","Áo ấm, khăn quàng cổ","Áo cộc tay, quần đùi"],answer:1,explain:"Trời lạnh em mặc áo ấm, quàng khăn."},{id:"tnxh1-thoi-tiet-28",type:"tf",q:"Mưa to kéo dài có thể gây ngập đường.",emoji:"🌊",answer:!0,explain:"Đúng. Mưa to, lâu có thể làm ngập đường, em cần cẩn thận."},{id:"tnxh1-thoi-tiet-11",type:"tf",q:"Trời mưa to có thể kèm sấm sét.",emoji:"⛈️",answer:!0,explain:"Đúng. Mưa giông thường có sấm sét."},{id:"tnxh1-thoi-tiet-20",type:"tf",q:"Trời có sấm sét, Chi chạy ra cánh đồng chơi. Chi làm đúng.",emoji:"⚡",answer:!1,explain:"Sai. Có sấm sét, Chi phải vào nhà trú."}]},summary:["Thời tiết có nắng, mưa, gió, mây, nóng, lạnh.","Thời tiết thay đổi; em xem dự báo để chuẩn bị."]},{id:"tnxh1-mac-hop-thoi-tiet",title:"Mặc phù hợp và an toàn theo thời tiết",weeks:[34,35],learn:[{title:"Trời nắng",text:"Trời nắng, em đội mũ, mặc quần áo mỏng, uống đủ nước.",example:"🧢 👕 💧"},{title:"Trời mưa",text:"Trời mưa, em mặc áo mưa hoặc che ô, đi chậm cho khỏi trơn ngã.",example:"🧥 ☂️ 🌧️"},{title:"Trời lạnh",text:"Trời lạnh, em mặc áo ấm, đi tất, quàng khăn.",example:"🧥 🧦 🧣"},{title:"Giông sét",text:"Có sấm sét, em vào nhà trú, không đứng dưới cây cao, không tắm mưa.",example:"⛈️ 🏠 🚫🌳"}],practice:[{questions:[{id:"tnxh1-mac-hop-thoi-tiet-01",type:"mc",q:"Trời mưa, em mang gì khi ra ngoài?",emoji:"☂️",options:["Chiếc quạt giấy","Kính bơi","Áo mưa hoặc ô"],answer:2,explain:"Áo mưa, ô giúp em không bị ướt."},{id:"tnxh1-mac-hop-thoi-tiet-02",type:"mc",q:"Trời lạnh, em mặc gì?",emoji:"🧥",options:["Đồ bơi","Áo cộc tay","Áo ấm"],answer:2,explain:"Trời lạnh em mặc áo ấm."},{id:"tnxh1-mac-hop-thoi-tiet-03",type:"mc",q:"Trời nắng, em đội gì khi ra ngoài?",emoji:"🧢",options:["Nồi","Mũ","Không đội gì"],answer:1,explain:"Đội mũ giúp che nắng."},{id:"tnxh1-mac-hop-thoi-tiet-04",type:"tf",q:"Trời rét, em mặc áo cộc và đi chân đất.",emoji:"🥶",answer:!1,explain:"Sai. Trời rét, em quàng khăn, đi tất để giữ ấm."},{id:"tnxh1-mac-hop-thoi-tiet-05",type:"tf",q:"Trời mưa, em chạy thật nhanh trên sân trơn.",emoji:"🌧️",answer:!1,explain:"Sai. Sân trơn dễ ngã, em đi chậm."},{id:"tnxh1-mac-hop-thoi-tiet-06",type:"match",q:"Nối thời tiết với đồ dùng.",pairs:[["☀️ Nắng","Mũ"],["🌧️ Mưa","Áo mưa"],["❄️ Rét","Áo ấm"]],explain:"Mỗi kiểu thời tiết cần đồ dùng phù hợp."},{id:"tnxh1-mac-hop-thoi-tiet-07",type:"multi",q:"Đồ dùng nào giúp em giữ ấm?",emoji:"🧤",options:["Quạt điện","Áo len","Khăn quàng cổ","Găng tay"],answers:[1,2,3],explain:"Áo len, khăn, găng tay giúp giữ ấm. Quạt làm mát."},{id:"tnxh1-mac-hop-thoi-tiet-08",type:"tf",q:"Có sấm sét, em nên vào trong nhà trú.",emoji:"⛈️🏠",answer:!0,explain:"Đúng. Ở trong nhà an toàn hơn khi có sấm sét."}]},{questions:[{id:"tnxh1-mac-hop-thoi-tiet-09",type:"mc",q:"Vì sao trời lạnh cần mặc ấm?",emoji:"🤧",options:["Để không bị cảm lạnh","Để chạy nhanh hơn","Để áo đẹp hơn"],answer:0,explain:"Mặc ấm giúp em không bị ốm vì lạnh."},{id:"tnxh1-mac-hop-thoi-tiet-10",type:"mc",q:"Có sấm sét, em không nên làm gì?",emoji:"⚡🌳",options:["Đứng dưới gốc cây cao","Tránh xa chỗ có nước","Vào nhà trú"],answer:0,explain:"Đứng dưới cây cao khi có sét rất nguy hiểm."},{id:"tnxh1-mac-hop-thoi-tiet-11",type:"tf",q:"Trời nắng nóng, em uống đủ nước.",emoji:"💧",answer:!0,explain:"Đúng. Uống đủ nước giúp em không bị mệt vì nóng."},{id:"tnxh1-mac-hop-thoi-tiet-12",type:"tf",q:"Đi dưới trời mưa không mặc áo mưa sẽ không sao.",emoji:"🌧️",answer:!1,explain:"Sai. Bị ướt mưa dễ bị cảm."},{id:"tnxh1-mac-hop-thoi-tiet-13",type:"match",q:"Nối đồ dùng với lúc cần dùng.",pairs:[["☂️ Ô","Khi trời mưa"],["🧢 Mũ","Khi trời nắng"],["🧣 Khăn quàng","Khi trời rét"]],explain:"Chọn đồ dùng theo thời tiết."},{id:"tnxh1-mac-hop-thoi-tiet-14",type:"multi",q:"Trời mưa giông, việc nào nguy hiểm?",emoji:"⛈️",options:["Thả diều","Trú dưới cây to","Tắm mưa ngoài sân","Ở trong nhà đóng cửa"],answers:[0,1,2],explain:"Tắm mưa, trú dưới cây to, thả diều khi có sét đều nguy hiểm."},{id:"tnxh1-mac-hop-thoi-tiet-15",type:"mc",q:"Trời nóng, em nên mặc quần áo thế nào?",emoji:"👕",options:["Mặc nhiều lớp áo","Áo len thật dày","Mỏng, thoáng mát"],answer:2,explain:"Trời nóng mặc quần áo mỏng, thoáng."},{id:"tnxh1-mac-hop-thoi-tiet-16",type:"tf",q:"Trời lạnh, đi học về em nên rửa chân tay bằng nước ấm.",emoji:"🚿",answer:!0,explain:"Đúng. Nước ấm giúp em không bị lạnh."}]},{questions:[{id:"tnxh1-mac-hop-thoi-tiet-17",type:"mc",q:"Sáng nay trời rét, An chỉ mặc áo cộc tay. An nên làm gì?",emoji:"🥶",options:["Cởi bớt áo ra","Mặc thêm áo ấm","Đi chân đất ra sân"],answer:1,explain:"Trời rét, An cần mặc thêm áo ấm."},{id:"tnxh1-mac-hop-thoi-tiet-18",type:"mc",q:"Đang đi học về thì trời mưa to có sấm sét. Em làm gì?",emoji:"⛈️",options:["Chạy ra giữa cánh đồng trống trải","Đứng trú dưới một cây to","Vào nơi có mái che an toàn để trú"],answer:2,explain:"Em vào nơi có mái che chắc chắn, không trú dưới cây."},{id:"tnxh1-mac-hop-thoi-tiet-19",type:"tf",q:"Dũng bị ướt mưa, về nhà Dũng thay quần áo khô ngay. Dũng làm đúng.",emoji:"👕",answer:!0,explain:"Đúng. Thay đồ khô giúp Dũng không bị cảm."},{id:"tnxh1-mac-hop-thoi-tiet-20",type:"tf",q:"Trời nắng gắt buổi trưa, Hà ra sân chơi không đội mũ. Hà làm đúng.",emoji:"☀️",answer:!1,explain:"Sai. Hà có thể bị say nắng. Hà nên đội mũ, chơi chỗ râm."},{id:"tnxh1-mac-hop-thoi-tiet-21",type:"order",q:"Sắp xếp các việc khi đi học về bị ướt mưa.",emoji:"🌧️",items:["Cởi áo mưa","Lau khô người","Thay quần áo khô","Uống một cốc nước ấm"],explain:"Cởi áo mưa, lau khô, thay đồ rồi uống nước ấm."},{id:"tnxh1-mac-hop-thoi-tiet-22",type:"multi",q:"Ngày mai trời mưa. Em chuẩn bị gì?",emoji:"☔",options:["Kính râm đi biển","Áo mưa","Ô","Dép quai hậu"],answers:[1,2,3],explain:"Áo mưa, ô, dép quai hậu giúp em đi mưa an toàn."},{id:"tnxh1-mac-hop-thoi-tiet-23",type:"mc",q:"Trời rất nóng, em thấy chóng mặt khi chơi ngoài nắng. Em làm gì?",emoji:"🥵",options:["Đứng tiếp ngoài trời phơi nắng","Cố chạy nhảy tiếp đến hết giờ chơi","Vào chỗ mát, uống nước, báo người lớn"],answer:2,explain:"Có thể em bị say nắng. Vào chỗ mát và báo người lớn."},{id:"tnxh1-mac-hop-thoi-tiet-24",type:"fill",q:"Trời mưa, em mặc áo … khi ra ngoài.",emoji:"🧥",answer:["mưa"],loose:!0,explain:"Áo mưa giúp em không bị ướt."}]}],challenge:{questions:[{id:"tnxh1-mac-hop-thoi-tiet-25",type:"match",q:"Nối tình huống với cách giữ an toàn.",pairs:[["Có sấm sét","Vào nhà trú"],["Nắng gắt","Đội mũ, uống nước"],["Trời rét","Mặc áo ấm"],["Sân trơn sau mưa","Đi chậm"]],explain:"Mỗi kiểu thời tiết có cách giữ an toàn."},{id:"tnxh1-mac-hop-thoi-tiet-26",type:"multi",q:"Mặc quần áo phù hợp thời tiết giúp gì cho em?",emoji:"😊",options:["Vui chơi, học tập tốt hơn","Cảm thấy dễ chịu","Không bị ốm"],answers:[0,1,2],explain:"Mặc phù hợp giúp em khỏe, dễ chịu và học tốt."},{id:"tnxh1-mac-hop-thoi-tiet-27",type:"mc",q:"Vì sao không đứng dưới cây cao khi có sét?",emoji:"⚡",options:["Vì sét dễ đánh vào cây cao","Vì cây cao sắp cho quả ngọt","Vì dưới cây rất mát"],answer:0,explain:"Sét hay đánh vào chỗ cao như cây cao, rất nguy hiểm."},{id:"tnxh1-mac-hop-thoi-tiet-28",type:"tf",q:"Thời tiết thay đổi, em cần thay đổi trang phục cho phù hợp.",emoji:"👕🧥",answer:!0,explain:"Đúng. Em chọn trang phục theo thời tiết."},{id:"tnxh1-mac-hop-thoi-tiet-10",type:"mc",q:"Có sấm sét, em không nên làm gì?",emoji:"⚡🌳",options:["Đứng dưới gốc cây cao","Tránh xa chỗ có nước","Vào nhà trú"],answer:0,explain:"Đứng dưới cây cao khi có sét rất nguy hiểm."},{id:"tnxh1-mac-hop-thoi-tiet-18",type:"mc",q:"Đang đi học về thì trời mưa to có sấm sét. Em làm gì?",emoji:"⛈️",options:["Chạy ra giữa cánh đồng trống trải","Đứng trú dưới một cây to","Vào nơi có mái che an toàn để trú"],answer:2,explain:"Em vào nơi có mái che chắc chắn, không trú dưới cây."}]},summary:["Trời nắng đội mũ, trời mưa mặc áo mưa, trời lạnh mặc ấm.","Có sấm sét, em vào nhà trú, không đứng dưới cây cao."]}]}],c={grade:1,subject:n,title:i,review:t,topics:h};export{c as default,a as grade,t as review,n as subject,i as title,h as topics};
